int main() {
    int n = 9;
    int square[n][n];
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            square[i][j] = n * (((i + 1) + (j + 1) - 1 + (n >> 1)) % n) + (((i + 1) + (2 * (j + 1)) - 2) % n) + 1;
            printf("%3d ", square[i][j]);
        }
        printf("\n");
    }
    int sum = n * (((n * n) + 1) / 2);
    printf("The sum of the square is %d.\n", sum);
