#define MAX_LINE 1024

int main(int argc, char *argv[])
{
    int fd;
    char line[MAX_LINE];
    time_t t;
    struct tm *tmp;
    char buf[MAX_LINE];
    int i;

    if (argc == 1) {
        fd = open("notes.txt", O_RDONLY);
        if (fd == -1) {
            if (errno == ENOENT) {
                return 0;
            } else {
                perror("open");
                return 1;
            }
        }
        while (read(fd, line, MAX_LINE) > 0) {
            write(STDOUT_FILENO, line, strlen(line));
        }
        close(fd);
    } else {
        fd = open("notes.txt", O_WRONLY | O_APPEND | O_CREAT, 0644);
        if (fd == -1) {
            perror("open");
            return 1;
        }
        t = time(NULL);
        tmp = localtime(&t);
        if (strftime(buf, MAX_LINE, "%Y-%m-%dT%H:%M:%S", tmp) == 0) {
            perror("strftime");
            return 1;
        }
        write(fd, buf, strlen(buf));
        write(fd, "\n\t", 2);
        for (i = 1; i < argc; i++) {
            write(fd, argv[i], strlen(argv[i]));
            if (i < argc - 1) {
                write(fd, " ", 1);
            }
        }
        write(fd, "\n", 1);
        close(fd);
    }
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <math.h>
 
typedef struct {
    int64_t *p;
    int64_t n;
    int64_t size;
} primes_t;
 
void primes_init(primes_t *primes, int64_t limit)
{
    primes->p = malloc(limit * sizeof(int64_t));
    primes->n = 0;
    primes->size = limit;
}
 
void primes_free(primes_t *primes)
{
    free(primes->p);
}
 
void primes_add(primes_t *primes, int64_t p)
{
    if (primes->n == primes->size) {
        primes->size *= 2;
        primes->p = realloc(primes->p, primes->size * sizeof(int64_t));
    }
    primes->p[primes->n++] = p;
}
 
void primes_sieve(primes_t *primes, int64_t limit)
{
    bool *c = calloc(limit, sizeof(bool));
    int64_t p = 2;
    for (;;) {
        primes_add(primes, p);
        int64_t p2 = p * p;
        if (p2 >= limit)
            break;
        for (int64_t i = p2; i < limit; i += p)
            c[i] = true;
        for (;;) {
            p++;
            if (!c[p])
                break;
        }
    }
    for (p++; p < limit; p++)
        if (!c[p])
            primes_add(primes, p);
    free(c);
}
 
int main(void)
{
    primes_t primes;
    primes_init(&primes, 4000);
    primes_sieve(&primes, 4000);
    int64_t pm = 1;
    int px = 0;
    int nx = 0;
    for (int i = 0; i < primes.n; i++) {
        int64_t p = primes.p[i];
        pm *= p;
        px++;
        if (isprime(pm + 1) || isprime(pm - 1)) {
            printf("%d ", px);
            nx++;
            if (nx == 20) {
                printf("\n");
                nx = 0;
            }
        }
    }
    primes_free(&primes);
    return 0;
}
 
bool isprime(int64_t n)
{
    if (n < 2)
        return false;
    if (n == 2)
        return true;
    if (n % 2 == 0)
        return false;
    for (int64_t i = 3; i <= sqrt(n); i += 2)
        if (n % i == 0)
            return false;
    return true;
}

