void primeFactors( unsigned n, unsigned* r ) {
    int f = 2; if( n == 1 ) r[0] = 1;
    else {
        while( true ) {
            if(!( n % f ) ) {
                r[0] = f;
                n /= f; if( n == 1 ) return;
            }
            else f++;
        }
    }
}
unsigned sumDigits( unsigned n ) {
    unsigned sum = 0, m;
    while( n ) {
        m = n % 10; sum += m;
        n -= m; n /= 10;
    }
    return sum;
}
unsigned sumDigits( unsigned* v ) {
    unsigned sum = 0;
    for( unsigned i = 0; v[i]!= 0; i++ ) {
        sum += sumDigits( v[i] );
    }
    return sum;
}
void listAllSmithNumbers( unsigned n ) {
    unsigned* pf = (unsigned*)malloc( n * sizeof( unsigned ) );
    for( unsigned i = 4; i < n; i++ ) {
        primeFactors( i, pf ); if( pf[0] == 0 ) continue;
        if( sumDigits( i ) == sumDigits( pf ) )
            printf( "%4d ", i );
        memset( pf, 0, n * sizeof( unsigned ) );
    }
    printf( "\n\n" );
    free( pf );
}
int main( int argc, char* argv[] ) {
    listAllSmithNumbers( 10000 );
    return 0;
}

#include <stdio.h>
#include <math.h>
 
int factors(int x)
{
    int factors[100];
    int i = 2;
    int s = (int)sqrt(x);
    int j = 0;
    while (i < s)
    {
        if (x % i == 0)
        {
            factors[j] = i;
            j++;
            x = x / i;
            s = (int)sqrt(x);
        }
        i++;
    }
    factors[j] = x;
    return j;
}
 
int main()
{
    int i;
    int fermat;
    int fac[100];
    int j;
    printf("First 10 Fermat numbers:\n");
    for (i = 0; i < 10; i++)
    {
        fermat = pow(2, pow(2, i)) + 1;
        printf("F%c = %d\n", i + 0x2080, fermat);
    }
    printf("\nFactors of first few Fermat numbers:\n");
    for (i = 0; i < 10; i++)
    {
        fermat = pow(2, pow(2, i)) + 1;
        j = factors(fermat);
        if (j == 0)
        {
            printf("F%c -> IS PRIME\n", i + 0x2080);
        }
        else
        {
            printf("F%c -> FACTORS: ", i + 0x2080);
            for (int k = 0; k < j; k++)
            {
                printf("%d ", fac[k]);
            }
            printf("\n");
        }
    }
    return 0;
}

#include <stdio.h>
 
double f(double x) {
    return x * x * x - 3 * x * x + 2 * x;
}
 
int main() {
    double step = 0.001;
    double start = -1;
    double stop = 3;
 
    int sign = f(start) > 0;
 
    double x = start;
    while (x <= stop) {
        double value = f(x);
 
        if (value == 0) {
            // We hit a root
            printf("Root found at %f\n", x);
        } else if ((value > 0)!= sign) {
            // We passed a root
            printf("Root found near %f\n", x);
        }
 
        // Update our sign
        sign = value > 0;
 
        x += step;
    }
 
    return 0;
}

