#define MAX_PRIMES 64000
 
int sieve(int limit, int *primes) {
    int i, j, p, p2;
    int count = 0;
    char *c = (char *) calloc(limit + 1, sizeof(char));
    for (i = 3; i <= limit; i += 2) {
        if (c[i]) continue;
        primes[count++] = i;
        p2 = i * i;
        if (p2 > limit) continue;
        for (j = p2; j <= limit; j += 2 * i) c[j] = 1;
    }
    free(c);
    return count;
}
 
int findPeriod(int n) {
    int r = 1;
    int i;
    for (i = 1; i < n; i++) r = (10 * r) % n;
    int rr = r;
    int period = 0;
    while (1) {
        r = (10 * r) % n;
        period++;
        if (r == rr) break;
    }
    return period;
}
 
int main() {
    int primes[MAX_PRIMES];
    int longPrimes[MAX_PRIMES];
    int numbers[] = {500, 1000, 2000, 4000, 8000, 16000, 32000, 64000};
    int totals[8];
    int count = 0;
    int index = 0;
    int i;
    int primeCount = sieve(64000, primes);
    for (i = 0; i < primeCount; i++) {
        if (findPeriod(primes[i]) == primes[i] - 1) {
            longPrimes[count++] = primes[i];
        }
        if (primes[i] > numbers[index]) {
            totals[index] = count;
            index++;
        }
    }
    totals[7] = count;
    printf("The long primes up to 500 are:\n");
    for (i = 0; i < totals[0]; i++) {
        printf("%d ", longPrimes[i]);
    }
    printf("\n\nThe number of long primes up to:\n");
    for (i = 0; i < 8; i++) {
        printf("  %5d is %d\n", numbers[i], totals[i]);
    }
    return 0;
}

