#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <gmp.h>
 
typedef struct node {
	int val;
	struct node *next;
} node;
 
node *sequence = NULL;
 
void genSeq(int n){
	node *cur = sequence;
	for(int conIdx = 1; conIdx < n; conIdx++){
		int consider = cur->val;
		int pre = cur->next->val;
		cur->next = (node *)malloc(sizeof(node));
		cur->next->val = consider + pre;
		cur->next->next = (node *)malloc(sizeof(node));
		cur->next->next->val = consider;
		cur->next->next->next = NULL;
		cur = cur->next->next;
	}
}
 
void printSeq(int n){
	node *cur = sequence;
	for(int i = 0; i < n; i++){
		printf("%d ", cur->val);
		cur = cur->next;
	}
	printf("\n");
}
 
int main(){
	sequence = (node *)malloc(sizeof(node));
	sequence->val = 1;
	sequence->next = (node *)malloc(sizeof(node));
	sequence->next->val = 1;
	sequence->next->next = NULL;
	genSeq(1200);
	printSeq(15);
	for(int i = 1; i <= 10; i++){
		node *cur = sequence;
		int idx = 1;
		while(cur->val!= i){
			cur = cur->next;
			idx++;
		}
		printf("First occurrence of %d is at %d\n", i, idx);
	}
	node *cur = sequence;
	int idx = 1;
	while(cur->val!= 100){
		cur = cur->next;
		idx++;
	}
	printf("First occurrence of 100 is at %d\n", idx);
	bool failure = false;
	cur = sequence;
	for(int i = 0; i < 999; i++){
		mpz_t a, b;
		mpz_init_set_ui(a, cur->val);
		mpz_init_set_ui(b, cur->next->val);
		mpz_gcd(a, a, b);
		failure |= mpz_cmp_ui(a, 1);
		cur = cur->next;
	}
	printf("All GCDs are%s 1\n", failure? " not" : "");
	return 0;
}

#include <stdio.h>
#include <stdlib.h>
 
typedef struct {
    unsigned int n0;
    unsigned int n1;
    unsigned int add;
} Leonardo;
 
unsigned int leonardo_next(Leonardo *leonardo) {
    unsigned int n = leonardo->n0;
    leonardo->n0 = leonardo->n1;
    leonardo->n1 += n + leonardo->add;
    return n;
}
 
int main() {
    Leonardo leonardo = {1, 1, 1};
    printf("First 25 Leonardo numbers:\n");
    for (int i = 0; i < 25; i++) {
        printf("%u ", leonardo_next(&leonardo));
    }
    printf("\n");
    leonardo.n0 = 0;
    leonardo.n1 = 1;
    leonardo.add = 0;
    printf("First 25 Fibonacci numbers:\n");
    for (int i = 0; i < 25; i++) {
        printf("%u ", leonardo_next(&leonardo));
    }
    printf("\n");
    return 0;
}

#include <stdio.h>
#include <math.h>
 
int isPrime(int n) {
    int i;
    for (i = 2; i <= sqrt(n); i++) {
        if (n % i == 0) {
            return 0;
        }
    }
    return 1;
}
 
int isWeiferich(int p) {
    if (!isPrime(p)) {
        return 0;
    }
    int q = 1;
    int p2 = p * p;
    while (p > 1) {
        q = (2 * q) % p2;
        p--;
    }
    if (q == 1) {
        return 1;
    } else {
        return 0;
    }
}
 
int main() {
    printf("Wieferich primes less than 5000: \n");
    int i;
    for (i = 2; i < 5001; i++) {
        if (isWeiferich(i)) {
            printf("%d\n", i);
        }
    }
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int levenshtein(char *a, char *b) {
  int t[strlen(b) + 1];
  int u[strlen(b) + 1];
  int i, j, m = strlen(a), n = strlen(b);
  if (!m) { return n; }
  if (!n) { return m; }
  for (j = 0; j <= n; j++) { t[j] = j; }
  for (i = 1; i <= m; i++) {
    for (u[0] = i, j = 1; j <= n; j++) {
      u[j] = a[i - 1] == b[j - 1]? t[j - 1] : (t[j - 1] < t[j]? t[j - 1] : t[j]) < u[j - 1]? (t[j - 1] < t[j]? t[j - 1] : t[j]) : u[j - 1] + 1;
    }
    memcpy(t, u, sizeof(int) * (n + 1));
  }
  return u[n];
}

int main(int argc, char *argv[]) {
  char *a = argv[1];
  char *b = argv[2];
  int d = levenshtein(a, b);
  printf("levenshtein(\"%s\",\"%s\") = %d\n", a, b, d);
  return 0;
}

