#include <stdio.h>
#include <stdlib.h>
#include <gmp.h>
 
#define ZERO 0
#define ONE 1
#define TWO 2
#define THREE 3
#define FOUR 4
#define SEVEN 7
#define TEN 10
 
void calcPi() {
    mpz_t nn;
    mpz_t nr;
    mpz_t q;
    mpz_t r;
    mpz_t t;
    mpz_t k;
    mpz_t n;
    mpz_t l;
    int first = 1;
    mpz_init_set_ui(q, ONE);
    mpz_init_set_ui(r, ZERO);
    mpz_init_set_ui(t, ONE);
    mpz_init_set_ui(k, ONE);
    mpz_init_set_ui(n, THREE);
    mpz_init_set_ui(l, THREE);
    while (1) {
        if (mpz_mul_ui(nn, q, FOUR) + mpz_sub(nr, r, mpz_mul(nn, n, t)) < mpz_mul(n, t)) {
            if (first) { printf("."); first = 0; }
            mpz_mul_ui(nr, r, TEN);
            mpz_submul_ui(nr, n, TEN);
            mpz_mul_ui(nn, q, TEN);
            mpz_mul_ui(nn, nn, THREE);
            mpz_addmul_ui(nn, r, TEN);
            mpz_tdiv_q(n, nn, t);
            mpz_mul_ui(q, q, TEN);
            mpz_set(r, nr);
        }
        else {
            mpz_mul_ui(nr, q, TWO);
            mpz_addmul_ui(nr, r, TWO);
            mpz_mul(nn, q, SEVEN);
            mpz_mul(nn, nn, k);
            mpz_add_ui(nn, nn, ONE);
            mpz_mul(nn, nn, l);
            mpz_tdiv_q(nn, nn, t);
            mpz_mul(nn, nn, l);
            mpz_add_ui(l, l, TWO);
            mpz_add_ui(k, k, ONE);
            mpz_set(n, nn);
            mpz_set(r, nr);
        }
        gmp_printf("%Zd", n);
    }
}
 
int main(int argc, char **argv) {
    calcPi();
    return 0;
}

#include <stdio.h>
#include <limits.h>
#include <stdlib.h>
 
int turn(int base, int n) {
    int sum = 0;
    while (n!= 0) {
        int rem = n % base;
        n = n / base;
        sum += rem;
    }
    return sum % base;
}
 
void fairshare(int base, int count) {
    printf("Base %2d:", base);
    for (int i = 0; i < count; i++) {
        int t = turn(base, i);
        printf(" %2d", t);
    }
    printf("\n");
}
 
void turnCount(int base, int count) {
    int *cnt = (int *)malloc(base * sizeof(int));
    for (int i = 0; i < base; i++) {
        cnt[i] = 0;
    }
 
    for (int i = 0; i < count; i++) {
        int t = turn(base, i);
        cnt[t]++;
    }
 
    int minTurn = INT_MAX;
    int maxTurn = INT_MIN;
    int portion = 0;
    for (int i = 0; i < base; i++) {
        if (cnt[i] > 0) {
            portion++;
        }
        if (cnt[i] < minTurn) {
            minTurn = cnt[i];
        }
        if (cnt[i] > maxTurn) {
            maxTurn = cnt[i];
        }
    }
 
    printf("  With %d people: ", base);
    if (0 == minTurn) {
        printf("Only %d have a turn\n", portion);
    } else if (minTurn == maxTurn) {
        printf("%d\n", minTurn);
    } else {
        printf("%d or %d\n", minTurn, maxTurn);
    }
 
    free(cnt);
}
 
int main() {
    fairshare(2, 25);
    fairshare(3, 25);
    fairshare(5, 25);
    fairshare(11, 25);
 
    printf("How many times does each get a turn in 50000 iterations?\n");
    turnCount(191, 50000);
    turnCount(1377, 50000);
    turnCount(49999, 50000);
    turnCount(50000, 50000);
    turnCount(50001, 50000);
 
    return 0;
}

