#include <stdbool.h>
#include <string.h>
 
bool strings_are_equal(const char *seq[]) {
    if (seq[0] == NULL) {
        return true;
    } else if (seq[1] == NULL) {
        return true;
    } else {
        const char *x = seq[0];
        const char *y = seq[1];
        if (strcmp(x, y) == 0) {
            const char *tail[] = {seq[2], NULL};
            return strings_are_equal(tail);
        } else {
            return false;
        }
    }
}
 
bool asc_strings(const char *seq[]) {
    if (seq[0] == NULL) {
        return true;
    } else if (seq[1] == NULL) {
        return true;
    } else {
        const char *x = seq[0];
        const char *y = seq[1];
        if (strcmp(x, y) < 0) {
            const char *tail[] = {seq[2], NULL};
            return asc_strings(tail);
        } else {
            return false;
        }
    }
}

int ack(int m, int n) {
	if (m == 0) {
		return n + 1;
	} else {
		if (n == 0) {
			return ack(m - 1, 1);
		} else {
			return ack(m - 1, ack(m, n - 1));
		}
	}
}

#include <stdio.h>
#include <stdlib.h>
 
typedef struct LinkedList {
    int _value;
    struct LinkedList* _next;
} LinkedList;
 
int LinkedList_value(LinkedList* this) {
    return this->_value;
}
void LinkedList_value_set(LinkedList* this, int value) {
    this->_value = value;
}
LinkedList* LinkedList_next(LinkedList* this) {
    return this->_next;
}
void LinkedList_next_set(LinkedList* this, LinkedList* next) {
    this->_next = next;
}
 
LinkedList* createLinkedListFromArray(int* ary, int len) {
    LinkedList* head = (LinkedList*)malloc(sizeof(LinkedList));
    LinkedList_value_set(head, ary[0]);
    LinkedList_next_set(head, NULL);
    LinkedList* prev = head;
    for (int i = 1; i < len; i++) {
        LinkedList* node = (LinkedList*)malloc(sizeof(LinkedList));
        LinkedList_value_set(node, ary[i]);
        LinkedList_next_set(node, NULL);
        LinkedList_next_set(prev, node);
        prev = node;
    }
    return head;
}
 
int main() {
    int ary[] = {10,20,30,40};
    LinkedList* head = createLinkedListFromArray(ary, 4);
    LinkedList* node = head;
    while (node!= NULL) {
        printf("%d\n", LinkedList_value(node));
        node = LinkedList_next(node);
    }
    return 0;
}

