#include <stdio.h>
#include <stdlib.h>
#include <math.h>
#include <X11/Xlib.h>
#include <X11/Xutil.h>
 
#define WIDTH 640
#define HEIGHT 640
 
void drawPentagram(Display *display, Window window, GC gc, int len, int x, int y,
                   unsigned long fill, unsigned long stroke) {
    double x2 = x;
    double y2 = y;
    double angle = 0.0;
    XPoint points[5];
    int i;
 
    points[0].x = x;
    points[0].y = y;
 
    for (i = 0; i < 5; i++) {
        x2 += cos(angle) * len;
        y2 += sin(-angle) * len;
        points[i + 1].x = x2;
        points[i + 1].y = y2;
        angle -= M_PI * 2.0 / 5.0;
    }
 
    XSetForeground(display, gc, fill);
    XFillPolygon(display, window, gc, points, 5, Convex, CoordModeOrigin);
    XSetForeground(display, gc, stroke);
    XDrawLines(display, window, gc, points, 5, CoordModeOrigin);
}
 
int main(int argc, char *argv[]) {
    Display *display;
    Window window;
    GC gc;
    XEvent event;
    int screen;
 
    display = XOpenDisplay(NULL);
    if (display == NULL) {
        fprintf(stderr, "Cannot open display\n");
        exit(1);
    }
 
    screen = DefaultScreen(display);
    window = XCreateSimpleWindow(display, RootWindow(display, screen), 0, 0,
                                 WIDTH, HEIGHT, 0, BlackPixel(display, screen),
                                 WhitePixel(display, screen));
    XSelectInput(display, window, ExposureMask | KeyPressMask);
    XMapWindow(display, window);
 
    gc = XCreateGC(display, window, 0, NULL);
    XSetLineAttributes(display, gc, 5, LineSolid, CapRound, JoinMiter);
 
    while (1) {
        XNextEvent(display, &event);
        if (event.type == Expose) {
            drawPentagram(display, window, gc, 500, 70, 250,
                          XBlackPixel(display, screen),
                          XBlackPixel(display, screen));
        }
        if (event.type == KeyPress) {
            break;
        }
    }
 
    XFreeGC(display, gc);
    XDestroyWindow(display, window);
    XCloseDisplay(display);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <math.h>
#include <stdbool.h>

#define LIMIT 1000000
#define SIEVE_LIMIT 15500000

int main(void) {
    int buckets[10][10] = {0};
    int prev_digit = 2;
    bool not_prime[SIEVE_LIMIT] = {false};
    sieve(not_prime);

    for (int n = 3, prime_count = 1; prime_count < LIMIT; n++) {
        if (not_prime[n])
            continue;

        int digit = n % 10;
        buckets[prev_digit][digit]++;
        prev_digit = digit;
        prime_count++;
    }

    for (int i = 0; i < 10; i++) {
        for (int j = 0; j < 10; j++) {
            if (buckets[i][j]!= 0) {
                printf("%d -> %d : %2f\n", i, j, buckets[i][j] / (LIMIT / 100.0));
            }
        }
    }

    return 0;
}

void sieve(bool not_prime[]) {
    not_prime[0] = not_prime[1] = true;

    int max = (int) sqrt(SIEVE_LIMIT);
    for (int n = 2; n <= max; n++) {
        if (!not_prime[n]) {
            for (int k = n * n; k < SIEVE_LIMIT; k += n) {
                not_prime[k] = true;
            }
        }
    }
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

typedef struct {
    char* key;
    int value;
} MapEntry;

typedef struct {
    MapEntry* entries;
    int size;
} Map;

Map* mapOf(char* key1, int value1, char* key2, int value2, char* key3, int value3, char* key4, int value4) {
    Map* map = malloc(sizeof(Map));
    map->size = 4;
    map->entries = malloc(sizeof(MapEntry) * map->size);
    map->entries[0].key = key1;
    map->entries[0].value = value1;
    map->entries[1].key = key2;
    map->entries[1].value = value2;
    map->entries[2].key = key3;
    map->entries[2].value = value3;
    map->entries[3].key = key4;
    map->entries[3].value = value4;
    return map;
}

int get(Map* map, char* key) {
    for (int i = 0; i < map->size; i++) {
        if (strcmp(map->entries[i].key, key) == 0) {
            return map->entries[i].value;
        }
    }
    return -1;
}

bool containsKey(Map* map, char* key) {
    for (int i = 0; i < map->size; i++) {
        if (strcmp(map->entries[i].key, key) == 0) {
            return true;
        }
    }
    return false;
}

void printKeys(Map* map) {
    for (int i = 0; i < map->size; i++) {
        printf("%s ", map->entries[i].key);
    }
    printf("\n");
}

void printValues(Map* map) {
    for (int i = 0; i < map->size; i++) {
        printf("%d ", map->entries[i].value);
    }
    printf("\n");
}

void printEntries(Map* map) {
    for (int i = 0; i < map->size; i++) {
        printf("%s => %d\n", map->entries[i].key, map->entries[i].value);
    }
}

int main(int argc, char** argv) {
    // map definition:
    Map* map = mapOf("foo", 5, "bar", 10, "baz", 15, "foo", 6);

    // retrieval:
    printf("%d\n", get(map, "foo")); // => 6
    printf("%d\n", get(map, "invalid")); // => -1

    // check keys:
    printf("%d\n", containsKey(map, "foo")); // => 1
    printf("%d\n", containsKey(map, "invalid")); // => 0

    // iterate over keys:
    printKeys(map);

    // iterate over values:
    printValues(map);

    // iterate over key, value pairs:
    printEntries(map);

    free(map->entries);
    free(map);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <assert.h>
#include <time.h>
#include <math.h>
 
int is_prime(unsigned int n) {
    assert(n > 0 && n < 64);
    return (1ULL << n) & 0x28208a20a08a28ac;
}
 
int prime_triangle_row(int *begin, int *end) {
    if (end - begin == 2)
        return is_prime(*begin + *(begin + 1));
    int *i;
    for (i = begin + 1; i + 1!= end; ++i) {
        if (is_prime(*begin + *i)) {
            int tmp = *i;
            *i = *(begin + 1);
            *(begin + 1) = tmp;
            if (prime_triangle_row(begin + 1, end))
                return 1;
            tmp = *(begin + 1);
            *(begin + 1) = *i;
            *i = tmp;
        }
    }
    return 0;
}
 
void prime_triangle_count(int *begin, int *end, int *count) {
    if (end - begin == 2) {
        if (is_prime(*begin + *(begin + 1)))
            ++*count;
        return;
    }
    int *i;
    for (i = begin + 1; i + 1!= end; ++i) {
        if (is_prime(*begin + *i)) {
            int tmp = *i;
            *i = *(begin + 1);
            *(begin + 1) = tmp;
            prime_triangle_count(begin + 1, end, count);
            tmp = *(begin + 1);
            *(begin + 1) = *i;
            *i = tmp;
        }
    }
}
 
void print(int *begin, int *end) {
    if (begin == end)
        return;
    int *i;
    printf("%2d", *begin++);
    for (i = begin; i!= end; ++i)
        printf(" %2d", *i);
    printf("\n");
}
 
int main() {
    clock_t start = clock();
    int n;
    for (n = 2; n < 21; ++n) {
        int *v = malloc(n * sizeof(int));
        int i;
        for (i = 0; i < n; ++i)
            v[i] = i + 1;
        if (prime_triangle_row(v, v + n))
            print(v, v + n);
        free(v);
    }
    printf("\n");
    for (n = 2; n < 21; ++n) {
        int *v = malloc(n * sizeof(int));
        int i;
        for (i = 0; i < n; ++i)
            v[i] = i + 1;
        int count = 0;
        prime_triangle_count(v, v + n, &count);
        if (n > 2)
            printf(" ");
        printf("%d", count);
        free(v);
    }
    printf("\n");
    clock_t end = clock();
    double duration = (double)(end - start) / CLOCKS_PER_SEC;
    printf("\nElapsed time: %f seconds\n", duration);
}

#include <stdio.h>
#include <string.h>
 
char *expand(char *cp)
{
    static char out[100];
    char *p = out;
    while (*cp) {
        switch (*cp) {
        case 'N':
            strcpy(p, "north");
            p += 5;
            break;
        case 'E':
            strcpy(p, "east");
            p += 4;
            break;
        case 'S':
            strcpy(p, "south");
            p += 5;
            break;
        case 'W':
            strcpy(p, "west");
            p += 4;
            break;
        case 'b':
            strcpy(p, " by ");
            p += 4;
            break;
        default:
            *p++ = '-';
            break;
        }
        cp++;
    }
    *p = '\0';
    return out;
}
 
int main(void)
{
    char *cp[] = {
        "N", "NbE", "N-NE", "NEbN", "NE", "NEbE", "E-NE", "EbN",
        "E", "EbS", "E-SE", "SEbE", "SE", "SEbS", "S-SE", "SbE",
        "S", "SbW", "S-SW", "SWbS", "SW", "SWbW", "W-SW", "WbS",
        "W", "WbN", "W-NW", "NWbW", "NW", "NWbN", "N-NW", "NbW"
    };
    printf("Index  Degrees  Compass point\n");
    printf("-----  -------  -------------\n");
    for (int i = 0; i <= 32; i++) {
        int index = i % 32;
        float heading = i * 11.25;
        if (i % 3 == 1)
            heading += 5.62;
        else if (i % 3 == 2)
            heading -= 5.62;
        printf("%2d     %6.2f   %s\n", index + 1, heading, expand(cp[index]));
    }
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
