typedef struct {
    uint8_t r;
    uint8_t g;
    uint8_t b;
    uint8_t a;
} RGBA;
 
typedef struct {
    int x;
    int y;
} Point;
 
typedef struct {
    int min;
    int max;
} Rectangle;
 
typedef struct {
    Rectangle r;
    RGBA *pixels;
} Image;
 
Image *image_new(Rectangle r) {
    Image *img = malloc(sizeof(Image));
    img->r = r;
    img->pixels = malloc(sizeof(RGBA) * (r.max - r.min) * (r.max - r.min));
    return img;
}
 
void image_draw(Image *img, Rectangle r, RGBA *color) {
    for (int y = r.min; y < r.max; y++) {
        for (int x = r.min; x < r.max; x++) {
            img->pixels[y * img->r.max + x] = *color;
        }
    }
}
 
void image_set(Image *img, Point p, RGBA *color) {
    img->pixels[p.y * img->r.max + p.x] = *color;
}
 
RGBA *image_at(Image *img, Point p) {
    return &img->pixels[p.y * img->r.max + p.x];
}
 
int main() {
    Rectangle rect = {0, 0, 320, 240};
    Image *img = image_new(rect);
 
    // Use green background, say.
    RGBA green = {0, 255, 0, 255};
    image_draw(img, rect, &green);
 
    // Set color of pixel at (100, 100) to red
    RGBA red = {255, 0, 0, 255};
    Point p = {100, 100};
    image_set(img, p, &red);
 
    // Check it worked.
    RGBA cmap[2] = {green, red};
    char *names[2] = {"green", "red"};
    RGBA *c1 = image_at(img, (Point){0, 0});
    RGBA *c2 = image_at(img, p);
    printf("The color of the pixel at (  0,   0) is %s.\n", names[*c1]);
    printf("The color of the pixel at (100, 100) is %s.\n", names[*c2]);
 
    free(img->pixels);
    free(img);
}

#include <stdio.h>
#include <stdlib.h>
#include <math.h>
#include <gsl/gsl_matrix.h>
#include <gsl/gsl_linalg.h>
 
gsl_matrix *Vandermonde(double *a, int n, int degree) {
    gsl_matrix *x = gsl_matrix_alloc(n, degree + 1);
    for (int i = 0; i < n; i++) {
        for (int j = 0, p = 1; j <= degree; j++, p *= a[i]) {
            gsl_matrix_set(x, i, j, p);
        }
    }
    return x;
}
 
int main() {
    double height[] = {1.47, 1.50, 1.52, 1.55, 1.57, 1.60, 1.63,
        1.65, 1.68, 1.70, 1.73, 1.75, 1.78, 1.80, 1.83};
    double weight[] = {52.21, 53.12, 54.48, 55.84, 57.20, 58.57, 59.93,
        61.29, 63.11, 64.47, 66.28, 68.10, 69.92, 72.19, 74.46};
    int degree = 2;
    int n = sizeof(height) / sizeof(height[0]);
    gsl_matrix *x = Vandermonde(height, n, degree);
    gsl_vector *y = gsl_vector_alloc(n);
    for (int i = 0; i < n; i++) {
        gsl_vector_set(y, i, weight[i]);
    }
    gsl_vector *c = gsl_vector_alloc(degree + 1);
    gsl_linalg_QR_decomp(x, c);
    gsl_linalg_QR_solve(x, c, y, c);
    for (int i = 0; i < degree + 1; i++) {
        printf("%.4f\n", gsl_vector_get(c, i));
    }
    gsl_matrix_free(x);
    gsl_vector_free(y);
    gsl_vector_free(c);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include <assert.h>

bool IsPalindrome(char* str)
{
    int len = strlen(str);
    int i;
    for (i = 0; i < len / 2; i++)
    {
        if (str[i]!= str[len - i - 1])
        {
            return false;
        }
    }
    return true;
}

bool IsPalindromeNonRecursive(char* str)
{
    int len = strlen(str);
    int i;
    for (i = 0; i < len / 2; i++)
    {
        if (str[i]!= str[len - i - 1])
        {
            return false;
        }
    }
    return true;
}

void PalindromeDetectorCanUnderstandPalindrome()
{
    bool expected = true;
    bool actual;
    actual = IsPalindrome("1");
    assert(expected == actual);
    actual = IsPalindromeNonRecursive("1");
    assert(expected == actual);
    actual = IsPalindrome("ingirumimusnocteetconsumimurigni");
    assert(expected == actual);
    actual = IsPalindromeNonRecursive("ingirumimusnocteetconsumimurigni");
    assert(expected == actual);
}

void PalindromeDetecotryCanUnderstandNonPalindrome()
{
    bool notExpected = true;
    bool actual = IsPalindrome("ThisIsNotAPalindrome");
    assert(notExpected!= actual);
    actual = IsPalindromeNonRecursive("ThisIsNotAPalindrome");
    assert(notExpected!= actual);
}

int main()
{
    PalindromeDetectorCanUnderstandPalindrome();
    PalindromeDetecotryCanUnderstandNonPalindrome();
    return 0;
}

