typedef struct {
  int red;
  int green;
  int blue;
} RGBColour;
 
typedef struct {
  int width;
  int height;
  RGBColour **data;
} Pixmap;
 
void save(Pixmap *self, char *filename) {
  FILE *f = fopen(filename, "w");
  fprintf(f, "P6\n%d %d\n255\n", self->width, self->height);
  fflush(f);
  fseek(f, 0, SEEK_END);
  int y;
  for (y = 0; y < self->height; y++) {
    int x;
    for (x = 0; x < self->width; x++) {
      RGBColour *colour = &self->data[x][y];
      fputc(colour->red, f);
      fputc(colour->green, f);
      fputc(colour->blue, f);
    }
  }
  fclose(f);
}
 
void write(Pixmap *self, char *filename) {
  save(self, filename);
}

#include <ruby.h>
#include <math.h>
 
static VALUE
semi_prime_p(VALUE self)
{
    long n = NUM2LONG(self);
    long i, j, k, l;
    long m = (long)sqrt(n);
    long sum = 0;
    for (i = 2; i <= m; i++) {
        if (n % i == 0) {
            for (j = 2; j <= m; j++) {
                if (i % j == 0) {
                    break;
                }
            }
            if (j > m) {
                for (k = 2; k <= m; k++) {
                    if (n / i % k == 0) {
                        for (l = 2; l <= m; l++) {
                            if (k % l == 0) {
                                break;
                            }
                        }
                        if (l > m) {
                            sum++;
                        }
                    }
                }
            }
        }
    }
    return sum == 2? Qtrue : Qfalse;
}
 
void
Init_semi_prime()
{
    rb_define_method(rb_cInteger, "semi_prime?", semi_prime_p, 0);
}

