#include <stdio.h>
#include <math.h>
 
double sum(double *array, int length) {
    double sum = 0;
    for (int i = 0; i < length; i++) {
        sum += array[i];
    }
    return sum;
}
 
double square(double x) {
    return x * x;
}
 
double mean(double *array, int length) {
    return sum(array, length) / length;
}
 
double averageSquareDiff(double a, double *predictions, int length) {
    double sum = 0;
    for (int i = 0; i < length; i++) {
        sum += square(predictions[i] - a);
    }
    return sum / length;
}
 
void diversityTheorem(double truth, double *predictions, int length) {
    double average = mean(predictions, length);
    printf("average-error: %f\n", averageSquareDiff(truth, predictions, length));
    printf("crowd-error: %f\n", square(truth - average));
    printf("diversity: %f\n", averageSquareDiff(average, predictions, length));
}
 
int main() {
    double a[] = {48,47,51};
    double b[] = {48,47,51,42};
    diversityTheorem(49, a, 3);
    diversityTheorem(49, b, 4);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <assert.h>
 
typedef struct {
    int start;
    int stop;
    int increment;
    char *comment;
} TableRow;
 
TableRow table[] = {
    { -2, 2, 1, "Normal" },
    { -2, 2, 0, "Zero increment" },
    { -2, 2, -1, "Increments away from stop value" },
    { -2, 2, 10, "First increment is beyond stop value" },
    { 2, -2, 1, "Start more than stop: positive increment" },
    { 2, 2, 1, "Start equal stop: positive increment" },
    { 2, 2, -1, "Start equal stop: negative increment" },
    { 2, 2, 0, "Start equal stop equal zero: zero increment" },
    { 0, 0, 0, "Start equal stop equal zero: zero increment" },
};
 
int main(int argc, char *argv[]) {
    int i;
    for (i = 0; i < sizeof(table) / sizeof(table[0]); i++) {
        TableRow *row = &table[i];
        printf("%s:\n  range(%d, %d, %d)\n", row->comment, row->start, row->stop, row->increment);
        int *values = NULL;
        int values_len = 0;
        int values_cap = 0;
        int j;
        for (j = row->start; j!= row->stop; j += row->increment) {
            if (values_len == values_cap) {
                values_cap = values_cap * 2 + 1;
