#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <limits.h>
 
int *indices;
 
int main(void) {
    long *array;
    int array_size = 0;
    int i;
    long highSum = LONG_MIN;
    long sum;
    long *highSet;
    int highSet_size = 0;
    long *temp;
    int temp_size = 0;
    int subSize;
    int j;
    int index;
 
    array = malloc(sizeof(long));
    while (scanf("%ld", &array[array_size]) == 1) {
        array_size++;
        array = realloc(array, (array_size + 1) * sizeof(long));
    }
 
    for (subSize = 0; subSize <= array_size; subSize++) {
        indices = malloc(subSize * sizeof(int));
        for (i = 0; i < subSize; i++) {
            indices[i] = i;
        }
        do {
            sum = 0;
            temp = malloc(subSize * sizeof(long));
            for (i = 0; i < subSize; i++) {
                index = indices[i];
                sum += array[index];
                temp[i] = array[index];
            }
            if (sum > highSum) {
                highSet = temp;
                highSet_size = subSize;
                highSum = sum;
            }
            free(temp);
        } while (nextIndices(array, array_size));
        free(indices);
    }
 
    printf("Sum: %ld\nSet: ", highSum);
    for (i = 0; i < highSet_size; i++) {
        printf("%ld ", highSet[i]);
    }
    printf("\n");
 
    free(array);
    free(highSet);
 
    return 0;
}
 
bool nextIndices(long *a, int a_size) {
    int i;
    int j;
 
    for (i = indices_size - 1; i >= 0; i--) {
        indices[i]++;
        for (j = i + 1; j < indices_size; j++) {
            indices[j] = indices[j - 1] + 1;
        }
        if (indices[indices_size - 1] < a_size) {
            return true;
        }
    }
    return false;
}

