#define M 50000

int biased(int n) {
    return rand() < RAND_MAX / n;
}

int unbiased(int n) {
    int a, b;
    do {
        a = biased(n);
        b = biased(n);
    } while (a == b);
    return a;
}

int main(int argc, char *argv[]) {
    int c1, c2;
    srand(time(NULL));
    for (int n = 3; n < 7; n++) {
        c1 = c2 = 0;
        for (int i = 0; i < M; i++) {
            c1 += biased(n)? 1 : 0;
            c2 += unbiased(n)? 1 : 0;
        }
        printf("%d: %2.2f%%  %2.2f%%\n", n, 100.0*c1/M, 100.0*c2/M);
    }
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <locale.h>
#include "prime_sieve.h"
 
typedef uint32_t integer;
 
// return number of decimal digits
int count_digits(integer n) {
    int digits = 0;
    for (; n > 0; ++digits)
        n /= 10;
    return digits;
}
 
// return the number with one digit replaced
integer change_digit(integer n, int index, int new_digit) {
    integer p = 1;
    integer changed = 0;
    for (; index > 0; p *= 10, n /= 10, --index)
        changed += p * (n % 10);
    changed += (10 * (n/10) + new_digit) * p;
    return changed;
}
 
// returns true if n unprimeable
bool unprimeable(const prime_sieve* sieve, integer n) {
    if (is_prime(sieve, n))
        return false;
    int d = count_digits(n);
    for (int i = 0; i < d; ++i) {
        for (int j = 0; j <= 9; ++j) {
            integer m = change_digit(n, i, j);
            if (m!= n && is_prime(sieve, m))
                return false;
        }
    }
    return true;
}
 
int main() {
    const integer limit = 10000000;
    prime_sieve* sieve = create_prime_sieve(limit);
 
    // print numbers with commas
    setlocale(LC_NUMERIC, "");
 
    printf("First 35 unprimeable numbers:\n");
    integer n = 100;
    integer lowest[10] = { 0 };
    for (int count = 0, found = 0; n < limit && (found < 10 || count < 600); ++n) {
        if (unprimeable(sieve, n)) {
            if (count < 35) {
                if (count!= 0)
                    printf(", ");
                printf("%'d", n);
            }
            ++count;
            if (count == 600)
                printf("\n600th unprimeable number: %'d\n", n);
            int last_digit = n % 10;
            if (lowest[last_digit] == 0) {
                lowest[last_digit] = n;
                ++found;
            }
        }
    }
    for (int i = 0; i < 10; ++i)
        printf("Least unprimeable number ending in %d: %'d\n", i, lowest[i]);
    destroy_prime_sieve(sieve);
    return 0;
}

#include <stdio.h>
