    printf("before: ");
    for (int i = 0; i < len; i++) {
        printf("%d ", v[i]);
    }
    printf("\n");
    bubble_sort(v, len);
    printf("after:  ");
    for (int i = 0; i < len; i++) {
        printf("%d ", v[i]);
    }
    printf("\n");
    return 0;
}

