    unsigned char two[SHA256_DIGEST_LENGTH] = {0x3a, 0x7b, 0xd3, 0xe2, 0x36, 0x0a, 0x3d, 0x29, 0xee, 0xa4, 0x36, 0xcf, 0xfb, 0x7e, 0x44, 0xc7, 0x35, 0xd1, 0x17, 0xc4, 0x2d, 0x1c, 0x18, 0x35, 0x42, 0x0b, 0x6b, 0x99, 0x42, 0xdd, 0x4f, 0x1b};
    unsigned char three[SHA256_DIGEST_LENGTH] = {0x74, 0xe1, 0xbb, 0x62, 0xf8, 0xda, 0xbb, 0x81, 0x25, 0xa5, 0x88, 0x52, 0xb6, 0x3b, 0xdf, 0x6e, 0xae, 0xf6, 0x67, 0xcb, 0x56, 0xac, 0x7f, 0x7c, 0xdb, 0xa6, 0xd7, 0x30, 0x5c, 0x50, 0xa2, 0x2f};
    password[0] = 97 + tid;
    for (password[1] = 97; password[1] < 123; password[1]++)
        for (password[2] = 97; password[2] < 123; password[2]++)
            for (password[3] = 97; password[3] < 123; password[3]++)
                for (password[4] = 97; password[4] < 123; password[4]++)
                {
                    SHA256(password, 5, hash);
                    if (memcmp(one, hash, SHA256_DIGEST_LENGTH) == 0 || memcmp(two, hash, SHA256_DIGEST_LENGTH) == 0 || memcmp(three, hash, SHA256_DIGEST_LENGTH) == 0)
                    {
                        printf("%c%c%c%c%c => ", password[0], password[1], password[2], password[3], password[4]);
                        for (i = 0; i < SHA256_DIGEST_LENGTH; i++)
                            printf("%02x", hash[i]);
