#include <stdio.h>
 
typedef struct {
	int next;
} PowIt;
 
typedef struct {
	PowIt powit;
} SquareIt;
 
typedef struct {
	PowIt powit;
} CubeIt;
 
int powit_next(PowIt *powit) {
	int result = powit->next;
	powit->next += 1;
	return result;
}
 
int squareit_next(SquareIt *squareit) {
	return powit_next(&squareit->powit) * powit_next(&squareit->powit);
}
 
int cubeit_next(CubeIt *cubeit) {
	return powit_next(&cubeit->powit) * powit_next(&cubeit->powit) * powit_next(&cubeit->powit);
}
 
int main(int argc, char *argv[]) {
	int squares[30];
	int hexponents[3];
	int i;
	int s, c;
	SquareIt squit;
	CubeIt cuit;
	squit.powit.next = 1;
	cuit.powit.next = 1;
	s = squareit_next(&squit);
	c = cubeit_next(&cuit);
	i = 0;
	while (i < 30 || i < 3) {
		if (s < c) {
			squares[i] = s;
			i++;
			s = squareit_next(&squit);
		} else if (s == c) {
			hexponents[i] = s;
			i++;
			s = squareit_next(&squit);
			c = cubeit_next(&cuit);
		} else {
			c = cubeit_next(&cuit);
		}
	}
	printf("Squares:\n");
	for (i = 0; i < 30; i++) {
		printf("%d ", squares[i]);
	}
	printf("\n");
	printf("Square-and-cubes:\n");
	for (i = 0; i < 3; i++) {
		printf("%d ", hexponents[i]);
	}
	printf("\n");
	return 0;
}

