#include <stdio.h>
#include <stdlib.h>
#include <math.h>

typedef struct {
    int a;
    int b;
    int c;
    int perimeter;
    int area;
} Heron;

double heronArea(int a, int b, int c) {
    double s = (a + b + c) / 2.0;
    return sqrt(s * (s - a) * (s - b) * (s - c));
}

int isHeron(double h) {
    return h == (int) h && h > 0;
}

int gcd(int a, int b) {
    int leftover = 1, dividend = a > b? a : b, divisor = a > b? b : a;
    while (leftover!= 0) {
        leftover = dividend % divisor;
        if (leftover > 0) {
            dividend = divisor;
            divisor = leftover;
        }
    }
    return divisor;
}

void sort(Heron *list, int size) {
    int swapped = 1;
    Heron temp;
    while (swapped) {
        swapped = 0;
        for (int i = 1; i < size; i++) {
            if (list[i].area < list[i - 1].area ||
                    list[i].area == list[i - 1].area &&
                    list[i].perimeter < list[i - 1].perimeter) {
                temp = list[i];
                list[i] = list[i - 1];
                list[i - 1] = temp;
                swapped = 1;
            }
        }
    }
}

int main() {
    Heron *list = malloc(sizeof(Heron) * 200 * 200 * 200);
    int index = 0;

    for (int c = 1; c <= 200; c++) {
        for (int b = 1; b <= c; b++) {
            for (int a = 1; a <= b; a++) {

                if (gcd(gcd(a, b), c) == 1 && isHeron(heronArea(a, b, c))) {
                    int area = (int) heronArea(a, b, c);
                    list[index].a = a;
                    list[index].b = b;
                    list[index].c = c;
                    list[index].perimeter = a + b + c;
                    list[index].area = area;
                    index++;
                }
            }
        }
    }
    sort(list, index);

    printf("Number of primitive Heronian triangles with sides up to 200: %d\n\n"
           "First ten when ordered by increasing area, then perimeter:\n"
           "Sides       Perimeter   Area", index);

    for (int i = 0; i < 10; i++) {
        printf("\n%d x %d x %d   %d     %d",
               list[i].a, list[i].b, list[i].c,
               list[i].perimeter, list[i].area);
    }

    printf("\n\nArea = 210\nSides        Perimeter   Area");
    for (int i = 0; i < index; i++) {
        if (list[i].area == 210)
            printf("\n%d x %d x %d   %d     %d",
                   list[i].a, list[i].b, list[i].c,
                   list[i].perimeter, list[i].area);
    }

    free(list);
    return 0;
}

