#include <inttypes.h>

#define MAX_PRIME 1000

bool is_prime(uint64_t n) {
    if (n <= 1) {
        return false;
    }
    if (n <= 3) {
        return true;
    }
    if (n % 2 == 0 || n % 3 == 0) {
        return false;
    }
    uint64_t i = 5;
    while (i * i <= n) {
        if (n % i == 0 || n % (i + 2) == 0) {
            return false;
        }
        i += 6;
    }
    return true;
}

int main() {
    uint64_t limit = MAX_PRIME;
    uint64_t sum = 0;
    printf("count  prime      sum\n");
    for (uint64_t n = 0, p = 2; p < limit; n++, p++) {
        if (is_prime(p)) {
            sum += p;
            if (is_prime(sum)) {
                printf("  %3" PRIu64 "    %3" PRIu64 "    %5" PRIu64 "\n", n + 1, p, sum);
            }
        }
    }
    return 0;
}

