char *bin_bit(char *h) {
    int i;
    for (i=0; i<strlen(h); i++) {
        if (h[i] == '1') {
            h[i] = 'x';
        } else {
            h[i] ='';
        }
    }
    return h;
}
 
char *binary(int n, int digits) {
    char *h = malloc(digits+1);
    sprintf(h, "%0*d", digits, n);
    return h;
}
 
