#include <stdio.h>
#include <stdlib.h>
#include <math.h>
 
#define sqrt3_2 0.86602540378444
 
typedef struct {
    double x;
    double y;
} point;
 
point* koch_next(const point* points, size_t size) {
    size_t output_size = 4*(size - 1) + 1;
    point* output = malloc(output_size * sizeof(point));
    double x0, y0, x1, y1;
    size_t j = 0;
    for (size_t i = 0; i + 1 < size; ++i) {
        x0 = points[i].x;
        y0 = points[i].y;
        x1 = points[i + 1].x;
        y1 = points[i + 1].y;
        double dy = y1 - y0;
        double dx = x1 - x0;
        output[j++] = (point){x0, y0};
        output[j++] = (point){x0 + dx/3, y0 + dy/3};
        output[j++] = (point){x0 + dx/2 - dy * sqrt3_2/3, y0 + dy/2 + dx * sqrt3_2/3};
        output[j++] = (point){x0 + 2 * dx/3, y0 + 2 * dy/3};
    }
    output[j] = (point){x1, y1};
    return output;
}
 
point* koch_points(int size, int iterations) {
    double length = size * sqrt3_2 * 0.95;
    double x = (size - length)/2;
    double y = size/2 - length * sqrt3_2/3;
    point points[] = {
        {x, y},
        {x + length/2, y + length * sqrt3_2},
        {x + length, y},
        {x, y}
    };
    for (int i = 0; i < iterations; ++i) {
        point* new_points = koch_next(points, sizeof(points)/sizeof(point));
        free(points);
        points = new_points;
    }
    return points;
}
 
void koch_curve_svg(FILE* out, int size, int iterations) {
    fprintf(out, "<svg xmlns='http://www.w3.org/2000/svg' width='%d' height='%d'>\n", size, size);
    fprintf(out, "<rect width='100%%' height='100%%' fill='black'/>\n");
    fprintf(out, "<path stroke-width='1' stroke='white' fill='none' d='");
    point* points = koch_points(size, iterations);
    for (size_t i = 0, n = sizeof(points)/sizeof(point); i < n; ++i)
        fprintf(out, (i == 0? "M" : "L") "%f,%f\n", points[i].x, points[i].y);
    fprintf(out, "z'/>\n</svg>\n");
    free(points);
}
 
int main() {
    FILE* out = fopen("koch_curve.svg", "w");
    if (!out) {
        fprintf(stderr, "Cannot open output file\n");
        return EXIT_FAILURE;
    }
    koch_curve_svg(out, 600, 5);
    fclose(out);
    return EXIT_SUCCESS;
}

