#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include <sys/stat.h>
#include <unistd.h>
#include <errno.h>

bool renameFile(char *oldname, char *newname) {
    // File (or directory) with old name
    struct stat st;
    if (stat(oldname, &st) == -1) {
        perror("stat");
        return false;
    }
    if (!S_ISREG(st.st_mode)) {
        fprintf(stderr, "Not a regular file: %s\n", oldname);
        return false;
    }
    // File (or directory) with new name
    if (stat(newname, &st) == -1) {
        perror("stat");
        return false;
    }
    if (!S_ISREG(st.st_mode)) {
        fprintf(stderr, "Not a regular file: %s\n", newname);
        return false;
    }
    // Rename file (or directory)
    if (rename(oldname, newname) == -1) {
        perror("rename");
        return false;
    }
    return true;
}

void test(char *type, char *oldname, char *newname) {
    printf("The following %s called %s %s renamed as %s.\n", type, oldname,
        ( renameFile(oldname, newname)? "was" : "could not be"), newname
    );
}

int main(int argc, char *argv[]) {
    test("file", "input.txt", "output.txt");
    test("file", "/", "output.txt");
    test("directory", "docs", "mydocs");
    test("directory", "/", "mydocs");
    return 0;
}

