#include <stdio.h>
#include <string.h>

char* lcs(char* a, char* b){
    int aLen = strlen(a);
    int bLen = strlen(b);
    if(aLen == 0 || bLen == 0){
        return "";
    }else if(a[aLen-1] == b[bLen-1]){
        return lcs(a.substring(0,aLen-1),b.substring(0,bLen-1))
            + a.charAt(aLen-1);
    }else{
        String x = lcs(a, b.substring(0,bLen-1));
        String y = lcs(a.substring(0,aLen-1), b);
        return (x.length() > y.length())? x : y;
    }
}

