/*
 * This is a class documentation comment.  This text shows at the top of the page
 * for the class.
 *
 * Comments can be written inside "=begin rdoc"/"end" blocks or 
 * in normal '#' comment blocks.
 *
 * There are no '@parameters' like javadoc, but 'name-value' lists can be written:
 * Author:: 
 * Date:: today
 */

#include <ruby.h>

/*
 * This is a comment for a Constant
 */

static VALUE cDoc;
static VALUE cConstant;

/*
 * This is a method comment.  Parameters and return values can be named
 * with the "call-seq" directive.  
 *
 * call-seq:
 *   a_method(first_arg, second_arg) -> return_value
 */

static VALUE
a_method(VALUE self, VALUE arg1, VALUE arg2)
{
    do_stuff();
    return Qnil;
}

/*
 * Class methods will be shown in a separate section of the generated documentation.
 */

static VALUE
class_method(VALUE self)
{
    return cConstant;
}

void
Init_doc()
{
    cDoc = rb_define_class("Doc", rb_cObject);
    rb_define_method(cDoc, "a_method", a_method, 2);
    rb_define_singleton_method(cDoc, "class_method", class_method, 0);
    cConstant = Qnil;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <limits.h>
 
#define min(a,b) ((a) < (b)? (a) : (b))
 
char *levenshtein_align(const char *a, const char *b)
{
    int i, j, temp;
    int a_len = strlen(a);
    int b_len = strlen(b);
    int *costs = malloc((a_len + 1) * sizeof(int));
    char *a_path = malloc(a_len + 1);
    char *b_path = malloc(b_len + 1);
    char *a_path_rev = malloc(a_len + 1);
    char *b_path_rev = malloc(b_len + 1);
    char *result;
 
    for (j = 0; j <= b_len; j++)
        costs[j] = j;
    for (i = 1; i <= a_len; i++) {
        costs[0] = i;
        for (j = 1; j <= b_len; j++) {
            temp = costs[j - 1] + (tolower(a[i - 1]) == tolower(b[j - 1])? 0 : 1);
            costs[j] = min(min(temp, costs[j] + 1), costs[j - 1] + 1);
        }
    }
 
    i = a_len;
    j = b_len;
    a_path[i] = '\0';
    b_path[j] = '\0';
    while (i!= 0 && j!= 0) {
        temp = costs[j - 1] + (tolower(a[i - 1]) == tolower(b[j - 1])? 0 : 1);
        if (costs[j] == temp) {
            a_path[--i] = a[i];
            b_path[--j] = b[j];
        } else if (costs[j] == costs[j - 1] + 1) {
            a_path[--i] = '-';
            b_path[--j] = b[j];
        } else {
            a_path[--i] = a[i];
            b_path[--j] = '-';
        }
    }
    while (i!= 0) {
        a_path[--i] = a[i];
        b_path[--j] = '-';
    }
    while (j!= 0) {
        a_path[--i] = '-';
        b_path[--j] = b[j];
    }
 
    for (i = 0; i < a_len; i++)
        a_path_rev[i] = a_path[a_len - i - 1];
    a_path_rev[a_len] = '\0';
    for (i = 0; i < b_len; i++)
        b_path_rev[i] = b_path[b_len - i - 1];
    b_path_rev[b_len] = '\0';
 
    result = malloc(a_len + b_len + 2);
    sprintf(result, "%s\n%s", a_path_rev, b_path_rev);
 
    free(costs);
    free(a_path);
    free(b_path);
    free(a_path_rev);
    free(b_path_rev);
 
    return result;
}
 
int main(void)
{
    char *result = levenshtein_align("place", "palace");
    printf("%s\n", result);
    free(result);
    result = levenshtein_align("rosettacode", "raisethysword");
    printf("%s\n", result);
    free(result);
 
    return 0;
}

