int *pascal() {
  int *a;
  a = malloc(sizeof(int));
  return a;
}
 
char *show(int *a) {
  int degree, i, sgn;
  char *show_x(int e) {
    switch (e) {
      case 0:
        return "";
      case 1:
        return "x";
      default:
        return "x^" + e;
    }
  }
  degree = sizeof(a) - 1;
  char *str = "(x - 1)^" + degree + " =";
  sgn = 1;
  for (i = 0; i < sizeof(a); i++) {
    str +='' + (sgn > 0? "+" : "-") +'' + a[i] + show_x(degree - i);
    sgn = -sgn;
  }
  return str;
}
 
bool primerow(int *row) {
  int degree;
  degree = sizeof(row) - 1;
  return row.slice(1, degree).every(function(x) {
    return x % degree === 0;
  });
}
 
