#include <stdio.h>
#include <stdlib.h>
#include <string.h>
 
typedef struct {
    char *name;
    int weight;
    int value;
} Item;
 
#define MAX_WEIGHT 400
 
Item wants[] = {
    {"map", 9, 150},
    {"compass", 13, 35},
    {"water", 153, 200},
    {"sandwich", 50, 160},
    {"glucose", 15, 60},
    {"tin", 68, 45},
    {"banana", 27, 60},
    {"apple", 39, 40},
    {"cheese", 23, 30},
    {"beer", 52, 10},
    {"suntan cream", 11, 70},
    {"camera", 32, 30},
    {"T-shirt", 24, 15},
    {"trousers", 48, 10},
    {"umbrella", 73, 40},
    {"waterproof trousers", 42, 70},
    {"waterproof overclothes", 43, 75},
    {"note-case", 22, 80},
    {"sunglasses", 7, 20},
    {"towel", 18, 12},
    {"socks", 4, 50},
    {"book", 30, 10}
};
 
int n = sizeof(wants) / sizeof(Item);
 
typedef struct {
    Item *items;
    int weight;
    int value;
} Result;
 
Result m(int i, int w) {
    Result result;
    result.items = NULL;
    result.weight = 0;
    result.value = 0;
    if (i < 0 || w == 0) return result;
    else if (wants[i].weight > w) return m(i - 1, w);
    Result r0 = m(i - 1, w);
    Result r1 = m(i - 1, w - wants[i].weight);
    r1.value += wants[i].value;
    if (r1.value > r0.value) {
        r1.items = (Item *) malloc(sizeof(Item) * (r1.weight + 1));
        memcpy(r1.items, r0.items, sizeof(Item) * r0.weight);
        r1.items[r1.weight++] = wants[i];
        free(r0.items);
        return r1;
    }
    return r0;
}
 
int main(int argc, char **argv) {
    Result result = m(n - 1, MAX_WEIGHT);
    printf("Knapsack Item Chosen    Weight Value\n");
    printf("----------------------  ------ -----\n");
    for (int i = 0; i < result.weight; i++)
        printf("%-24s  %3d    %3d\n", result.items[i].name, result.items[i].weight, result.items[i].value);
    printf("----------------------  ------ -----\n");
    printf("Total %d Items Chosen     %d   %d\n", result.weight, result.weight, result.value);
    free(result.items);
    return 0;
}

