#include <stdio.h>
 
void gnomeSort(int a[], int len) {
    int i, j;
    for (i = 1, j = 2; i < len; i = j, j++) {
        if (a[i-1] > a[i]) {
            int tmp = a[i-1];
            a[i-1] = a[i];
            a[i] = tmp;
            i--;
            if (i > 0) {
                continue;
            }
        }
    }
}
 
int main() {
    int a[] = {170, 45, 75, -90, -802, 24, 2, 66};
    int len = sizeof(a) / sizeof(a[0]);
    int i;
    printf("before: ");
    for (i = 0; i < len; i++) {
        printf("%d ", a[i]);
    }
    printf("\n");
    gnomeSort(a, len);
    printf("after:  ");
    for (i = 0; i < len; i++) {
        printf("%d ", a[i]);
    }
    printf("\n");
    return 0;
}

