#include <stdio.h>
#include <stdlib.h>
 
typedef struct BinaryTreeNode {
  int value;
  struct BinaryTreeNode *left;
  struct BinaryTreeNode *right;
} BinaryTreeNode;
 
BinaryTreeNode *BinaryTreeNode_from_array(int *nested_list) {
  int value = nested_list[0];
  int *left = nested_list[1];
  int *right = nested_list[2];
  if (value) {
    BinaryTreeNode *node = malloc(sizeof(BinaryTreeNode));
    node->value = value;
    node->left = BinaryTreeNode_from_array(left);
    node->right = BinaryTreeNode_from_array(right);
    return node;
  } else {
    return NULL;
  }
}
 
void BinaryTreeNode_walk_nodes(BinaryTreeNode *node, int *order, void (*block)(BinaryTreeNode *)) {
  int i;
  for (i = 0; order[i]; i++) {
    switch (order[i]) {
      case 1: if (node->left) BinaryTreeNode_walk_nodes(node->left, order, block); break;
      case 2: block(node); break;
      case 3: if (node->right) BinaryTreeNode_walk_nodes(node->right, order, block); break;
    }
  }
}
 
void BinaryTreeNode_each_preorder(BinaryTreeNode *node, void (*block)(BinaryTreeNode *)) {
  BinaryTreeNode_walk_nodes(node, (int[]){2, 1, 3, 0}, block);
}
 
void BinaryTreeNode_each_inorder(BinaryTreeNode *node, void (*block)(BinaryTreeNode *)) {
  BinaryTreeNode_walk_nodes(node, (int[]){1, 2, 3, 0}, block);
}
 
void BinaryTreeNode_each_postorder(BinaryTreeNode *node, void (*block)(BinaryTreeNode *)) {
  BinaryTreeNode_walk_nodes(node, (int[]){1, 3, 2, 0}, block);
}
 
void BinaryTreeNode_each_levelorder(BinaryTreeNode *node, void (*block)(BinaryTreeNode *)) {
  BinaryTreeNode *queue[100];
  int head = 0, tail = 0;
  queue[tail++] = node;
  while (head < tail) {
    node = queue[head++];
    block(node);
    if (node->left) queue[tail++] = node->left;
    if (node->right) queue[tail++] = node->right;
  }
}
 
void print_node(BinaryTreeNode *node) {
  printf("%d ", node->value);
}
 
int main() {
  int tree[] = {1, {2, {4, 7, 0}, {5, 0, 0}}, {3, {6, {8, 0, 0}, {9, 0, 0}}, 0}};
  BinaryTreeNode *root = BinaryTreeNode_from_array(tree);
  BinaryTreeNode_each_preorder(root, print_node); printf("\n");
  BinaryTreeNode_each_inorder(root, print_node); printf("\n");
  BinaryTreeNode_each_postorder(root, print_node); printf("\n");
  BinaryTreeNode_each_levelorder(root, print_node); printf("\n");
  return 0;
}

#include <stdio.h>
#include <string.h>
#include <stdlib.h>

char *lookandsay(char *str) {
    char *result = malloc(strlen(str) * 2);
    char *p = result;
    char *q = str;
    while (*q) {
        int count = 1;
        while (*q == *(q + 1)) {
            count++;
            q++;
        }
        *p++ = count + '0';
        *p++ = *q++;
    }
    *p = '\0';
    return result;
}

int main() {
    char *num = "1";
    for (int i = 10; i > 0; i--) {
        printf("%s\n", num);
        num = lookandsay(num);
    }
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
 
bool *sieve(int limit) {
    // True denotes composite, false denotes prime.
    bool *c = calloc(limit + 1, sizeof(bool));
    c[0] = true;
    c[1] = true;
    // apart from 2 all even numbers are of course composite
    for (int i = 4; i <= limit; i += 2) c[i] = true;
    int p = 3; // start from 3
    while (true) {
        int p2 = p * p;
        if (p2 > limit) break;
        for (int i = p2; i <= limit; i += 2 * p) c[i] = true;
        while (true) {
            p += 2;
            if (!c[p]) break;
        }
    }
    return c;
}
 
int main(int argc, char **argv) {
    // sieve up to 10 million
    bool *sieved = sieve(10000000);
    int safe[35];
    int count = 0;
    int i = 3;
    while (count < 35) {
        if (!sieved[i] &&!sieved[(i - 1) / 2]) safe[count++] = i;
        i += 2;
    }
    printf("The first 35 safe primes are:\n");
    for (int j = 0; j < 35; j++) printf("%d ", safe[j]);
    printf("\n\n");
 
    count = 0;
    for (int j = 3; j < 1000000; j += 2) {
        if (!sieved[j] &&!sieved[(j - 1) / 2]) count++;
    }
    printf("The number of safe primes below 1,000,000 is %d\n\n", count);
 
    for (int j = 1000001; j < 10000000; j += 2) {
        if (!sieved[j] &&!sieved[(j - 1) / 2]) count++;
    }
    printf("The number of safe primes below 10,000,000 is %d\n\n", count);
 
    int unsafe[40];
    unsafe[0] = 2;  // since (2 - 1)/2 is not prime
    count = 1;
    i = 3;
    while (count < 40) {
        if (!sieved[i] && sieved[(i - 1) / 2]) unsafe[count++] = i;
        i += 2;
    }
    printf("The first 40 unsafe primes are:\n");
    for (int j = 0; j < 40; j++) printf("%d ", unsafe[j]);
    printf("\n\n");
 
    count = 1;
    for (int j = 3; j < 1000000; j += 2) {
        if (!sieved[j] && sieved[(j - 1) / 2]) count++;
    }
    printf("The number of unsafe primes below 1,000,000 is %d\n\n", count);
 
    for (int j = 1000001; j < 10000000; j += 2) {
        if (!sieved[j] && sieved[(j - 1) / 2]) count++;
    }
    printf("The number of unsafe primes below 10,000,000 is %d\n\n", count);
 
    free(sieved);
    return 0;
}

