#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <assert.h>
 
typedef struct {
    int *blocks;
    int nblocks;
    int cells;
} config;
 
void print_config(config *c) {
    int i, j, k;
    char *vector;
    vector = malloc(c->cells * sizeof(char));
    memset(vector, '_', c->cells);
    for (i = 0; i < c->nblocks; i++) {
        for (j = c->blocks[i]; j > 0; j--) {
            vector[k++] = 'A' + i;
        }
        vector[k++] = '|';
    }
    printf("%s\n", vector);
    free(vector);
}
 
int nonoblocks(config *c, int *vec, int nvec) {
    int i, j, k, blength, brest, minspace4rest, bpos, offset;
    int *subpos;
    if (c->nblocks == 0) {
        vec[0] = 0;
        return 1;
    }
    assert(c->blocks[0] + c->nblocks - 1 <= c->cells, "Those blocks will not fit in those cells");
    blength = c->blocks[0];
    brest = c->nblocks - 1;
    minspace4rest = 0;
    for (i = 0; i < brest; i++) {
        minspace4rest += 1 + c->blocks[i+1];
    }
    for (bpos = 0; bpos < c->cells - minspace4rest - blength + 1; bpos++) {
        if (brest == 0) {
            vec[0] = bpos;
            vec[1] = blength;
            return 1;
        } else {
            offset = bpos + blength + 1;
            config subc;
            subc.blocks = c->blocks + 1;
            subc.nblocks = brest;
            subc.cells = c->cells - offset;
            subpos = malloc(subc.nblocks * sizeof(int));
            k = nonoblocks(&subc, subpos, 0);
            for (i = 0; i < k; i++) {
                vec[0] = bpos;
                vec[1] = blength;
                for (j = 0; j < brest; j++) {
                    vec[j+2] = offset + subpos[j];
                }
                vec += brest + 2;
            }
            free(subpos);
        }
    }
    return 0;
}
 
int main(int argc, char *argv[]) {
    int i, j, k, nvec, *vec;
    config c;
    c.blocks = malloc(10 * sizeof(int));
    c.nblocks = 0;
    c.cells = 10;
    c.blocks[c.nblocks++] = 2;
    c.blocks[c.nblocks++] = 1;
    nvec = 1;
    for (i = 0; i < c.nblocks; i++) {
        nvec *= c.blocks[i] + 1;
    }
    vec = malloc(nvec * (c.nblocks + 1) * sizeof(int));
    k = nonoblocks(&c, vec, 0);
    printf("Configuration:\n");
    print_config(&c);
    printf("Possibilities:\n");
    for (i = 0; i < k; i++) {
        for (j = 0; j < c.nblocks + 1; j++) {
            printf("%d ", vec[i*(c.nblocks+1) + j]);
        }
        printf("\n");
    }
    printf("A total of %d Possible configurations.\n", k);
    free(vec);
    free(c.blocks);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <math.h>
#include <stdbool.h>
#include <pthread.h>
 
#define ZERO 0
#define ONE 1
#define TWO 2
#define FOUR 4
 
typedef struct {
    int p;
    bool isPrime;
} Prime;
 
typedef struct {
    int start;
    int end;
    Prime* primes;
} PrimeRange;
 
void* isMersennePrime(void* arg) {
    PrimeRange* range = (PrimeRange*)arg;
    for (int i = range->start; i < range->end; i++) {
        if (i % 2 == 0) range->primes[i].isPrime = (i == 2);
        else {
            for (int j = 3; j <= sqrt(i); j += 2)
                if (i % j == 0) {
                    range->primes[i].isPrime = false;
                    break;
                }
            if (range->primes[i].isPrime) {
                long long m_p = pow(TWO, i) - ONE;
                long long s = FOUR;
                for (int j = 3; j <= i; j++)
                    s = (s * s - TWO) % m_p;
                range->primes[i].isPrime = (s == ZERO);
            }
        }
    }
    return NULL;
}
 
int* GetMersennePrimeNumbers(int upTo) {
    Prime* primes = (Prime*)malloc(sizeof(Prime) * upTo);
    for (int i = 0; i < upTo; i++) {
        primes[i].p = i;
        primes[i].isPrime = false;
    }
    int numThreads = 4;
    pthread_t threads[numThreads];
    PrimeRange ranges[numThreads];
    int rangeSize = upTo / numThreads;
    for (int i = 0; i < numThreads; i++) {
        ranges[i].start = i * rangeSize;
        ranges[i].end = (i + 1) * rangeSize;
        ranges[i].primes = primes;
        pthread_create(&threads[i], NULL, isMersennePrime, &ranges[i]);
    }
    for (int i = 0; i < numThreads; i++)
        pthread_join(threads[i], NULL);
    int* response = (int*)malloc(sizeof(int) * upTo);
    int j = 0;
    for (int i = 0; i < upTo; i++)
        if (primes[i].isPrime) response[j++] = i;
    free(primes);
    return response;
}
 
int main() {
    int* mersennePrimes = GetMersennePrimeNumbers(11213);
    for (int i = 0; mersennePrimes[i]!= 0; i++)
        printf("M%d ", mersennePrimes[i]);
    free(mersennePrimes);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <math.h>
 
// inputs must be random-access iterators of doubles
// Note: this function modifies the input range
double median(double *begin, double *end) {
  // this is middle for odd-length, and "upper-middle" for even length
  double *middle = begin + (end - begin) / 2;
 
  // This function runs in O(n) on average, according to the standard
  nth_element(begin, middle, end);
 
  if ((end - begin) % 2!= 0) { // odd length
    return *middle;
  } else { // even length
    // the "lower middle" is the max of the lower half
    double *lower_middle = max_element(begin, middle);
    return (*middle + *lower_middle) / 2.0;
  }
}
 
int main() {
  double a[] = {4.1, 5.6, 7.2, 1.7, 9.3, 4.4, 3.2};
  double b[] = {4.1, 7.2, 1.7, 9.3, 4.4, 3.2};
 
  printf("%f\n", median(a+0, a + sizeof(a)/sizeof(a[0]))); // 4.4
  printf("%f\n", median(b+0, b + sizeof(b)/sizeof(b[0]))); // 4.25
 
  return 0;
}

