    printf("%f %f %f\n", v3(a, b, c).x, v3(a, b, c).y, v3(a, b, c).z);
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
 
typedef struct {
    int rows;
    int columns;
    double **mtx;
} Matrix;
 
Matrix *newMatrix(int rows, int columns) {
    Matrix *m = malloc(sizeof(Matrix));
    m->rows = rows;
    m->columns = columns;
    m->mtx = malloc(rows * sizeof(double *));
    for (int i = 0; i < rows; i++) {
        m->mtx[i] = malloc(columns * sizeof(double));
    }
    return m;
}
 
void freeMatrix(Matrix *m) {
    for (int i = 0; i < m->rows; i++) {
        free(m->mtx[i]);
    }
    free(m->mtx);
    free(m);
}
 
void printMatrix(Matrix *m) {
    for (int i = 0; i < m->rows; i++) {
        for (int j = 0; j < m->columns; j++) {
            printf("%.2f ", m->mtx[i][j]);
        }
        printf("\n");
    }
}
 
Matrix *toReducedRowEchelonForm(Matrix *m) {
    int lead = 0;
    for (int r = 0; r < m->rows; r++) {
        if (m->columns <= lead) {
            return m;
        }
        int i = r;
        while (m->mtx[i][lead] == 0) {
            i++;
            if (m->rows == i) {
                i = r;
                lead++;
                if (m->columns == lead) {
                    return m;
                }
            }
        }
 
        double *tmp = m->mtx[i];
        m->mtx[i] = m->mtx[r];
        m->mtx[r] = tmp;
 
        double val = m->mtx[r][lead];
        for (int j = 0; j < m->columns; j++) {
            m->mtx[r][j] /= val;
        }
 
        for (int i = 0; i < m->rows; i++) {
            if (i == r) continue;
            val = m->mtx[i][lead];
            for (int j = 0; j < m->columns; j++) {
                m->mtx[i][j] -= val * m->mtx[r][j];
            }
        }
        lead++;
    }
    return m;
}
 
int main() {
    Matrix *m = newMatrix(3, 4);
    m->mtx[0][0] = 1;
    m->mtx[0][1] = 2;
    m->mtx[0][2] = -1;
    m->mtx[0][3] = -4;
    m->mtx[1][0] = 2;
    m->mtx[1][1] = 3;
    m->mtx[1][2] = -1;
    m->mtx[1][3] = -11;
    m->mtx[2][0] = -2;
    m->mtx[2][1] = 0;
    m->mtx[2][2] = -3;
    m->mtx[2][3] = 22;
    printMatrix(toReducedRowEchelonForm(m));
    freeMatrix(m);
 
    m = newMatrix(3, 4);
    m->mtx[0][0] = 1;
    m->mtx[0][1] = 2;
    m->mtx[0][2] = 3;
    m->mtx[0][3] = 7;
    m->mtx[1][0] = -4;
    m->mtx[1][1] = 7;
    m->mtx[1][2] = -2;
    m->mtx[1][3] = 7;
    m->mtx[2][0] = 3;
    m->mtx[2][1] = 3;
    m->mtx[2][2] = 0;
    m->mtx[2][3] = 7;
    printMatrix(toReducedRowEchelonForm(m));
    freeMatrix(m);
 
    return 0;
}

