#include <stdio.h>
#include <stdlib.h>
#include <math.h>
 
/**
 * Draw a hilbert curve of the given order.
 * Outputs a svg string. Save the string as a.svg file and open in a browser.
 * @param {!Number} order
 */
void drawHilbert(int order) {
    if (!order || order < 1) {
        printf("You need to give a valid positive integer");
        exit(1);
    } else {
        order = floor(order);
    }
 
 
    // Curve Constants
    int width = pow(2, order);
    int space = 10;
 
    // SVG Setup
    int size = 500;
    int stroke = 2;
    char col[] = "red";
    char fill[] = "transparent";
 
    // Prep and run function
    int points[width * width * 2];
    int i = 0;
    hilbert(width, space, points, 0, 0, width, 0, 0, &i);
    char path[width * width * 2];
    for (int j = 0; j < i; j++) {
        char temp[10];
        sprintf(temp, "%d ", points[j]);
        strcat(path, temp);
    }
 
    printf("<svg xmlns=\"http://www.w3.org/2000/svg\" \
    width=\"%d\" \
    height=\"%d\" \
    viewBox=\"%d %d %d %d\"> \
  <path d=\"M%s\" stroke-width=\"%d\" stroke=\"%s\" fill=\"%s\"/> \
</svg>", size, size, space / 2, space / 2, width * space, width * space, path, stroke, col, fill);
 
}
 
/**
 * Translate this
 * const hilbert = (width, spacing, points) => (x, y, lg, i1, i2, f) => {
    if (lg === 1) {
        const px = (width - x) * spacing;
        const py = (width - y) * spacing;
        points.push(px, py);
        return;
    }
    lg >>= 1;
    f(x + i1 * lg, y + i1 * lg, lg, i1, 1 - i2, f);
    f(x + i2 * lg, y + (1 - i2) * lg, lg, i1, i2, f);
    f(x + (1 - i1) * lg, y + (1 - i1) * lg, lg, i1, i2, f);
    f(x + (1 - i2) * lg, y + i2 * lg, lg, 1 - i1, i2, f);
    return points;
};
 */
void hilbert(int width, int spacing, int points[], int x, int y, int lg, int i1, int i2, int *i) {
    if (lg == 1) {
        int px = (width - x) * spacing;
        int py = (width - y) * spacing;
        points[*i] = px;
        *i = *i + 1;
        points[*i] = py;
        *i = *i + 1;
        return;
    }
    lg >>= 1;
    hilbert(width, spacing, points, x + i1 * lg, y + i1 * lg, lg, i1, 1 - i2, i);
    hilbert(width, spacing, points, x + i2 * lg, y + (1 - i2) * lg, lg, i1, i2, i);
    hilbert(width, spacing, points, x + (1 - i1) * lg, y + (1 - i1) * lg, lg, i1, i2, i);
    hilbert(width, spacing, points, x + (1 - i2) * lg, y + i2 * lg, lg, 1 - i1, i2, i);
    return;
}
 
int main() {
    drawHilbert(6);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
 
int **cache;
 
int *cumu(int n) {
    int i, j, *r;
    if (n < 0) return NULL;
    if (cache[n]) return cache[n];
    r = malloc((n+1) * sizeof(int));
    r[0] = 0;
    for (i = 1; i <= n; i++) {
        r[i] = r[i-1];
        for (j = 1; j <= i; j++) {
            r[i] += cache[i-j][j];
        }
    }
    cache[n] = r;
    return r;
}
 
int *row(int n) {
    int i, *r;
    r = cumu(n);
    for (i = 0; i < n; i++) {
        r[i] = r[i+1] - r[i];
    }
    return r;
}
 
int main(int argc, char *argv[]) {
    int i, j, n;
    cache = malloc(1000000 * sizeof(int *));
    memset(cache, 0, 1000000 * sizeof(int *));
    for (i = 1; i <= 10; i++) {
        printf("%2d: ", i);
        for (j = 0; j < i; j++) {
            printf("%d ", row(i)[j]);
        }
        printf("\n");
    }
    printf("\nsums:\n");
    for (i = 0; i < 4; i++) {
        n = 23;
        for (j = 0; j < i; j++) {
            n *= 10;
            n += 23;
        }
        printf("%d %d\n", n, cumu(n)[n]);
    }
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <math.h>
#include <string.h>

#define N 13

int cmp(const void *a, const void *b) {
    return *(int *)a - *(int *)b;
}

int cmp_tuple(const void *a, const void *b) {
    int *aa = (int *)a;
    int *bb = (int *)b;
    for (int i = 0; i < 3; i++) {
        if (aa[i]!= bb[i]) {
            return aa[i] - bb[i];
        }
    }
    return 0;
}

int main() {
    int squares[N+1];
    for (int i = 0; i <= N; i++) {
        squares[i] = i * i;
    }
    int sqrset[N+1];
    memset(sqrset, 0, sizeof(sqrset));
    for (int i = 0; i <= N; i++) {
        sqrset[squares[i]] = 1;
    }
    int tri90[N*N/2][3];
    int tri60[N*N/2][3];
    int tri120[N*N/2][3];
    int n90 = 0, n60 = 0, n120 = 0;
    for (int a = 1; a <= N; a++) {
        int a2 = squares[a];
        for (int b = 1; b <= a; b++) {
            int b2 = squares[b];
            int c2 = a2 + b2;
            if (sqrset[c2]) {
                tri90[n90][0] = a;
                tri90[n90][1] = b;
                tri90[n90][2] = (int)sqrt(c2);
                n90++;
            }
            int ab = a * b;
            c2 -= ab;
            if (sqrset[c2]) {
                tri60[n60][0] = a;
                tri60[n60][1] = b;
                tri60[n60][2] = (int)sqrt(c2);
                n60++;
            }
            c2 += 2 * ab;
            if (sqrset[c2]) {
                tri120[n120][0] = a;
                tri120[n120][1] = b;
                tri120[n120][2] = (int)sqrt(c2);
                n120++;
            }
        }
    }
    qsort(tri90, n90, sizeof(tri90[0]), cmp_tuple);
    qsort(tri60, n60, sizeof(tri60[0]), cmp_tuple);
    qsort(tri120, n120, sizeof(tri120[0]), cmp_tuple);
    printf("Integer triangular triples for sides 1..%d:\n", N);
    printf("  90° has %d solutions:\n", n90);
    for (int i = 0; i < n90; i++) {
        printf("    (%d, %d, %d)\n", tri90[i][0], tri90[i][1], tri90[i][2]);
    }
    printf("  60° has %d solutions:\n", n60);
    for (int i = 0; i < n60; i++) {
        printf("    (%d, %d, %d)\n", tri60[i][0], tri60[i][1], tri60[i][2]);
    }
    printf(" 120° has %d solutions:\n", n120);
    for (int i = 0; i < n120; i++) {
        printf("    (%d, %d, %d)\n", tri120[i][0], tri120[i][1], tri120[i][2]);
    }
    int notsame = 0;
    for (int i = 0; i < n60; i++) {
        if (tri60[i][0]!= tri60[i][1] || tri60[i][1]!= tri60[i][2]) {
            notsame++;
        }
