#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <regex.h>
 
// Parses the input string for the numerators and denominators
void compile(char *prog, int *numArr, int *denArr) {
    regex_t regex;
    regcomp(&regex, "\\s*(\\d*)\\s*\\/\\s*(\\d*)\\s*(.*)", REG_EXTENDED);
    regmatch_t match[4];
    int i = 0;
    while (regexec(&regex, prog, 4, match, 0) == 0) {
        numArr[i] = atoi(prog + match[1].rm_so);
        denArr[i] = atoi(prog + match[2].rm_so);
        prog = prog + match[3].rm_so;
        i++;
    }
    regfree(&regex);
}
 
// Outputs the result of the compile stage
void dump(int *numArr, int *denArr, int len) {
    for (int i = 0; i < len; i++) {
        printf("%d/%d ", numArr[i], denArr[i]);
    }
    printf("\n");
}
 
// Step
int step(int val, int *numArr, int *denArr, int len) {
    int i = 0;
    while (i < len && val % denArr[i]!= 0) i++;
    return numArr[i] * val / denArr[i];
}
 
// Executes Fractran
void exec(int val, int i, int limit, int *numArr, int *denArr, int len) {
    while (val && i < limit) {
        printf("%d: %d\n", i, val);
        val = step(val, numArr, denArr, len);
        i++;
    }
}
 
// Main
int main() {
    int num[15], den[15];
    compile("17/91 78/85 19/51 23/38 29/33 77/29 95/23 77/19 1/17 11/13 13/11 15/14 15/2 55/1", num, den);
    dump(num, den, 15);
    exec(2, 0, 15, num, den, 15);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
 
void stoogesort(int *a, int len)
{
    if (a[0] > a[len - 1]) {
        int tmp = a[0];
        a[0] = a[len - 1];
        a[len - 1] = tmp;
    }
    if (len - 1 > 1) {
        int t = len / 3;
        stoogesort(a, len - 1);
        stoogesort(a + t, len - t);
        stoogesort(a, len - 1);
    }
}
 
int main(void)
{
    int numbers[] = {1, 9, 4, 7, 6, 5, 3, 2, 8};
    int i;
    int len = sizeof(numbers) / sizeof(numbers[0]);
    printf("Before: ");
    for (i = 0; i < len; i++) {
        printf("%d ", numbers[i]);
    }
    printf("\n");
    stoogesort(numbers, len);
    printf("After: ");
    for (i = 0; i < len; i++) {
        printf("%d ", numbers[i]);
    }
    printf("\n");
    return 0;
}

