#define MAX_LINE_LEN 1024
 
int main() {
	FILE *f = fopen("sample.csv", "r");
	if (f == NULL) {
		perror("Error opening file");
		return EXIT_FAILURE;
	}
	char line[MAX_LINE_LEN];
	char *rows[100];
	int i = 0;
	while (fgets(line, MAX_LINE_LEN, f)!= NULL) {
		rows[i] = strdup(line);
		i++;
	}
	fclose(f);
	appendSum(rows, i);
	writeChanges(rows, i);
	return EXIT_SUCCESS;
}
 
void appendSum(char *rows[], int n) {
	char *sum = "SUM";
	char *new_rows[100];
	for (int i = 0; i < n; i++) {
		char *row = rows[i];
		char *new_row = malloc(strlen(row) + strlen(sum) + 2);
		strcpy(new_row, row);
		strcat(new_row, ",");
		strcat(new_row, sum);
		new_rows[i] = new_row;
	}
	for (int i = 1; i < n; i++) {
		char *row = new_rows[i];
		char *new_row = malloc(strlen(row) + strlen(sum) + 2);
		strcpy(new_row, row);
		strcat(new_row, ",");
		strcat(new_row, sum);
		new_rows[i] = new_row;
	}
	for (int i = 0; i < n; i++) {
		rows[i] = new_rows[i];
	}
}
 
void writeChanges(char *rows[], int n) {
	FILE *f = fopen("output.csv", "w");
	if (f == NULL) {
		perror("Error opening file");
		return;
	}
	for (int i = 0; i < n; i++) {
		fprintf(f, "%s", rows[i]);
	}
	fclose(f);
}

