#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include <math.h>
#include <assert.h>

// CARTESIAN PRODUCT OF THREE LISTS ------------------

// cartProd3 :: [a] -> [b] -> [c] -> [[a, b, c]]
int*** cartProd3(int* xs, int xs_len, int* ys, int ys_len, int* zs, int zs_len) {
    int*** result = malloc(xs_len * ys_len * zs_len * sizeof(int**));
    int result_len = 0;
    for (int i = 0; i < xs_len; i++) {
        for (int j = 0; j < ys_len; j++) {
            for (int k = 0; k < zs_len; k++) {
                int** triple = malloc(3 * sizeof(int*));
                triple[0] = xs[i];
                triple[1] = ys[j];
                triple[2] = zs[k];
                result[result_len++] = triple;
            }
        }
    }
    return result;
}

// TEST -----------------------------------------------
int main() {
    int xs[] = {1, 2};
    int ys[] = {3, 4};
    int zs[] = {5, 6};
    int*** result = cartProd3(xs, 2, ys, 2, zs, 2);
    for (int i = 0; i < 8; i++) {
        printf("[%d, %d, %d]\n", result[i][0], result[i][1], result[i][2]);
    }
    return 0;
}

#include <stdio.h>
