float agm(float x, float y);
 
int main(int argc, char *argv[]) {
    if (argc!= 3) {
        printf("Usage: %s <arg1> <arg2>\n", argv[0]);
        return 1;
    }
 
    float x = atof(argv[1]);
    float y = atof(argv[2]);
 
    float result = agm(x, y);
    printf("The arithmetic-geometric mean is %f\n", result);
 
    return 0;
}
 
float agm(float x, float y) {
    float e = 0.000001;
    float a = x;
    float g = y;
    float a1;
    float g1;
 
    if (a * g < 0) {
        printf("The arithmetric-geometric mean is undefined for numbers less than zero!\n");
        exit(1);
    } else {
        while (1) {
            a1 = (a + g) / 2;
            g1 = sqrt(a * g);
            a = a1;
            g = g1;
            if (fabs(a - g) < e) {
                return a;
            }
        }
    }
}

#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
 
typedef struct vector {
  int *data;
  int size;
  int capacity;
} vector;
 
void vector_init(vector *v) {
  v->data = malloc(sizeof(int) * 1);
  v->size = 0;
  v->capacity = 1;
}
 
void vector_push_back(vector *v, int value) {
  if (v->size == v->capacity) {
    v->capacity *= 2;
    v->data = realloc(v->data, sizeof(int) * v->capacity);
  }
  v->data[v->size] = value;
  v->size++;
}
 
bool vector_less(vector *a, vector *b) {
  int i = 0;
  while (i < a->size && i < b->size) {
    if (a->data[i] < b->data[i]) {
      return true;
    } else if (a->data[i] > b->data[i]) {
      return false;
    }
    i++;
  }
  return a->size < b->size;
}
 
int main() {
  vector a;
  vector_init(&a);
  vector_push_back(&a, 1);
  vector_push_back(&a, 2);
  vector_push_back(&a, 1);
  vector_push_back(&a, 3);
  vector_push_back(&a, 2);
  vector b;
  vector_init(&b);
  vector_push_back(&b, 1);
  vector_push_back(&b, 2);
  vector_push_back(&b, 0);
  vector_push_back(&b, 4);
  vector_push_back(&b, 4);
  vector_push_back(&b, 0);
  vector_push_back(&b, 0);
  vector_push_back(&b, 0);
  printf("%s\n", vector_less(&a, &b)? "true" : "false"); // prints "false"
  return 0;
}

