#include <stdio.h>
#include <stdlib.h>
 
double *deconv(double *g, double *f, int fs) {
    int n;
    double *h = (double *)malloc((sizeof(double)) * (fs - 1));
    for (n = 0; n < fs - 1; n++) {
        h[n] = g[n];
        int lower = (n >= fs)? n - fs + 1 : 0;
        int i;
        for (i = lower; i < n; i++) h[n] -= h[i] * f[n - i];
        h[n] /= f[0];
    }
    return h;
}
 
int main(int argc, char **argv) {
    double h[] = {-8.0, -9.0, -3.0, -1.0, -6.0, 7.0};
    double f[] = {-3.0, -6.0, -1.0,  8.0, -6.0,  3.0, -1.0, -9.0, 
                  -9.0,  3.0, -2.0,  5.0,  2.0, -2.0, -7.0, -1.0};
    double g[] = {24.0,  75.0, 71.0, -34.0,  3.0,  22.0, -45.0, 
                  23.0, 245.0, 25.0,  52.0, 25.0, -67.0, -96.0,
                  96.0,  31.0, 55.0,  36.0, 29.0, -43.0,  -7.0};
    int fs = sizeof(f) / sizeof(double);
    int n;
    for (n = 0; n < fs - 1; n++) printf("%.0f ", h[n]);
    printf("\n");
    double *h1 = deconv(g, f, fs);
    for (n = 0; n < fs - 1; n++) printf("%.0f ", h1[n]);
    printf("\n\n");
    for (n = 0; n < fs - 1; n++) printf("%.0f ", f[n]);
    printf("\n");
    double *g1 = deconv(g, h, fs);
    for (n = 0; n < fs - 1; n++) printf("%.0f ", g1[n]);
    printf("\n");
    free(h1);
    free(g1);
    return 0;
}

