#include <stdio.h>
#include <stdlib.h>
#include <string.h>
 
char *StripControlChars(char *arg)
{
    char *arrForm = arg;
    char *buffer = malloc(strlen(arg) + 1);
    int i = 0;
    int j = 0;
    while(arrForm[i]!= '\0')
    {
        if(!iscntrl(arrForm[i]))
        {
            buffer[j] = arrForm[i];
            j++;
        }
        i++;
    }
    buffer[j] = '\0';
    return buffer;
}
 
char *StripExtended(char *arg)
{
    char *buffer = malloc(strlen(arg) + 1);
    int i = 0;
    int j = 0;
    while(arg[i]!= '\0')
    {
        if((arg[i] >= 32) && (arg[i] <= 126))
        {
            buffer[j] = arg[i];
            j++;
        }
        i++;
    }
    buffer[j] = '\0';
    return buffer;
}
 
int main()
{
    char *test = "string of ☺☻♥♦⌂, may include control characters and other ilk.♫☼§►↔◄";
    printf("Original: %s\n", test);
    printf("Stripped of control codes: %s\n", StripControlChars(test));
    printf("Stripped of extended: %s\n", StripExtended(test));
    return 0;
}

#include <stdio.h>
#include <time.h>

/* Gets current time in milliseconds. */
long millis() {
  return (long)time(NULL) * 1000;
}

/* Executes function 'func' n times, returns array of execution times. */
long* benchmark(int n, void (*func)(), int args) {
  long* times = (long*)malloc(sizeof(long) * n);
  for (int i=0; i<n; i++) {
    long m = millis();
    func(args);
    times[i] = millis() - m;
  }
  return times;
}

int main() {
  long* times = benchmark(1000, func, 1000);
  for (int i=0; i<1000; i++) {
    printf("%ld\n", times[i]);
  }
  free(times);
  return 0;
}

