task_description:
Implement some operations on variable-length quantities, at least including conversions from a normal number in the language to the binary representation of the variable-length quantity for that number, and vice versa. Any variants are acceptable.



Task

With above operations,

convert these two numbers 0x200000 (2097152 in decimal) and 0x1fffff (2097151 in decimal) into sequences of octets (an eight-bit byte); 
display these sequences of octets;
convert these sequences of octets back to numbers, and check that they are equal to original numbers.

code:
// version 1.0.6
 
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
 
int toOctets(int n, unsigned char *ba) {
    char *s = malloc(sizeof(char) * 33);
    sprintf(s, "%x", n);
    int r = strlen(s) % 7;
    int z = strlen(s) / 7;
    if (r > 0) {
        z++;
        s = realloc(s, sizeof(char) * (z * 7 + 1));
        for (int i = strlen(s); i < z * 7; i++) s[i] = '0';
        s[z * 7] = '\0';
    }
    char *t = malloc(sizeof(char) * (z + 1));
    for (int i = 0; i < z; i++) t[i] = '1';
    t[z] = '\0';
    strcat(t, s);
    t[z * 8] = '\0';
    t[z * 8 - 8] = '0';
    for (int i = 0; i < z; i++) {
        char *u = malloc(sizeof(char) * 9);
        strncpy(u, t + i * 8, 8);
        u[8] = '\0';
        ba[i] = (unsigned char) strtol(u, NULL, 2);
        free(u);
    }
    free(s);
    free(t);
    return z;
}
 
int fromOctets(unsigned char *ba, int z) {
    char *s = malloc(sizeof(char) * (z * 8 + 1));
    for (int i = 0; i < z; i++) {
        char *t = malloc(sizeof(char) * 9);
        sprintf(t, "%08x", ba[i]);
        strncpy(s + i * 8, t + 1, 7);
        free(t);
    }
    s[z * 8] = '\0';
    int n = (int) strtol(s, NULL, 2);
    free(s);
    return n;
}
 
int main(int argc, char **argv) {
    int tests[] = {0x7f, 0x3fff, 0x200000, 0x1fffff};
    for (int i = 0; i < 4; i++) {
        unsigned char *ba = malloc(sizeof(char) * 4);
        int z = toOctets(tests[i], ba);
        printf("%8x -> ", tests[i]);
        for (int j = 0; j < z; j++) printf("0x%02x ", ba[j]);
        printf(" <- %x\n", fromOctets(ba, z));
        free(ba);
    }
    return 0;
}

