#define MAX_GUESSES 20

int main(int argc, char *argv[]) {
    srand(time(NULL));
    char num[5];
    // generate a 4 digit random number from 1234 to 9876 with no zeros or repeated digits
    do {
        int n = 1234 + rand() % 8643;
        sprintf(num, "%d", n);
    } while (strchr(num, '0') || strlen(set(num)) < 4);

    printf("All guesses should have exactly 4 distinct digits excluding zero.\n");
    printf("Keep guessing until you guess the chosen number (maximum %d valid guesses).\n\n", MAX_GUESSES);
    int guesses = 0;
    while (1) {
        printf("Enter your guess : ");
        char guess[5];
        scanf("%s", guess);
        if (strcmp(guess, num) == 0) {
            printf("You've won with %d valid guesses!\n", ++guesses);
            return 0;
        }
        int n = atoi(guess);
        if (n == 0)
            printf("Not a valid number\n");
        else if (strchr(guess, '-') || strchr(guess, '+'))
            printf("Can't contain a sign\n");
        else if (strchr(guess, '0'))
            printf("Can't contain zero\n");
        else if (strlen(guess)!= 4)
            printf("Must have exactly 4 digits\n");
        else if (strlen(set(guess)) < 4)
            printf("All digits must be distinct\n");
        else {
            int bulls = 0;
            int cows  = 0;
            for (int i = 0; i < 4; i++) {
                if (num[i] == guess[i]) bulls++;
                else if (strchr(num, guess[i])) cows++;
            }
            printf("Your score for this guess:  Bulls = %d  Cows = %d\n", bulls, cows);
            guesses++;
            if (guesses == MAX_GUESSES)
                printf("You've now had %d valid guesses, the maximum allowed\n", guesses);
        }
    }
}

char *set(char *s) {
    char *p = s;
    while (*p) {
        char *q = p + 1;
        while (*q) {
            if (*p == *q) *q = '\0';
            q++;
        }
        p++;
    }
    return s;
}

#include <stdio.h>
