#include <assert.h>
 
typedef struct {
    int *arr;
    int len;
    int pos;
} Wheel;
 
void init_wheel(Wheel *w, int *arr, int len) {
    w->arr = arr;
    w->len = len;
    w->pos = 0;
}
 
int next_wheel(Wheel *w) {
    int res = w->arr[w->pos];
    w->pos = (w->pos + 1) % w->len;
    return res;
}
 
int main() {
    int a1[] = {1, 2, 3};
    int a2[] = {1, 3, 4};
    int a3[] = {1, 6, 7, 8};
    int a4[] = {1, 3, 5};
