    int *arrs[] = {a1, a2, a3, a4, a5, a6};
    int lens[] = {3, 3, 4, 3, 2, 2};
    Wheel wheels[6];
    for (int i = 0; i < 6; i++) {
        init_wheel(&wheels[i], arrs[i], lens[i]);
    }
    for (int i = 0; i < 4; i++) {
        for (int j = 0; j < 20; j++) {
            int el = next_wheel(&wheels[0]);
            while (el >= 0) {
                el = next_wheel(&wheels[el]);
            }
            printf("%d ", el);
        }
        printf("\n");
    }
    return 0;
}

