#include <stdio.h>
#include <stdlib.h>
#include <string.h>
 
#define N 41
#define K 3
#define M 3
#define POSITION 5
 
int main(void) {
    int *prisoners = malloc(N * sizeof(int));
    int *executed = malloc(N * sizeof(int));
    int i;
    for (i = 0; i < N; i++) {
        prisoners[i] = i;
    }
 
    int to_kill = 0;
    int len = N;
 
    while (len > M) {
        to_kill = (to_kill + K - 1) % len;
        executed[N - len] = prisoners[to_kill];
        memmove(&prisoners[to_kill], &prisoners[to_kill + 1], (len - to_kill - 1) * sizeof(int));
        len -= 1;
    }
 
    printf("JOSEPHUS n=%d, k=%d, m=%d\n", N, K, M);
    printf("Executed: ");
    for (i = 0; i < N - M; i++) {
        printf("%d ", executed[i]);
    }
    printf("\n");
    printf("Executed position number %d: %d\n", POSITION, executed[POSITION - 1]);
    printf("Survivors: ");
    for (i = 0; i < M; i++) {
        printf("%d ", prisoners[i]);
    }
    printf("\n");
 
    free(prisoners);
    free(executed);
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
 
const char DIGITS[] = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz";
 
char *encode_negative_base(long n, int b) {
    if (b < -62 || b > -1) {
        fprintf(stderr, "b out of range\n");
        exit(1);
    }
    if (n == 0) {
        return "0";
    }
    char *output = malloc(sizeof(char) * 100);
    long nn = n;
    int i = 0;
    while (nn!= 0) {
        int rem = nn % b;
        nn /= b;
        if (rem < 0) {
            nn++;
            rem -= b;
        }
        output[i++] = DIGITS[rem];
    }
    output[i] = '\0';
    char *reversed = malloc(sizeof(char) * 100);
    int j = 0;
    for (int k = i - 1; k >= 0; k--) {
        reversed[j++] = output[k];
    }
    reversed[j] = '\0';
    return reversed;
}
 
long decode_negative_base(char *ns, int b) {
    if (b < -62 || b > -1) {
        fprintf(stderr, "b out of range\n");
        exit(1);
    }
    if (strcmp(ns, "0") == 0) {
        return 0;
    }
    long total = 0;
    long bb = 1;
    for (int i = strlen(ns) - 1; i >= 0; i--) {
        char c = ns[i];
        total += strchr(DIGITS, c) - DIGITS * bb;
        bb *= b;
    }
    return total;
}
 
int main(int argc, char *argv[]) {
    int nbl[][2] = {
        {10, -2},
        {146, -3},
        {15, -10},
        {-34025238427, -62},
    };
    for (int i = 0; i < 4; i++) {
        char *ns = encode_negative_base(nbl[i][0], nbl[i][1]);
        printf("%12ld encoded in base %3d = %s\n", nbl[i][0], nbl[i][1], ns);
        long n = decode_negative_base(ns, nbl[i][1]);
        printf("%12s decoded in base %3d = %ld\n", ns, nbl[i][1], n);
        printf("\n");
    }
    return 0;
}

// Version 1.3.21
 
int totient(int n) {
    int tot = n;
    int nn = n;
    int i = 2;
    while (i * i <= nn) {
        if (nn % i == 0) {
            while (nn % i == 0) nn /= i;
            tot -= tot / i;
        }
        if (i == 2) i = 1;
        i += 2;
    }
    if (nn > 1) tot -= tot / nn;
    return tot;
}
 
int main() {
    int perfect[20];
    int n = 1;
    int i = 0;
    while (i < 20) {
        int tot = n;
        int sum = 0;
        while (tot!= 1) {
            tot = totient(tot);
            sum += tot;
        }
        if (sum == n) {
            perfect[i] = n;
            i++;
        }
        n += 2;
    }
    printf("The first 20 perfect totient numbers are:\n");
    for (int j = 0; j < 20; j++) {
        printf("%d ", perfect[j]);
    }
    printf("\n");
    return 0;
}

void bline(int x0, int y0, int x1, int y1) {
  int dx = abs(x1 - x0), sx = x0 < x1? 1 : -1;
  int dy = abs(y1 - y0), sy = y0 < y1? 1 : -1; 
  int err = (dx>dy? dx : -dy)/2;
  while (true) {
    setPixel(x0,y0);
    if (x0 === x1 && y0 === y1) break;
    int e2 = err;
    if (e2 > -dx) { err -= dy; x0 += sx; }
    if (e2 < dy) { err += dx; y0 += sy; }
  }
}

