#include <stdio.h>
#include <stdbool.h>
 
bool isPrime(int n) {
    switch (n) {
    case 0:
    case 1:
        return false;
    case 2:
        return true;
    case 3:
        return true;
    default:
        int d = 5;
        while (d*d <= n) {
            if (n%d == 0) {
                return false;
            }
            d += 2;
            if (n%d == 0) {
                return false;
            }
            d += 4;
        }
        return true;
    }
}
 
int countPrimeFactors(int n) {
    switch (n) {
    case 1:
        return 0;
    default:
        int count = 0, f = 2;
        while (true) {
            if (n%f == 0) {
                count++;
                n /= f;
                if (n == 1) {
                    return count;
                }
                if (isPrime(n)) {
                    f = n;
                }
            } else if (f >= 3) {
                f += 2;
            } else {
                f = 3;
            }
        }
        return count;
    }
}
 
int main() {
    const int max = 120;
    printf("The attractive numbers up to and including %d are:\n", max);
    int count = 0;
    for (int i = 1; i <= max; i++) {
        int n = countPrimeFactors(i);
        if (isPrime(n)) {
            printf("%4d", i);
            count++;
            if (count % 20 == 0) {
                printf("\n");
            }
        }
    }
    printf("\n");
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

char *lastSundayOfEachMonths(int year) {
	int lastDay[12] = {31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
	char *sundays = malloc(10 * 12);
	char *date = malloc(10);
	int month;
	if (year % 4 == 0 && (year % 100!= 0 || year % 400 == 0)) {
		lastDay[2] = 29;
	}
	for (month = 0; month < 12; month += 1) {
		struct tm tm = {0};
		tm.tm_year = year - 1900;
		tm.tm_mon = month;
		tm.tm_mday = lastDay[month];
		mktime(&tm);
		tm.tm_mday -= tm.tm_wday;
		strftime(date, 10, "%Y-%m-%d", &tm);
		memcpy(sundays + 10 * month, date, 10);
	}
	free(date);
	return sundays;
}

int main(void) {
	char *sundays = lastSundayOfEachMonths(2013);
	int i;
	for (i = 0; i < 12; i += 1) {
		printf("%s\n", sundays + 10 * i);
	}
	free(sundays);
	return 0;
}

