int isEsthetic(int inp, int base) {
  char *arr = malloc(100);
  sprintf(arr, "%d", inp);
  int len = strlen(arr);
  if (len == 1) return 0;
  for (int i = 0; i < len; i++)
    arr[i] -= '0';
  for (i = 0; i < len-1; i++)
    if (abs(arr[i]-arr[i+1])!= 1) return 0;
  return 1;
}
 
int collectEsthetics(int base, int range[2]) {
  int out[1000000], x;
  if (range) {
    for (x = range[0]; x < range[1]; x++)
      if (isEsthetic(x, base)) printf("%d ", x);
    return 0;
  } else {
    x = 1;
    while (x < base*6) {
      char s[100];
      sprintf(s, "%d", x);
      if (isEsthetic(s, base)) printf("%s ", s);
      x++;
    }
    return 0;
  }
}
 
