#include <stdio.h>
#include <stdlib.h>
#include <time.h>
 
int in_order(int *l, int len) {
    if (len == 0) {
        return 1;
    }
    int last = l[0];
    int i;
    for (i = 1; i < len; i++) {
        if (l[i] < last) {
            return 0;
        }
        last = l[i];
    }
    return 1;
}
 
void shuffle(int *l, int len) {
    int i;
    for (i = 0; i < len; i++) {
        int j = rand() % len;
        int tmp = l[i];
        l[i] = l[j];
        l[j] = tmp;
    }
}
 
int *bogosort(int *l, int len) {
    while (!in_order(l, len)) {
        shuffle(l, len);
    }
    return l;
}
 
int main() {
    srand(time(NULL));
    int l[] = {5, 4, 3, 2, 1};
    int *sorted = bogosort(l, 5);
    int i;
    for (i = 0; i < 5; i++) {
        printf("%d ", sorted[i]);
    }
    printf("\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
 
// encoding scheme:
// encode to byte array
// byte value < 26 means single character: byte value + 'A'
// byte value 26..255 means (byte value - 24) copies of next byte
unsigned char *rllEncode(char *s) {
    int i, j, c, nc;
    unsigned char *r;
    int len = strlen(s);
    if (len == 0) {
        return NULL;
    }
    c = s[0];
    if (c < 'A' || c > 'Z') {
        printf("invalid\n");
        exit(1);
    }
    r = (unsigned char *)malloc(len);
    j = 0;
    nc = 1;
    for (i = 1; i < len; i++) {
        int d = s[i];
        switch (d) {
        case c:
            if (nc < (255 - 24)) {
                nc++;
                continue;
            }
            break;
        }
        if (nc > 1) {
            r[j++] = nc + 24;
        }
        r[j++] = c - 'A';
        if (d < 'A' || d > 'Z') {
            printf("invalid\n");
            exit(1);
        }
        c = d;
        nc = 1;
    }
    if (nc > 1) {
        r[j++] = nc + 24;
    }
    r[j++] = c - 'A';
    r = realloc(r, j);
    return r;
}
 
char *rllDecode(unsigned char *e) {
    int i, c;
    char *d;
    int len = strlen((char *)e);
    d = (char *)malloc(len);
    i = 0;
    c = 0;
    while (i < len) {
        unsigned char b = e[i];
        if (b < 26) {
            c = 1;
        } else {
            c = b - 24;
            i++;
            b = e[i];
        }
        while (c > 0) {
            d[i++] = b + 'A';
            c--;
        }
    }
    d = realloc(d, i);
    return d;
}
 
int main() {
    char *s = "WWWWWWWWWWWWBWWWWWWWWWWWWBBBWWWWWWWWWWWWWWWWWWWWWWWWBWWWWWWWWWWWWWW";
    printf("source: %d bytes: %s\n", strlen(s), s);
    unsigned char *e = rllEncode(s);
    printf("encoded: %d bytes: %s\n", strlen((char *)e), e);
    char *d = rllDecode(e);
    printf("decoded: %d bytes: %s\n", strlen(d), d);
    printf("decoded = source: %d\n", strcmp(d, s) == 0);
    return 0;
}

#include <stdio.h>
#include <math.h>
 
typedef struct {
    double x, y, r;
} circle;
 
circle ap(circle c1, circle c2, circle c3, int s);
 
int main() {
    circle c1 = {0, 0, 1};
    circle c2 = {4, 0, 1};
    circle c3 = {2, 4, 2};
    circle c4 = ap(c1, c2, c3, 1);
    circle c5 = ap(c1, c2, c3, 0);
    printf("%f %f %f\n", c4.x, c4.y, c4.r);
    printf("%f %f %f\n", c5.x, c5.y, c5.r);
    return 0;
}
 
circle ap(circle c1, circle c2, circle c3, int s) {
    double x1sq = c1.x * c1.x;
    double y1sq = c1.y * c1.y;
    double r1sq = c1.r * c1.r;
    double x2sq = c2.x * c2.x;
    double y2sq = c2.y * c2.y;
    double r2sq = c2.r * c2.r;
    double x3sq = c3.x * c3.x;
    double y3sq = c3.y * c3.y;
    double r3sq = c3.r * c3.r;
    double v11 = 2 * (c2.x - c1.x);
    double v12 = 2 * (c2.y - c1.y);
    double v13 = x1sq - x2sq + y1sq - y2sq - r1sq + r2sq;
    double v14 = 2 * (c2.r - c1.r);
    double v21 = 2 * (c3.x - c2.x);
    double v22 = 2 * (c3.y - c2.y);
    double v23 = x2sq - x3sq + y2sq - y3sq - r2sq + r3sq;
    double v24 = 2 * (c3.r - c2.r);
    if (s) {
        v14 = -v14;
        v24 = -v24;
    }
    double w12 = v12 / v11;
    double w13 = v13 / v11;
    double w14 = v14 / v11;
    double w22 = v22/v21 - w12;
    double w23 = v23/v21 - w13;
    double w24 = v24/v21 - w14;
    double p = -w23 / w22;
    double q = w24 / w22;
    double m = -w12*p - w13;
    double n = w14 - w12*q;
    double a = n*n + q*q - 1;
    double b = m*n - n*c1.x + p*q - q*c1.y;
    if (s) {
        b -= c1.r;
    } else {
        b += c1.r;
    }
    b *= 2;
    double c = x1sq + m*m - 2*m*c1.x + p*p + y1sq - 2*p*c1.y - r1sq;
    double d = b*b - 4*a*c;
    double rs = (-b - sqrt(d)) / (2 * a);
    return (circle){m + n*rs, p + q*rs, rs};
}

