#include <stdio.h>
#include <stdlib.h>
 
int fact(int n) {
  return n == 0? 1 : n * fact(n-1);
}
 
int lah(int n, int k) {
  switch (k) {
    case 1: return fact(n);
    case n: return 1;
    default: return n < 1? 0 : fact(n) * fact(n-1) / fact(k) / fact(k-1) / fact(n-k);
  }
}
 
int main(int argc, char *argv[]) {
  int i, j;
  printf("Unsigned Lah numbers: L(n, k):\n");
  printf("n/k ");
  for (i = 0; i <= 12; i++) printf("%11d", i);
  printf("\n");
  for (i = 0; i <= 12; i++) {
    printf("%-4d", i);
    for (j = 0; j <= i; j++) printf("%11d", lah(i, j));
    printf("\n");
  }
  printf("\nMaximum value from the L(100, *) row:\n");
  for (i = 1; i <= 100; i++) printf("%d\n", lah(100, i));
  return 0;
}

#include <stdio.h>
#include <string.h>
#include <ctype.h>

char *ltrim(char *s) {
    int i = 0;
    while (i < strlen(s) && isspace(s[i])) {
        i++;
    }
    return s + i;
}

char *rtrim(char *s) {
    int i = strlen(s) - 1;
    while (i > 0 && isspace(s[i])) {
        i--;
    }
    return s;
}

char *trim(char *s) {
    return rtrim(ltrim(s));
}

int main(int argc, char *argv[]) {
    char s[] = " \t \r \n String with spaces \u2009 \t  \r  \n  ";
    printf("[%s]\n", ltrim(s));
    printf("[%s]\n", rtrim(s));
    printf("[%s]\n", trim(s));
    return 0;
}

#include <stdio.h>
 
int gray_encode(int n) {
    return n ^ n >> 1;
}
 
int gray_decode(int n) {
    int m = n >> 1;
    while (m) {
        n ^= m;
        m >>= 1;
    }
    return n;
}
 
int main() {
    printf("DEC,   BIN =>  GRAY => DEC\n");
    for (int i = 0; i < 32; i++) {
        int gray = gray_encode(i);
        int dec = gray_decode(gray);
        printf("%2d, %05b => %05b => %2d\n", i, i, gray, dec);
    }
}

