typedef struct {
    int *data;
    int size;
} List;
 
List *list_create(int size) {
    List *list = malloc(sizeof(List));
    list->data = malloc(sizeof(int) * size);
    list->size = size;
    return list;
}
 
void list_free(List *list) {
    free(list->data);
    free(list);
}
 
void list_add(List *list, int value) {
    list->data[list->size++] = value;
}
 
char *extractRange(List *list) {
    if (list->size == 0) return "";
    char *sb = malloc(sizeof(char) * 1000);
    int first = list->data[0];
    int prev  = first;
 
    void append(int index) {
        if (first == prev) sprintf(sb, "%s%d", sb, prev);
        else if (first == prev - 1) sprintf(sb, "%s%d,%d", sb, first, prev);
        else sprintf(sb, "%s%d-%d", sb, first, prev);
        if (index < list->size - 1) sprintf(sb, "%s,", sb);
    }
 
    for (int i = 1; i < list->size; i++) {
        if (list->data[i] == prev + 1) prev++;
        else {
            append(i);
            first = list->data[i];
            prev  = first;
        }
    }
    append(list->size - 1);
    return sb;
}
 
