#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <time.h>
#include <SDL/SDL.h>
 
#define WIDTH 800
#define HEIGHT 800
#define MAX_ITERATIONS 450
#define MIN_X -0.5
#define MAX_X 0.5
#define MIN_Y -0.5
#define MAX_Y 0.5
#define JS_X 0.285
#define JS_Y 0.01
 
SDL_Surface *screen;
 
void putpixel(int x, int y, Uint32 pixel)
{
    Uint8 *target_pixel = (Uint8 *)screen->pixels + y * screen->pitch + x * 4;
    *(Uint32 *)target_pixel = pixel;
}
 
Uint32 getpixel(int x, int y)
{
    Uint8 *target_pixel = (Uint8 *)screen->pixels + y * screen->pitch + x * 4;
    return *(Uint32 *)target_pixel;
}
 
double remap(double x, double t1, double t2, double s1, double s2)
{
    double f = (x - t1) / (t2 - t1);
    double g = f * (s2 - s1) + s1;
    return g;
}
 
Uint32 getColor(int c)
{
    double r, g, b, p = c / 32.0, l = floor(p * 6), o = p * 6 - l, q = 1 - o;
    switch((int)l % 6) {
        case 0: r = 1; g = o; b = 0; break;
        case 1: r = q; g = 1; b = 0; break;
        case 2: r = 0; g = 1; b = o; break;
        case 3: r = 0; g = q; b = 1; break;
        case 4: r = o; g = 0; b = 1; break;
        case 5: r = 1; g = 0; b = q; break;
    }
    Uint32 c1 = (Uint32)(r * 255) << 16;
    Uint32 c2 = (Uint32)(g * 255) << 8;
    Uint32 c3 = (Uint32)(b * 255);
    return c1 | c2 | c3;
}
 
void drawFractal()
{
    double a, as, za, b, bs, zb, cnt;
    Uint32 clr;
    for(int j = 0; j < HEIGHT; j++) {
        for(int i = 0; i < WIDTH; i++) {
            a = remap(i, 0, WIDTH, MIN_X, MAX_X);
            b = remap(j, 0, HEIGHT, MIN_Y, MAX_Y);
            cnt = 0;
            while(++cnt < MAX_ITERATIONS) {
                za = a * a; zb = b * b;
                if(za + zb > 4) break;
                as = za - zb; bs = 2 * a * b;
                a = as + JS_X; b = bs + JS_Y;
            }
            if(cnt < MAX_ITERATIONS) {
                clr = getColor(cnt);
            }
            putpixel(i, j, clr);
        }
    }
}
 
int main(int argc, char *argv[])
{
    if(SDL_Init(SDL_INIT_VIDEO) < 0) {
        fprintf(stderr, "Unable to init SDL: %s\n", SDL_GetError());
        exit(1);
    }
    atexit(SDL_Quit);
    screen = SDL_SetVideoMode(WIDTH, HEIGHT, 32, SDL_HWSURFACE);
    if(screen == NULL) {
        fprintf(stderr, "Unable to set video mode: %s\n", SDL_GetError());
        exit(1);
    }
    drawFractal();
    SDL_Flip(screen);
    SDL_Delay(10000);
    return 0;
}

