#include <stdio.h>
#include <stdlib.h>
#include <math.h>
 
void disp(char *x) {
	printf("%s\n", x);
}
 
int fc[16], c2[16], c3[16];
int fact(int n) { return fc[n]? fc[n] : fc[n] = (n? n * fact(n - 1) : 1); }
int cata1(int n) { return (int)floor(fact(2 * n) / fact(n + 1) / fact(n) +.5); }
int cata2(int n) {
	if (n == 0) return 1;
	if (!c2[n]) {
		int s = 0;
		for (int i = 0; i < n; i++) s += cata2(i) * cata2(n - i - 1);
		c2[n] = s;
	}
	return c2[n];
}
int cata3(int n) {
	if (n == 0) return 1;
	return c3[n]? c3[n] : c3[n] = (4 * n - 2) * cata3(n - 1) / (n + 1);
}
 
int main() {
	disp("       meth1   meth2   meth3");
	for (int i = 0; i <= 15; i++)
		printf("%d\t%d\t%d\t%d\n", i, cata1(i), cata2(i), cata3(i));
	return 0;
}

void bubblesort(int *arr, int len) {
    int done = 0;
    while (!done) {
        done = 1;
        for (int i = 1; i<len; i++) {
            if (arr[i-1] > arr[i]) {
                done = 0;
                int temp = arr[i-1];
                arr[i-1] = arr[i];
                arr[i] = temp;
            }
        }
    }
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <gmp.h>
 
void generateFibonacci(mpz_t *fib, int n) {
    mpz_init_set_ui(fib[0], 1);
    mpz_init_set_ui(fib[1], 1);
    for (int i = 2; i < n; i++) {
        mpz_add(fib[i], fib[i - 2], fib[i - 1]);
    }
}
 
int main() {
    mpz_t *numbers = malloc(1000 * sizeof(mpz_t));
    generateFibonacci(numbers, 1000);
 
    int firstDigits[10] = {0};
    for (int i = 0; i < 1000; i++) {
        char *numberString = mpz_get_str(NULL, 10, numbers[i]);
        firstDigits[numberString[0] - '0']++;
        free(numberString);
    }
 
    for (int i = 1; i < 10; i++) {
        printf("%d %10.6f %10.6f\n", i, (double) firstDigits[i] / 1000, log10(1.0 + 1.0 / i));
    }
 
    for (int i = 0; i < 1000; i++) {
        mpz_clear(numbers[i]);
    }
    free(numbers);
 
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/wait.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>
#include <limits.h>
 
#define BUF_SIZE 1024
 
void check(int err) {
    if (err == -1) {
        perror("Error");
        exit(EXIT_FAILURE);
    }
}
 
int main() {
    char name[BUF_SIZE];
    while (name[0] == '\0') {
        printf("Enter output file name (without extension) : ");
        check(scanf("%s", name));
    }
    strcat(name, ".wav");
 
    int rate;
    while (rate < 2000 || rate > 192000) {
        printf("Enter sampling rate in Hz (2000 to 192000) : ");
        check(scanf("%d", &rate));
    }
    char rateS[BUF_SIZE];
    sprintf(rateS, "%d", rate);
 
    double dur;
    while (dur < 5 || dur > 30) {
        printf("Enter duration in seconds (5 to 30)        : ");
        check(scanf("%lf", &dur));
    }
    char durS[BUF_SIZE];
    sprintf(durS, "%f", dur);
 
    printf("OK, start speaking now...\n");
    // Default arguments: -c 1, -t wav. Note only signed 16 bit format supported.
    char *args[] = {"arecord", "-r", rateS, "-f", "S16_LE", "-d", durS, name, NULL};
    pid_t pid = fork();
    check(pid);
    if (pid == 0) {
        execvp("arecord", args);
        perror("Error");
        exit(EXIT_FAILURE);
    }
    int status;
    check(waitpid(pid, &status, 0));
 
    printf("'%s' created on disk and will now be played back...\n", name);
    char *args2[] = {"aplay", name, NULL};
    pid = fork();
    check(pid);
    if (pid == 0) {
        execvp("aplay", args2);
        perror("Error");
        exit(EXIT_FAILURE);
    }
    check(waitpid(pid, &status, 0));
    printf("Play-back completed.\n");
}

