#include <stdio.h>
#include <math.h>
 
int munchausen(int n) {
  int sum = 0;
  int d;
  int m;
  int i;
  for (i = n; i > 0; i = i / 10) {
    d = i % 10;
    m = pow(d, d);
    sum += m;
  }
  return sum == n;
}
 
int main() {
  int i;
  for (i = 1; i < 5000; i++) {
    if (munchausen(i)) {
      printf("%d\n", i);
    }
  }
  return 0;
}

