} Gecos;
 
typedef struct {
  char *account;
  char *password;
  int uid;
  int gid;
  Gecos *gecos;
  char *directory;
  char *shell;
} Passwd;
 
void free_gecos(Gecos *gecos) {
  free(gecos->fullname);
  free(gecos->office);
  free(gecos->extension);
  free(gecos->homephone);
  free(gecos->email);
  free(gecos);
}
 
void free_passwd(Passwd *passwd) {
  free(passwd->account);
  free(passwd->password);
  free(passwd->directory);
  free(passwd->shell);
  free_gecos(passwd->gecos);
  free(passwd);
}
 
char *gecos_to_s(Gecos *gecos) {
  char *s = malloc(strlen(gecos->fullname) + strlen(gecos->office) + strlen(gecos->extension) + strlen(gecos->homephone) + strlen(gecos->email) + 4);
  sprintf(s, "%s,%s,%s,%s,%s", gecos->fullname, gecos->office, gecos->extension, gecos->homephone, gecos->email);
  return s;
}
 
char *passwd_to_s(Passwd *passwd) {
  char *s = malloc(strlen(passwd->account) + strlen(passwd->password) + strlen(passwd->directory) + strlen(passwd->shell) + strlen(gecos_to_s(passwd->gecos)) + 6);
  sprintf(s, "%s:%s:%d:%d:%s:%s:%s", passwd->account, passwd->password, passwd->uid, passwd->gid, gecos_to_s(passwd->gecos), passwd->directory, passwd->shell);
  return s;
}
 
Passwd *new_passwd(char *account, char *password, int uid, int gid, Gecos *gecos, char *directory, char *shell) {
  Passwd *passwd = malloc(sizeof(Passwd));
  passwd->account = strdup(account);
  passwd->password = strdup(password);
  passwd->uid = uid;
  passwd->gid = gid;
  passwd->gecos = gecos;
  passwd->directory = strdup(directory);
  passwd->shell = strdup(shell);
  return passwd;
}
 
Gecos *new_gecos(char *fullname, char *office, char *extension, char *homephone, char *email) {
  Gecos *gecos = malloc(sizeof(Gecos));
  gecos->fullname = strdup(fullname);
  gecos->office = strdup(office);
  gecos->extension = strdup(extension);
  gecos->homephone = strdup(homephone);
  gecos->email = strdup(email);
  return gecos;
}
 
int main(int argc, char **argv) {
  Passwd *jsmith = new_passwd("jsmith", "x", 1001, 1000, new_gecos("", "Room 1007", "(234)555-8917", "(234)555-0077", ""), "/home/jsmith", "/bin/bash");
  Passwd *jdoe = new_passwd("jdoe", "x", 1002, 1000, new_gecos("", "Room 1004", "(234)555-8914", "(234)555-0044", ""), "/home/jdoe", "/bin/bash");
  Passwd *xyz = new_passwd("xyz", "x", 1003, 1000, new_gecos("X Yz", "Room 1003", "(234)555-8913", "(234)555-0033", ""), "/home/xyz", "/bin/bash");
  FILE *io;
  char *filename = "append.records.test";
  char *s;
  int i;
  
  // create the passwd file with two records
  io = fopen(filename, "w");
  fprintf(io, "%s\n", passwd_to_s(jsmith));
  fprintf(io, "%s\n", passwd_to_s(jdoe));
  fclose(io);
  
  printf("before appending:\n");
  io = fopen(filename, "r");
  while (fgets(s, 1024, io)) {
    printf("%s", s);
  }
  fclose(io);
  
  // append the third record
  io = fopen(filename, "a");
  fprintf(io, "%s\n", passwd_to_s(xyz));
  fclose(io);
  
  printf("after appending:\n");
  io = fopen(filename, "r");
  while (fgets(s, 1024, io)) {
