    double y;
} Point;
 
double ShoelaceArea(Point *v, int n) {
    double a = 0.0;
    for (int i = 0; i < n - 1; i++) {
        a += v[i].x * v[i + 1].y - v[i + 1].x * v[i].y;
    }
    return fabs(a + v[n - 1].x * v[0].y - v[0].x * v[n - 1].y) / 2.0;
}
 
int main() {
    Point v[] = {
        {3,4},
        {5,11},
        {12,8},
        {9,5},
        {5,6},
    };
    int n = sizeof(v) / sizeof(v[0]);
    double area = ShoelaceArea(v, n);
    printf("Given a polygon with vertices [");
    for (int i = 0; i < n; i++) {
        printf("(%g, %g)", v[i].x, v[i].y);
        if (i < n - 1) {
            printf(", ");
        }
    }
    printf("],\nits area is %g.\n", area);
    return 0;
}

#include <stdio.h>
#include <math.h>
 
typedef struct {
    double A;
    double B;
    double C;
    double D;
} Quaternion;
 
double Quaternion_Norm(Quaternion q)
{
    return sqrt(q.A * q.A + q.B * q.B + q.C * q.C + q.D * q.D);
}
 
Quaternion Quaternion_op_UnaryNegation(Quaternion q)
{
    Quaternion result;
    result.A = -q.A;
    result.B = -q.B;
    result.C = -q.C;
    result.D = -q.D;
    return result;
}
 
Quaternion Quaternion_Conjugate(Quaternion q)
{
    Quaternion result;
    result.A = q.A;
    result.B = -q.B;
    result.C = -q.C;
    result.D = -q.D;
    return result;
}
 
Quaternion Quaternion_op_Implicit(double d)
{
    Quaternion result;
    result.A = d;
    result.B = 0;
    result.C = 0;
    result.D = 0;
    return result;
}
 
Quaternion Quaternion_op_Addition(Quaternion q1, Quaternion q2)
{
    Quaternion result;
    result.A = q1.A + q2.A;
    result.B = q1.B + q2.B;
    result.C = q1.C + q2.C;
    result.D = q1.D + q2.D;
    return result;
}
 
Quaternion Quaternion_op_Multiply(Quaternion q1, Quaternion q2)
{
    Quaternion result;
    result.A = q1.A * q2.A - q1.B * q2.B - q1.C * q2.C - q1.D * q2.D;
    result.B = q1.A * q2.B + q1.B * q2.A + q1.C * q2.D - q1.D * q2.C;
    result.C = q1.A * q2.C - q1.B * q2.D + q1.C * q2.A + q1.D * q2.B;
    result.D = q1.A * q2.D + q1.B * q2.C - q1.C * q2.B + q1.D * q2.A;
    return result;
}
 
int Quaternion_op_Equality(Quaternion q1, Quaternion q2)
{
    return q1.A == q2.A && q1.B == q2.B && q1.C == q2.C && q1.D == q2.D;
}
 
int Quaternion_op_Inequality(Quaternion q1, Quaternion q2)
{
    return!(Quaternion_op_Equality(q1, q2));
}
 
int Quaternion_Equals(Quaternion q1, Quaternion q2)
{
    return Quaternion_op_Equality(q1, q2);
}
 
int Quaternion_GetHashCode(Quaternion q)
{
    return q.A ^ q.B ^ q.C ^ q.D;
}
 
void Quaternion_ToString(Quaternion q, char* buffer)
{
    sprintf(buffer, "Q(%f, %f, %f, %f)", q.A, q.B, q.C, q.D);
}
 
int main()
{
    Quaternion q1 = Quaternion_op_Implicit(1);
    Quaternion q2 = Quaternion_op_Implicit(2);
    Quaternion q3 = Quaternion_op_Addition(q1, q2);
    Quaternion q4 = Quaternion_op_Multiply(q1, q2);
    int eq = Quaternion_op_Equality(q1, q2);
    int neq = Quaternion_op_Inequality(q1, q2);
    int hash = Quaternion_GetHashCode(q1);
    char buffer[100];
    Quaternion_ToString(q1, buffer);
    printf("%s\n", buffer);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <inttypes.h>
 
const char *LOW[] = {
    "zero", "one", "two", "three", "four", "five",
    "six", "seven", "eight","nine", "ten",
    "eleven", "twelve", "thirteen", "fourteen", "fifteen",
    "sixteen", "seventeen", "eighteen", "nineteen"
};
const char *MED[] = {
    "twenty", "thirty", "forty", "fifty",
    "sixy", "seventy", "eighty", "ninety"
};
const char *HIGH[] = {
    "thousand", "million", "billion",
    "trillion", "quadrillion", "quintillion"
};
 
char *number_name(uint64_t num) {
    if (num < 20) {
        return strdup(LOW[num]);
    }
    if (num < 100) {
        int index = ((num / 10) - 2);
        char *tens = strdup(MED[index]);
        uint64_t remainder = num % 10;
        if (remainder > 0) {
            char *cur = number_name(remainder);
            char *ret = malloc(strlen(tens) + strlen(cur) + 2);
            sprintf(ret, "%s-%s", tens, cur);
            free(tens);
            free(cur);
            return ret;
        }
        return tens;
    }
    if (num < 1000) {
        char *hundreds = strdup(LOW[num / 100]);
        uint64_t remainder = num % 100;
        if (remainder > 0) {
            char *cur = number_name(remainder);
            char *ret = malloc(strlen(hundreds) + strlen(cur) + 11);
            sprintf(ret, "%s hundred %s", hundreds, cur);
            free(hundreds);
            free(cur);
            return ret;
        }
        char *ret = malloc(strlen(hundreds) + 8);
        sprintf(ret, "%s hundred", hundreds);
        free(hundreds);
        return ret;
    }
 
    uint64_t remainder = num % 1000;
    char *cur = (remainder > 0)? number_name(remainder) : strdup("");
    uint64_t n = num / 1000;
 
    for (int i = 0; i < 6; i++) {
        if (n > 0) {
            remainder = n % 1000;
            if (remainder > 0) {
                char *noun = strdup(HIGH[i]);
                char *tmp = number_name(remainder);
                char *ret = malloc(strlen(tmp) + strlen(noun) + strlen(cur) + 2);
                sprintf(ret, "%s %s %s", tmp, noun, cur);
                free(tmp);
                free(noun);
                free(cur);
                cur = ret;
            }
            n /= 1000;
        }
    }
    return cur;
}
 
void magic(uint64_t num) {
    if (num == 4) {
        printf("four is magic!\n\n");
        return;
    }
    char *name = number_name(num);
    uint64_t len = strlen(name);
    printf("%s is %s, ", name, number_name(len));
    free(name);
    magic(len);
}
 
int main() {
    magic(4);
    magic(2340);
    magic(765000);
    magic(27000001);
    magic(999123090);
    magic(239579832723441);
    magic(UINT64_MAX);
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
 
#define N 8
 
int moves[8][2] = { {+1,-2},{+2,-1},{+2,+1},{+1,+2},
                    {-1,+2},{-2,+1},{-2,-1},{-1,-2} };
 
typedef struct ListMoves
{
	int x, y;
} ListMoves;
 
int Move_Possible( int board[N][N], int cur_x, int cur_y )
{
	if ( board[cur_x][cur_y] >= 8 )
		return 0;
 
int new_x = cur_x + moves[board[cur_x][cur_y]][0],
    new_y = cur_y + moves[board[cur_x][cur_y]][1];
 
if ( new_x >= 0 && new_x < N && new_y >= 0 && new_y < N && board[new_x][new_y] == 0 )
	return 1;
 
return 0;
}
 
int main( int argc, char *argv[] )
{
	int board[N][N],
	    x = 0,
	    y = 0,
	    i;
	ListMoves *list;
	char *letters = "ABCDEFGH";
 
for( i=0; i<N*N; i++ )
	board[i/N][i%N] = 0;
 
list = (ListMoves*)malloc( N*N*sizeof(ListMoves) );
list[0].x = x;
list[0].y = y;
 
do
{
	if ( Move_Possible( board, x, y ) )
	{
		int move = board[x][y];
		board[x][y]++;
		x += moves[move][0];
		y += moves[move][1];
		list[i].x = x;
		list[i].y = y;
		i++;
	}
	else
	{
		if ( board[x][y] >= 8 )
		{
			board[x][y] = 0;
			i--;
			if ( i == 0 )
			{
				printf( "No solution found.\n" );
				return 0;
			}
			x = list[i-1].x;
			y = list[i-1].y;
		}
		board[x][y]++;
	}
}
while( i < N*N );
 
int last_x = list[0].x,
    last_y = list[0].y;
for( i=1; i<N*N; i++ )
{
	printf( "%2d:  %c%d - %c%d\n", i, letters[last_x], last_y+1, letters[list[i].x], list[i].y+1 );
	last_x = list[i].x;
	last_y = list[i].y;
}
 
return 0;
}

#include <Python.h>
#include <sys/stat.h>
#include <dirent.h>
#include <unistd.h>
#include <string.h>
 
static PyObject *
dodir(PyObject *self, PyObject *args)
{
    PyObject *h;
    char *path;
    DIR *dir;
    struct dirent *entry;
    struct stat st;
    char *p;
    int len;
 
    if (!PyArg_ParseTuple(args, "sO", &path, &h))
        return NULL;
 
    if ((dir = opendir(path)) == NULL)
        return PyErr_SetFromErrno(PyExc_OSError);
 
    while ((entry = readdir(dir))!= NULL) {
        if (strcmp(entry->d_name, ".") == 0 ||
            strcmp(entry->d_name, "..") == 0)
            continue;
 
        len = strlen(path) + strlen(entry->d_name) + 2;
        p = malloc(len);
        if (p == NULL) {
            closedir(dir);
            return PyErr_NoMemory();
        }
        sprintf(p, "%s/%s", path, entry->d_name);
 
        if (lstat(p, &st) == -1) {
            PyErr_SetFromErrnoWithFilename(PyExc_OSError, p);
            free(p);
            closedir(dir);
            return NULL;
        }
 
        if (S_ISLNK(st.st_mode)) {
            free(p);
            continue;
        }
        else if (S_ISREG(st.st_mode)) {
            PyObject *key = PyLong_FromLong(st.st_size);
            PyObject *val = PyDict_GetItem(h, key);
            if (val == NULL) {
                val = PyLong_FromLong(1);
                if (val == NULL) {
                    free(p);
                    closedir(dir);
                    return NULL;
                }
                if (PyDict_SetItem(h, key, val) == -1) {
                    free(p);
                    closedir(dir);
                    return NULL;
                }
                Py_DECREF(val);
            }
            else {
                Py_INCREF(val);
                if (PyDict_SetItem(h, key, PyLong_FromLong(PyLong_AsLong(val) + 1)) == -1) {
                    free(p);
                    closedir(dir);
                    return NULL;
                }
            }
            Py_DECREF(key);
        }
        else if (S_ISDIR(st.st_mode)) {
            if (dodir(self, Py_BuildValue("(sO)", p, h)) == NULL) {
                free(p);
                closedir(dir);
                return NULL;
            }
        }
        else {
            free(p);
            continue;
        }
        free(p);
    }
    closedir(dir);
    Py_RETURN_NONE;
}
 
static PyObject *
main(PyObject *self, PyObject *args)
{
    PyObject *h;
    PyObject *key, *val;
    PyObject *ret;
    PyObject *iter;
    long size, n, s;
 
    if (!PyArg_ParseTuple(args, "O", &h))
        return NULL;
 
    iter = PyObject_GetIter(h);
    if (iter == NULL)
        return NULL;
 
    n = s = 0;
    while ((key = PyIter_Next(iter))!= NULL) {
        val = PyDict_GetItem(h, key);
        if (val == NULL) {
            Py_DECREF(key);
            Py_DECREF(iter);
            return NULL;
        }
        size = PyLong_AsLong(key);
        n += PyLong_AsLong(val);
        s += size * PyLong_AsLong(val);
        printf("Size %ld -> %ld file(s)\n", size, PyLong_AsLong(val));
        Py_DECREF(key);
    }
    Py_DECREF(iter);
    ret = Py_BuildValue("ll", s, n);
    if (ret == NULL)
        return NULL;
    printf("Total %ld bytes for %ld files\n", s, n);
    return ret;
}
 
static PyMethodDef methods[] = {
    {"dodir", dodir, METH_VARARGS, NULL},
    {"main", main, METH_VARARGS, NULL},
    {NULL, NULL, 0, NULL}
};
 
static struct PyModuleDef module = {
    PyModuleDef_HEAD_INIT,
    "dirsize",
    NULL,
    -1,
    methods
};
 
PyMODINIT_FUNC
PyInit_dirsize(void)
{
    return PyModule_Create(&module);
}

typedef struct Node {
   void *element;
   struct Node *next;
   struct Node *prev;
} Node;

Node *newNode(Node *n, Node *p, void *elem) {
   Node *node = malloc(sizeof(Node));
   node->next = n;
   node->prev = p;
   node->element = elem;
   return node;
}

void setNext(Node *node, Node *n) {
   node->next = n;
}

Node *getNext(Node *node) {
   return node->next;
}

void setElem(Node *node, void *elem) {
   node->element = elem;
}

void *getElem(Node *node) {
   return node->element;
}

void setPrev(Node *node, Node *p) {
   node->prev = p;
}

Node *getPrev(Node *node) {
   return node->prev;
}

#include <stdio.h>
#include <stdlib.h>
#include <math.h>

double SpecialRound(double inValue)
{
    if (inValue > 1) return 1;

    double Splitters[] = { 0.00, 0.06, 0.11, 0.16, 0.21, 0.26, 0.31, 0.36, 0.41, 0.46, 0.51, 0.56, 0.61, 0.66, 0.71, 0.76, 0.81, 0.86, 0.91, 0.96 };
    double replacements[] = { 0.10, 0.18, 0.26, 0.32, 0.38, 0.44, 0.50, 0.54, 0.58, 0.62, 0.66, 0.70, 0.74, 0.78, 0.82, 0.86, 0.90, 0.94, 0.98, 1.00 };

    for (int x = 0; x < 19; x++)
    {
        if (inValue >= Splitters[x] && inValue < Splitters[x + 1])
        {
            return replacements[x];
        }
    }

    return inValue;
}

int main()
{
    for (int x = 0; x < 10; x++)
    {
        printf("In: %0.2f, Out: %0.2f\n", ((double)x) / 10, SpecialRound(((double)x) / 10));
    }

    printf("\n");

    for (int x = 0; x < 10; x++)
    {
        printf("In: %0.2f, Out: %0.2f\n", ((double)x) / 10 + 0.05, SpecialRound(((double)x) / 10 + 0.05));
    }

    printf("\n");
    printf("In: %0.2f, Out: %0.2f\n", 1.01, SpecialRound(1.01));

    return 0;
}

#include <stdio.h>
