int main(void)
{
    int inclusive_range[2] = {1, 100};
    int target, answer, i;
    srand(time(NULL));
    target = rand() % (inclusive_range[1] - inclusive_range[0] + 1) + inclusive_range[0];
    printf("Guess my target number that is between %i and %i (inclusive).\n", inclusive_range[0], inclusive_range[1]);
    for (i = 0; answer!= target; i++) {
        printf("Your guess(%i): ", i + 1);
        scanf("%i", &answer);
        if (answer < inclusive_range[0] || answer > inclusive_range[1]) {
            printf("  Out of range!\n");
            continue;
        }
        if (answer == target) {
            printf("  Ye-Haw!!\n");
            break;
        }
        if (answer < target) printf("  Too low.\n");
        if (answer > target) printf("  Too high.\n");
    }
    printf("\nThanks for playing.\n");
    return 0;
}

#include <stdio.h>
 
int kPrime(int n, int k) {
    int nf = 0;
    for (int i = 2; i <= n; i++) {
        while (n % i == 0) {
            if (nf == k) {
                return 0;
            }
            nf++;
            n /= i;
        }
    }
    return nf == k;
}
 
void gen(int k, int n, int *r) {
    n = 2;
    for (int i = 0; i < n; i++) {
        while (!kPrime(n, k)) {
            n++;
        }
        r[i] = n;
        n++;
    }
}
 
int main() {
    for (int k = 1; k <= 5; k++) {
        int r[10];
        gen(k, 10, r);
        printf("%d ", k);
        for (int i = 0; i < 10; i++) {
            printf("%d ", r[i]);
        }
        printf("\n");
    }
}

#include <stdio.h>
#include <math.h>
 
int prime(int a) {
    return!(a < 2 || (int)any(a % x == 0 for x in xrange(2, int(a**0.5) + 1)));
}
 
int primes_below(int n) {
    return [i for i in range(n) if prime(i)];
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <limits.h>
#include <stdbool.h>
 
#define n 61
 
int l[n];
 
int fusc(int n) {
    if (n < sizeof(l) / sizeof(l[0])) return l[n];
    int f = (n & 1) == 0? l[n >> 1] : l[(n - 1) >> 1] + l[(n + 1) >> 1];
    l[n] = f;
    return f;
}
 
int main() {
    bool lst = true;
    int w = -1;
    int c = 0;
    int t;
    char res[1000];
    res[0] = '\0';
    printf("First %d numbers in the fusc sequence:\n", n);
    for (int i = 0; i < INT_MAX; i++) {
        int f = fusc(i);
        if (lst) {
            if (i < n) {
                printf("%d ", f);
            } else {
                lst = false;
                printf("\nPoints in the sequence where an item has more digits than any previous items:\n");
                printf("%11s%s%9s\n", "Index\\", "  ", "/Value");
                printf("%s\n", res);
                res[0] = '\0';
            }
        }
        char buf[100];
        sprintf(buf, "%d", f);
        t = strlen(buf);
        if (t > w) {
            w = t;
            if (res[0]!= '\0') {
                strcat(res, "\n");
            }
            sprintf(buf, "%11d%s%9d", i, "  ", f);
            strcat(res, buf);
            if (!lst) {
                printf("%s\n", res);
                res[0] = '\0';
            }
            if (++c > 5) {
                break;
            }
        }
    }
    return 0;
}

#include <string.h>
#include <stdio.h>
 
int main()
{
    // Allocate enough memory to hold an instance of std::string
    char* data = malloc(sizeof(char) * 100);
 
    // use placement new to construct a std::string in the memory we allocated previously
    char* stringPtr = data;
    strcpy(stringPtr, "ABCD");
 
    printf("%s 0x%p\n", stringPtr, stringPtr);
 
    // use placement new to construct a new string object in the same memory location
    // remember to manually call destructor
    stringPtr = data;
    strcpy(stringPtr, "123456");
 
    printf("%s 0x%p\n", stringPtr, stringPtr);
 
    // clean up
    free(data);
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
 
char *ordinalize(int n)
{
    char *ordinal;
    int num = abs(n);
    int mod = num % 100;
    if (mod >= 11 && mod <= 13)
        ordinal = "th";
    else
    {
        switch (num % 10)
        {
            case 1:
                ordinal = "st";
                break;
            case 2:
                ordinal = "nd";
                break;
            case 3:
                ordinal = "rd";
                break;
            default:
                ordinal = "th";
        }
    }
    char *result = malloc(snprintf(NULL, 0, "%d%s", n, ordinal) + 1);
    sprintf(result, "%d%s", n, ordinal);
    return result;
}
 
int main(void)
{
    int i;
    for (i = 0; i < 26; i++)
        printf("%s, ", ordinalize(i));
    printf("\n");
    for (i = 250; i < 266; i++)
        printf("%s, ", ordinalize(i));
    printf("\n");
    for (i = 1000; i < 1026; i++)
        printf("%s, ", ordinalize(i));
    printf("\n");
    return 0;
}

