// version 1.0.6
 
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
 
#define MAX_SIZE 100
 
int jortSort(void *a, size_t size, size_t n, int (*cmp)(const void *, const void *)) {
    void *b = malloc(size * n);
    memcpy(b, a, size * n);
    qsort(b, n, size, cmp);
    for (int i = 0; i < n; i++)
        if (memcmp(a + i * size, b + i * size, size)!= 0) {
            free(b);
            return 0;
        }
    free(b);
    return 1;
}
 
void printResults(void *a, size_t size, size_t n, int (*cmp)(const void *, const void *)) {
    for (int i = 0; i < n; i++)
        printf("%d ", *(int *)(a + i * size));
    printf("=> %s\n", jortSort(a, size, n, cmp)? "sorted" : "not sorted");
}
 
int cmpInt(const void *a, const void *b) {
    return *(int *)a - *(int *)b;
}
 
int cmpChar(const void *a, const void *b) {
    return *(char *)a - *(char *)b;
}
 
int main(void) {
    int a[MAX_SIZE];
    a[0] = 1;
    a[1] = 2;
    a[2] = 3;
    a[3] = 4;
    a[4] = 5;
    printResults(a, sizeof(int), 5, cmpInt);
    int b[MAX_SIZE];
    b[0] = 2;
    b[1] = 1;
    b[2] = 3;
    b[3] = 4;
    b[4] = 5;
    printResults(b, sizeof(int), 5, cmpInt);
    printf("\n");
    char c[MAX_SIZE];
    c[0] = 'A';
    c[1] = 'B';
    c[2] = 'C';
    c[3] = 'D';
    c[4] = 'E';
    printResults(c, sizeof(char), 5, cmpChar);
    char d[MAX_SIZE];
    d[0] = 'C';
    d[1] = 'D';
    d[2] = 'A';
    d[3] = 'E';
    d[4] = 'B';
    printResults(d, sizeof(char), 5, cmpChar);
    return 0;
}

