char *commatize(unsigned long long n) {
    char *s = malloc(25);
    sprintf(s, "%llu", n);
    int le = strlen(s);
    for (int i = le - 3; i >= 1; i -= 3) {
        memmove(s + i + 1, s + i, le - i);
        s[i] = ',';
        le++;
    }
    return s;
}
 
int main() {
    unsigned long long starts[] = {100, 1000000, 10000000, 1000000000, 7123};
    int counts[] = {30, 15, 15, 10, 25};
    for (int i = 0; i < 5; i++) {
        int count = 0;
        unsigned long long j = starts[i];
        unsigned long long pow = 100;
        while (j < pow * 10) {
            pow *= 10;
        }
        printf("First %d gapful numbers starting at %s:\n", counts[i], commatize(starts[i]));
        while (count < counts[i]) {
            unsigned long long fl = (j / pow) * 10 + (j % 10);
            if (j % fl == 0) {
                printf("%llu ", j);
                count++;
            }
            j++;
            if (j >= 10 * pow) {
                pow *= 10;
            }
        }
        printf("\n\n");
    }
}

