#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <arpa/inet.h>
 
typedef struct {
    struct in_addr ip;
    int length;
} CIDR;
 
CIDR CIDR_Parse(char *cidr) {
    char *parts[2];
    char *token = strtok(cidr, "/");
    int i = 0;
    while (token!= NULL) {
        parts[i++] = token;
        token = strtok(NULL, "/");
    }
    CIDR cidr_struct;
    cidr_struct.ip.s_addr = inet_addr(parts[0]);
    cidr_struct.length = atoi(parts[1]);
    return cidr_struct;
}
 
CIDR CIDR_Canonicalize(CIDR cidr) {
    CIDR cidr_struct;
    cidr_struct.ip.s_addr = ntohl(htonl(cidr.ip.s_addr) & ~((1 << (32 - cidr.length)) - 1));
    cidr_struct.length = cidr.length;
    return cidr_struct;
}
 
char *CIDR_ToString(CIDR cidr) {
    char *ip = inet_ntoa(cidr.ip);
    char *length = malloc(sizeof(char) * 3);
    sprintf(length, "%d", cidr.length);
    char *cidr_string = malloc(sizeof(char) * (strlen(ip) + strlen(length) + 2));
    strcpy(cidr_string, ip);
    strcat(cidr_string, "/");
    strcat(cidr_string, length);
    return cidr_string;
}
 
int main() {
    char *tests[] = {
        "87.70.141.1/22",
        "36.18.154.103/12",
        "62.62.197.11/29",
        "67.137.119.181/4",
        "161.214.74.21/24",
        "184.232.176.184/18"
    };
 
    for (int i = 0; i < 6; i++) {
        CIDR cidr = CIDR_Parse(tests[i]);
        cidr = CIDR_Canonicalize(cidr);
        printf("%s   =>   %s\n", tests[i], CIDR_ToString(cidr));
    }
 
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <xmlrpc-c/base.h>
#include <xmlrpc-c/server.h>
#include <xmlrpc-c/server_abyss.h>
#include <xmlrpc-c/abyss.h>
 
static xmlrpc_value *
sample_add(xmlrpc_env *   const envP,
           xmlrpc_value * const paramArrayP,
           void *         const serverInfo,
           void *         const channelInfo) {
 
    xmlrpc_int32 x, y, sum;
 
    xmlrpc_decompose_value(envP, paramArrayP, "(ii)", &x, &y);
    if (envP->fault_occurred)
        return NULL;
 
    sum = x + y;
 
    return xmlrpc_build_value(envP, "i", sum);
}
 
static xmlrpc_value *
sample_div(xmlrpc_env *   const envP,
           xmlrpc_value * const paramArrayP,
           void *         const serverInfo,
           void *         const channelInfo) {
 
    xmlrpc_int32 x, y, quotient;
 
    xmlrpc_decompose_value(envP, paramArrayP, "(ii)", &x, &y);
    if (envP->fault_occurred)
        return NULL;
 
    quotient = x / y;
 
    return xmlrpc_build_value(envP, "i", quotient);
}
 
int
main(int           const argc,
     const char ** const argv) {
 
    xmlrpc_server_abyss_parms serverparm;
    xmlrpc_registry * registryP;
    xmlrpc_env env;
 
    xmlrpc_env_init(&env);
 
    registryP = xmlrpc_registry_new(&env);
    if (env.fault_occurred) {
        fprintf(stderr, "xmlrpc_registry_new failed.  %s\n",
                env.fault_string);
        exit(1);
    }
 
    xmlrpc_registry_add_method(&env, registryP, NULL, "sample.add",
                               &sample_add, NULL);
    if (env.fault_occurred) {
        fprintf(stderr, "Failed to add method sample.add.  %s\n",
                env.fault_string);
        exit(1);
    }
 
    xmlrpc_registry_add_method(&env, registryP, NULL, "sample.div",
                               &sample_div, NULL);
    if (env.fault_occurred) {
        fprintf(stderr, "Failed to add method sample.div.  %s\n",
                env.fault_string);
        exit(1);
    }
 
    serverparm.config_file_name = "xmlrpc_sample.conf";
    serverparm.registryP = registryP;
    serverparm.port_number = 8080;
 
    xmlrpc_server_abyss(&env, &serverparm, XMLRPC_APSIZE(registryP));
    if (env.fault_occurred) {
        fprintf(stderr, "xmlrpc_server_abyss failed.  %s\n",
                env.fault_string);
        exit(1);
    }
 
    return 0;
}

#include <stdio.h>
#include <math.h>
 
typedef struct {
    double value;
    double error;
} Approx;
 
Approx Approx_new(Approx b){
    Approx this;
    this.value = b.value;
    this.error = b.error;
    return this;
}
 
Approx Approx_new2(double value, double error){
    Approx this;
    this.value = value;
    this.error = error;
    return this;
}
 
Approx Approx_add(Approx this, Approx b){
    this.value+= b.value;
    this.error = sqrt(this.error * this.error + b.error * b.error);
    return this;
}
 
Approx Approx_add2(Approx this, double b){
    this.value+= b;
    return this;
}
 
Approx Approx_sub(Approx this, Approx b){
    this.value-= b.value;
    this.error = sqrt(this.error * this.error + b.error * b.error);
    return this;
}
 
Approx Approx_sub2(Approx this, double b){
    this.value-= b;
    return this;
}
 
Approx Approx_mult(Approx this, Approx b){
    double oldVal = this.value;
    this.value*= b.value;
    this.error = sqrt(this.value * this.value * (this.error*this.error) / (oldVal*oldVal) +
                                  (b.error*b.error) / (b.value*b.value));
    return this;
}
 
Approx Approx_mult2(Approx this, double b){
    this.value*= b;
    this.error = fabs(b * this.error);
    return this;
}
 
Approx Approx_div(Approx this, Approx b){
    double oldVal = this.value;
    this.value/= b.value;
    this.error = sqrt(this.value * this.value * (this.error*this.error) / (oldVal*oldVal) +
                                  (b.error*b.error) / (b.value*b.value));
    return this;
}
 
Approx Approx_div2(Approx this, double b){
    this.value/= b;
    this.error = fabs(b * this.error);
    return this;
}
 
Approx Approx_pow(Approx this, double b){
    double oldVal = this.value;
    this.value = pow(this.value, b);
    this.error = fabs(this.value * b * (this.error / oldVal));
    return this;
}
 
void Approx_print(Approx this){
    printf("%f±%f\n", this.value, this.error);
}
 
int main(){
    Approx x1 = Approx_new2(100, 1.1);
    Approx y1 = Approx_new2(50, 1.2);
    Approx x2 = Approx_new2(200, 2.2);
    Approx y2 = Approx_new2(100, 2.3);
 
    Approx_pow(Approx_add(Approx_sub(Approx_sub(x1, x2), Approx_sub(y1, y2)), 2), 0.5);
 
    Approx_print(x1);
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <curl/curl.h>

struct MemoryStruct {
  char *memory;
  size_t size;
};

static size_t
WriteMemoryCallback(void *contents, size_t size, size_t nmemb, void *userp)
{
  size_t realsize = size * nmemb;
  struct MemoryStruct *mem = (struct MemoryStruct *)userp;

  mem->memory = realloc(mem->memory, mem->size + realsize + 1);
  if(mem->memory == NULL) {
    /* out of memory! */
    printf("not enough memory (realloc returned NULL)\n");
    return 0;
  }

  memcpy(&(mem->memory[mem->size]), contents, realsize);
  mem->size += realsize;
  mem->memory[mem->size] = 0;

  return realsize;
}

int main(void)
{
  CURL *curl_handle;
  CURLcode res;

  struct MemoryStruct chunk;

  chunk.memory = malloc(1);  /* will be grown as needed by the realloc above */
  chunk.size = 0;    /* no data at this point */

  curl_global_init(CURL_GLOBAL_ALL);

  /* init the curl session */
  curl_handle = curl_easy_init();

  /* specify URL to get */
  curl_easy_setopt(curl_handle, CURLOPT_URL, "http://www.puzzlers.org/pub/wordlists/unixdict.txt");

  /* send all data to this function  */
  curl_easy_setopt(curl_handle, CURLOPT_WRITEFUNCTION, WriteMemoryCallback);

  /* we pass our 'chunk' struct to the callback function */
  curl_easy_setopt(curl_handle, CURLOPT_WRITEDATA, (void *)&chunk);

  /* some servers don't like requests that are made without a user-agent
     field, so we provide one */
  curl_easy_setopt(curl_handle, CURLOPT_USERAGENT, "libcurl-agent/1.0");

  /* get it! */
  res = curl_easy_perform(curl_handle);

  /* check for errors */
  if(res!= CURLE_OK) {
    fprintf(stderr, "curl_easy_perform() failed: %s\n",
            curl_easy_strerror(res));
  }
  else {
    /*
     * Now, our chunk.memory points to a memory block that is chunk.size
     * bytes big and contains the remote file.
     *
     * Do something nice with it!
     */

    printf("%lu bytes retrieved\n", (long)chunk.size);
  }

  /* cleanup curl stuff */
  curl_easy_cleanup(curl_handle);

  free(chunk.memory);

  /* we're done with libcurl, so clean it up */
  curl_global_cleanup();

  return 0;
}

#include <stdio.h>
#include <math.h>
 
typedef struct {
	double r;
	double i;
} Complex;
 
Complex Complex_add(Complex num, Complex *args, int ilim) {
	int i;
	for(i = 0; i < ilim; i += 1){
		num.r += args[i].r;
		num.i += args[i].i;
	}
	return num;
}
 
Complex Complex_multiply(Complex num, Complex *args, int ilim) {
	int i;
	for(i = 0; i < ilim; i += 1){
		num.r = (num.r * args[i].r) - (num.i * args[i].i);
		num.i = (num.i * args[i].r) - (num.r * args[i].i);
	}
	return num;
}
 
Complex Complex_negate(Complex z) {
	Complex num;
	num.r = -1*z.r;
	num.i = -1*z.i;
	return num;
}
 
Complex Complex_invert(Complex z) {
	Complex num;
	double denom = pow(z.r,2) + pow(z.i,2);
	num.r = z.r/denom;
	num.i = -1*z.i/denom;
	return num;
}
 
Complex Complex_conjugate(Complex z) {
	Complex num;
	num.r = z.r;
	num.i = -1*z.i;
	return num;
}
 
// BONUSES!
 
char *Complex_toString(Complex z) {
	char *str = malloc(sizeof(char) * 100);
	if(z.r === 0 && z.i === 0){
		sprintf(str, "0");
	} else {
		sprintf(str, "%s%s%s", (z.r!== 0? z.r : ""), ((z.r!== 0 || z.i < 0) && z.i!== 0? (z.i > 0? "+" : "-") : "" ), ( z.i!== 0? abs(z.i) + "i" : "" ));
	}
	return str;
}
 
double Complex_getMod(Complex z) {
	return sqrt( pow(z.r,2), pow(z.i,2) );
}

