size_t write_data(void *ptr, size_t size, size_t nmemb, void *stream)
{
    size_t realsize = size * nmemb;
    char *data = realloc(stream, realsize + 1);
 
    if(data) {
        memcpy(data, ptr, realsize);
        data[realsize] = 0;
    }
    return realsize;
}

