#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <unistd.h>
#include <semaphore.h>
 
#define NUM_THREADS 6
 
void *Worker(void *arg)
{
    sem_t *sem = (sem_t *)arg;
    sem_wait(sem);
    printf("Thread %d has a semaphore & is now working.\n", (int)pthread_self());
    sleep(2);
    printf("#%d done.\n", (int)pthread_self());
    sem_post(sem);
    return NULL;
}
 
int main()
{
    sem_t *semaphore = malloc(sizeof(sem_t));
    sem_init(semaphore, 0, sysconf(_SC_NPROCESSORS_ONLN)*2);
    printf("You have %d processors available\n", sysconf(_SC_NPROCESSORS_ONLN));
    printf("This program will use %d semaphores.\n", sysconf(_SC_NPROCESSORS_ONLN)*2);
    pthread_t threads[NUM_THREADS];
    int i;
    for (i = 0; i < NUM_THREADS; i++)
        pthread_create(&threads[i], NULL, Worker, semaphore);
    for (i = 0; i < NUM_THREADS; i++)
        pthread_join(threads[i], NULL);
    sem_destroy(semaphore);
    free(semaphore);
    return 0;
}

