#include <stdio.h>
#include <stdlib.h>
#include <string.h>
 
typedef struct {
    int *arr;
} BellTriangle;
 
BellTriangle *BellTriangle_new(int n) {
    BellTriangle *bt = malloc(sizeof(BellTriangle));
    int length = n * (n + 1) / 2;
    bt->arr = malloc(sizeof(int) * length);
    memset(bt->arr, 0, sizeof(int) * length);
 
    bt->arr[0] = 1;
    for (int i = 2; i <= n; ++i) {
        bt->arr[i * (i - 1) / 2] = bt->arr[(i - 1) * (i - 2) / 2];
        for (int j = 1; j < i; ++j) {
            int value = bt->arr[i * (i - 1) / 2 + j - 1] + bt->arr[(i - 1) * (i - 2) / 2 + j - 1];
            bt->arr[i * (i - 1) / 2 + j] = value;
        }
    }
 
    return bt;
}
 
int BellTriangle_get(BellTriangle *bt, int row, int col) {
    if (row > 0 && col >= 0 && col < row) {
        return bt->arr[row * (row - 1) / 2 + col];
    } else {
        return -1;
    }
}
 
void BellTriangle_free(BellTriangle *bt) {
    free(bt->arr);
    free(bt);
}
 
int main(int argc, char *argv[]) {
    const int rows = 15;
    BellTriangle *bt = BellTriangle_new(rows);
 
    printf("First fifteen Bell numbers:\n");
    for (int i = 0; i < rows; ++i) {
        printf("%2d: %d\n", i + 1, BellTriangle_get(bt, i + 1, 0));
    }
 
    for (int i = 1; i <= 10; ++i) {
        printf("%d", BellTriangle_get(bt, i, 0));
        for (int j = 1; j < i; ++j) {
            printf(", %d", BellTriangle_get(bt, i, j));
        }
        printf("\n");
    }
 
    BellTriangle_free(bt);
 
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <math.h>
 
#define MAX_FANGS 16
 
void show_fangs(unsigned long x, unsigned long f[], int cnt);
int fangs(unsigned long x, unsigned long f[], unsigned long tens[]);
unsigned long dtally(unsigned long x);
int ndigits(unsigned long x);
 
int main(int argc, char *argv[])
{
    int i, j, n;
    unsigned long x;
    unsigned long f[MAX_FANGS];
    unsigned long bigs[] = { 16758243290880UL, 24959017348650UL, 14593825548650UL, 0 };
    unsigned long tens[20];
    tens[0] = 1;
    for (i = 1; i < 20; i++)
        tens[i] = tens[i - 1] * 10;
 
    for (x = 1, n = 0; n < 25; x++)
    {
        if ((j = fangs(x, f, tens)) == 0) continue;
        printf("%d: ", ++n);
        show_fangs(x, f, j);
    }
 
    for (i = 0; bigs[i] > 0 ; i++)
    {
        if ((j = fangs(bigs[i], f, tens)) > 0)
            show_fangs(bigs[i], f, j);
        else
            printf("%lu is not vampiric.\n", bigs[i]);
    }
    return 0;
}
 
void show_fangs(unsigned long x, unsigned long f[], int cnt)
{
    int i;
    printf("%lu", x);
    for (i = 0; i < cnt; i++)
        printf(" = %lu * %lu", f[i], x / f[i]);
    printf("\n");
}
 
int fangs(unsigned long x, unsigned long f[], unsigned long tens[])
{
    int n = 0;
    int nd = ndigits(x);
    if ((nd & 1) > 0) return 0;
    nd /= 2;
 
    unsigned long lo, hi;
    lo = fmax(tens[nd - 1], (x + tens[nd] - 2) / (tens[nd] - 1));
    hi = fmin(x / lo, (unsigned long) sqrt(x));
 
    unsigned long a, b, t = dtally(x);
    for (a = lo; a <= hi; a++)
    {
        b = x / a;
        if (a * b == x && ((a % 10) > 0 || (b % 10) > 0) && t == dtally(a) + dtally(b))
            f[n++] = a;
    }
 
    return n;
}
 
unsigned long dtally(unsigned long x)
{
    unsigned long t = 0;
    while (x > 0)
    {
        t += 1UL << (int)((x % 10) * 6);
        x /= 10;
    }
 
    return t;
}
 
int ndigits(unsigned long x)
{
    int n = 0;
    while (x > 0)
    {
        n++;
        x /= 10;
    }
    return n;
}

