}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <math.h>
 
typedef struct {
    int64_t Numerator;
    int64_t Denominator;
} Fraction;
 
Fraction* Fraction_new(double f, int64_t MaximumDenominator)
{
    /* Translated from the C version. */
    /*  a: continued fraction coefficients. */
    int64_t a;
    int64_t h[3] = { 0, 1, 0 };
    int64_t k[3] = { 1, 0, 0 };
    int64_t x, d, n = 1;
    int i, neg = 0;
 
    if (MaximumDenominator <= 1)
    {
        Fraction* f = malloc(sizeof(Fraction));
        f->Denominator = 1;
        f->Numerator = (int64_t)f;
        return f;
    }
 
    if (f < 0) { neg = 1; f = -f; }
 
    while (f!= floor(f)) { n <<= 1; f *= 2; }
    d = (int64_t)f;
 
    /* continued fraction and check denominator each step */
    for (i = 0; i < 64; i++)
    {
        a = (n!= 0)? d / n : 0;
        if ((i!= 0) && (a == 0)) break;
 
        x = d; d = n; n = x % n;
 
        x = a;
        if (k[1] * a + k[0] >= MaximumDenominator)
        {
            x = (MaximumDenominator - k[0]) / k[1];
            if (x * 2 >= a || k[1] >= MaximumDenominator)
                i = 65;
            else
                break;
        }
 
        h[2] = x * h[1] + h[0]; h[0] = h[1]; h[1] = h[2];
        k[2] = x * k[1] + k[0]; k[0] = k[1]; k[1] = k[2];
    }
    Fraction* f = malloc(sizeof(Fraction));
    f->Denominator = k[1];
    f->Numerator = neg!= 0? -h[1] : h[1];
    return f;
}
 
void Fraction_print(Fraction* f)
{
    printf("%lld / %lld", f->Numerator, f->Denominator);
}
 
int main(int argc, char** argv)
{
    double d;
    Fraction* f;
    for (d = 0.9054054; d <= 0.90909; d += 0.00001)
    {
        f = Fraction_new(d, d >= 2? 65536 : 4096);
        printf("%20.10f → ", d);
        Fraction_print(f);
        printf("\n");
        free(f);
    }
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
 
int pow(int n, unsigned int e) {
    if (e == 0) {
        return 1;
    }
    int prod = n;
    for (unsigned int i = 2; i <= e; i++) {
        prod *= n;
    }
    return prod;
}
 
int abs(int n) {
    if (n >= 0) {
        return n;
    }
    return -n;
}
 
char *commatize(int n) {
    char *s = malloc(100);
    sprintf(s, "%d", n);
    if (n < 0) {
        s++;
    }
    int le = strlen(s);
    for (int i = le - 3; i >= 1; i -= 3) {
        memmove(s + i + 1, s + i, le - i);
        s[i] = ',';
    }
    if (n >= 0) {
        return s;
    }
    return strcat(s, "-");
}
 
int main() {
    int prod = 1;
    int sum = 0;
    const int x = 5;
    const int y = -5;
    const int z = -2;
    const int one = 1;
    const int three = 3;
    const int seven = 7;
    int p = pow(11, x);
    int j;
 
    void process() {
        sum += abs(j);
        if (abs(prod) < (1<<27) && j!= 0) {
            prod *= j;
        }
    }
 
    for (j = -three; j <= pow(3, 3); j += three) {
        process();
    }
    for (j = -seven; j <= seven; j += x) {
        process();
    }
    for (j = 555; j <= 550-y; j++) {
        process();
    }
    for (j = 22; j >= -28; j -= three) {
        process();
    }
    for (j = 1927; j <= 1939; j++) {
        process();
    }
    for (j = x; j >= y; j -= -z) {
        process();
    }
    for (j = p; j <= p+one; j++) {
        process();
    }
    printf("sum  = %s\n", commatize(sum));
    printf("prod = %s\n", commatize(prod));
}

#include <Python.h>

typedef struct {
	PyObject_HEAD
	PyObject *datum;
} Borg;

static PyObject *Borg_new(PyTypeObject *type, PyObject *args, PyObject *kwds)
{
	Borg *self;
	self = (Borg *)type->tp_alloc(type, 0);
	if (self!= NULL) {
		self->datum = PyDict_New();
		if (self->datum == NULL) {
			Py_DECREF(self);
			return NULL;
		}
	}
	return (PyObject *)self;
}

static void Borg_dealloc(Borg *self)
{
	Py_XDECREF(self->datum);
	Py_TYPE(self)->tp_free((PyObject *)self);
}

static PyMemberDef Borg_members[] = {
	{"datum", T_OBJECT_EX, offsetof(Borg, datum), 0,
	 "datum"},
	{NULL}  /* Sentinel */
};

static PyTypeObject BorgType = {
	PyVarObject_HEAD_INIT(NULL, 0)
	"borg.Borg",             /* tp_name */
	sizeof(Borg),            /* tp_basicsize */
	0,                       /* tp_itemsize */
	(destructor)Borg_dealloc, /* tp_dealloc */
	0,                       /* tp_print */
	0,                       /* tp_getattr */
	0,                       /* tp_setattr */
	0,                       /* tp_reserved */
	0,                       /* tp_repr */
	0,                       /* tp_as_number */
	0,                       /* tp_as_sequence */
	0,                       /* tp_as_mapping */
	0,                       /* tp_hash  */
	0,                       /* tp_call */
	0,                       /* tp_str */
	0,                       /* tp_getattro */
	0,                       /* tp_setattro */
	0,                       /* tp_as_buffer */
	Py_TPFLAGS_DEFAULT | Py_TPFLAGS_BASETYPE, /* tp_flags */
	"Borg objects",          /* tp_doc */
	0,                       /* tp_traverse */
	0,                       /* tp_clear */
	0,                       /* tp_richcompare */
	0,                       /* tp_weaklistoffset */
	0,                       /* tp_iter */
	0,                       /* tp_iternext */
	0,                       /* tp_methods */
	Borg_members,            /* tp_members */
	0,                       /* tp_getset */
	0,                       /* tp_base */
	0,                       /* tp_dict */
	0,                       /* tp_descr_get */
	0,                       /* tp_descr_set */
	0,                       /* tp_dictoffset */
	0,                       /* tp_init */
	0,                       /* tp_alloc */
	Borg_new,                /* tp_new */
};

static PyMethodDef module_methods[] = {
	{NULL}  /* Sentinel */
};

static struct PyModuleDef borgmodule = {
	PyModuleDef_HEAD_INIT,
	"borg",
	NULL,
	-1,
	module_methods,
	NULL,
	NULL,
	NULL,
	NULL
};

PyMODINIT_FUNC
PyInit_borg(void)
{
	PyObject* m;

	if (PyType_Ready(&BorgType) < 0)
		return NULL;

	m = PyModule_Create(&borgmodule);
	if (m == NULL)
		return NULL;

	Py_INCREF(&BorgType);
	PyModule_AddObject(m, "Borg", (PyObject *)&BorgType);
	return m;
}

#include <stdio.h>
#include <stdlib.h>
#include <math.h>
#include <time.h>
 
double factorial(int n) {
    double p = 1;
    for (int i = 1; i <= n; i++) {
        p *= i;
    }
    return p;
}
 
double analytical(int n) {
    double sum = 0;
    for (int i = 1; i <= n; i++) {
        sum += factorial(n) / pow(n, i) / factorial(n - i);
    }
    return sum;
}
 
double empirical(int n, int trials) {
    double sum = 0;
    for (int t = 0; t < trials; t++) {
        int item = 1;
        int seen[n];
        for (int i = 0; i < n; i++) {
            seen[i] = 0;
        }
        for (int step = 0; step < n; step++) {
            if (seen[item - 1]) {
                sum += step;
                break;
            }
            seen[item - 1] = 1;
            item = rand() % n + 1;
        }
        if (step == n) {
            sum += n;
        }
    }
    return sum / trials;
}
 
int main(int argc, char *argv[]) {
    int max_n = 20;
    int trials = 1000;
 
    if (argc == 3) {
        max_n = atoi(argv[1]);
        trials = atoi(argv[2]);
    }
 
    printf(" N    average    analytical    (error)\n");
    printf("===  =========  ============  ========\n");
    for (int n = 1; n <= max_n; n++) {
        double the_analytical = analytical(n);
        double the_empirical = empirical(n, trials);
        printf(" %2d     %3.4f        %3.4f  ( %+1.2f%%)\n",
               n,
               the_empirical,
               the_analytical,
               100 * (the_empirical / the_analytical - 1));
    }
}

