    m[1][1].fixed = 1;
 
    m[6][7].v = -1.0;
    m[6][7].fixed = -1;
}
 
double calcuate_difference(Node** m, Node** d, int w, int h) {
    double total = 0.0;
    for (int i = 0; i < h; i++) {
        for (int j = 0; j < w; j++) {
            double v = 0.0;
            int n = 0;
            if (i > 0) {
                v += m[i - 1][j].v;
                n++;
            }
            if (j > 0) {
                v += m[i][j - 1].v;
                n++;
            }
            if (i + 1 < h) {
                v += m[i + 1][j].v;
                n++;
            }
            if (j + 1 < w) {
                v += m[i][j + 1].v;
                n++;
            }
            v = m[i][j].v - v / n;
            d[i][j].v = v;
            if (m[i][j].fixed == 0) {
                total += v * v;
            }
        }
    }
    return total;
}
 
double iter(Node** m, int w, int h) {
    Node** d = (Node**)malloc(sizeof(Node*) * h);
    for (int i = 0; i < h; i++) {
        d[i] = (Node*)malloc(sizeof(Node) * w);
        for (int j = 0; j < w; j++) {
            d[i][j].v = 0.0;
            d[i][j].fixed = 0;
        }
    }
 
    double curr[3] = {0.0, 0.0, 0.0};
    double diff = 1e10;
 
    while (diff > 1e-24) {
        set_boundary(m);
        diff = calcuate_difference(m, d, w, h);
        for (int i = 0; i < h; i++) {
            for (int j = 0; j < w; j++) {
                m[i][j].v -= d[i][j].v;
            }
        }
    }
 
    for (int i = 0; i < h; i++) {
        for (int j = 0; j < w; j++) {
            int k = 0;
            if (i!= 0) k++;
            if (j!= 0) k++;
            if (i < h - 1) k++;
            if (j < w - 1) k++;
            curr[m[i][j].fixed + 1] += d[i][j].v * k;
        }
    }
 
    return (curr[2] - curr[0]) / 2.0;
}
 
#define S 10
int main(int argc, char** argv) {
    Node** mesh = (Node**)malloc(sizeof(Node*) * S);
    for (int i = 0; i < S; i++) {
        mesh[i] = (Node*)malloc(sizeof(Node) * S);
        for (int j = 0; j < S; j++) {
            mesh[i][j].v = 0.0;
            mesh[i][j].fixed = 0;
        }
    }
 
    double r = 2.0 / iter(mesh, S, S);
    printf("R = %f\n", r);
 
    return 0;
}

#include <stdio.h>
