#define MAX_PRIME 1000000

bool is_prime[MAX_PRIME];

void sieve_of_eratosthenes() {
    for (int i = 0; i < MAX_PRIME; i++) {
        is_prime[i] = true;
    }
    is_prime[0] = false;
    is_prime[1] = false;
    for (int i = 2; i < MAX_PRIME; i++) {
        if (is_prime[i]) {
            for (int j = i * i; j < MAX_PRIME; j += i) {
                is_prime[j] = false;
            }
        }
    }
}

int main() {
    sieve_of_eratosthenes();
    int n;
    scanf("%d", &n);
    for (int i = 2; i <= n; i++) {
        if (is_prime[i]) {
            printf("%d ", i);
        }
    }
    printf("\n");
    return 0;
}

