typedef struct {
    int type;
    void *value;
    void *traceback;
} Exception;
 
typedef struct {
    int type;
    void *value;
    void *traceback;
} U0;
 
typedef struct {
    int type;
    void *value;
    void *traceback;
} U1;
 
void foo();
void bar(int i);
void baz(int i);
 
void foo() {
    int i;
    for (i = 0; i < 2; i++) {
        Exception *exc = NULL;
        try {
            bar(i);
        } catch (U0 *e) {
            exc = (Exception *)e;
        }
        if (exc) {
            printf("Function foo caught exception U0\n");
        }
    }
}
 
void bar(int i) {
    baz(i);
}
 
void baz(int i) {
    if (i) {
        U1 *e = malloc(sizeof(U1));
        e->type = 1;
        e->value = NULL;
        e->traceback = NULL;
        throw e;
    } else {
        U0 *e = malloc(sizeof(U0));
        e->type = 0;
        e->value = NULL;
        e->traceback = NULL;
        throw e;
    }
}
 
int main() {
    foo();
    return 0;
}

