#include <stdio.h>
#include <stdlib.h>
#include <assert.h>
 
typedef int* row;
typedef row* matrix;
 
matrix matrixMul(matrix m1, matrix m2, int size) {
	matrix result = (matrix)malloc(size*sizeof(row));
	int i, j, k;
	for (i=0; i<size; i++) {
		result[i] = (row)malloc(size*sizeof(int));
		for (j=0; j<size; j++) {
			result[i][j] = 0;
			for (k=0; k<size; k++) {
				result[i][j] += m1[i][k] * m2[k][j];
			}
		}
	}
	return result;
}
 
matrix identity(int size) {
	matrix result = (matrix)malloc(size*sizeof(row));
	int i, j;
	for (i=0; i<size; i++) {
		result[i] = (row)malloc(size*sizeof(int));
		for (j=0; j<size; j++) {
			result[i][j] = (i==j)? 1 : 0;
		}
	}
	return result;
}
 
matrix matrixExp(matrix m, int size, int pow) {
	assert(pow>=0 && pow==(int)pow);
	matrix accumulator = identity(size);
	int i;
	for (i=0; i<pow; i++) {
		accumulator = matrixMul(accumulator, m, size);
	}
	return accumulator;
}
 
void printtable(matrix m, int size) {
	int i, j;
	for (i=0; i<size; i++) {
		for (j=0; j<size; j++) {
			printf("%-5d", m[i][j]);
		}
		printf("\n");
	}
}
 
int main() {
	int size = 2;
	matrix m = (matrix)malloc(size*sizeof(row));
	m[0] = (row)malloc(size*sizeof(int));
	m[1] = (row)malloc(size*sizeof(int));
	m[0][0] = 3;
	m[0][1] = 2;
	m[1][0] = 2;
	m[1][1] = 1;
	int i;
	for (i=0; i<5; i++) {
		printf("\n%i:\n", i);
		printtable(matrixExp(m, size, i), size);
	}
	return 0;
}

