void pascal(int n, void (*yield)(int *row, int n))
{
  if (n < 1) {
    fprintf(stderr, "must be positive.\n");
    exit(1);
  }
  int *ar = malloc(sizeof(int) * n);
  ar[0] = 1;
  yield(ar, 1);
  for (int i = 1; i < n; i++) {
    int *new_ar = malloc(sizeof(int) * (i + 1));
    new_ar[0] = 0;
    memcpy(new_ar + 1, ar, sizeof(int) * i);
    new_ar[i] = 0;
    for (int j = 0; j < i; j++) {
      new_ar[j] += new_ar[j + 1];
    }
    yield(new_ar, i + 1);
    free(ar);
    ar = new_ar;
  }
  free(ar);
}
 
void print_row(int *row, int n)
{
  for (int i = 0; i < n; i++) {
    printf("%d ", row[i]);
  }
  printf("\n");
}
 
int main(void)
{
  pascal(8, print_row);
  return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <math.h>
 
typedef struct Interval
{
    double LeftEndpoint;
    double RightEndpoint;
} Interval;
 
Interval Interval_new(double leftEndpoint, double size)
{
    Interval interval;
    interval.LeftEndpoint = leftEndpoint;
    interval.RightEndpoint = leftEndpoint + size;
    return interval;
}
 
double Interval_Size(Interval interval)
{
    return interval.RightEndpoint - interval.LeftEndpoint;
}
 
double Interval_Center(Interval interval)
{
    return (interval.LeftEndpoint + interval.RightEndpoint) / 2;
}
 
Interval* Interval_Subdivide(Interval interval, int subintervalCount)
{
    double subintervalSize = Interval_Size(interval) / subintervalCount;
    Interval* subintervals = malloc(subintervalCount * sizeof(Interval));
    for (int index = 0; index < subintervalCount; index++)
    {
        subintervals[index] = Interval_new(interval.LeftEndpoint + index * subintervalSize, subintervalSize);
    }
    return subintervals;
}
 
typedef enum ApproximationMethod
{
    RectangleLeft,
    RectangleMidpoint,
    RectangleRight,
    Trapezium,
    Simpson
} ApproximationMethod;
 
typedef struct DefiniteIntegral
{
    double (*Integrand)(double);
    Interval Domain;
} DefiniteIntegral;
 
DefiniteIntegral DefiniteIntegral_new(double (*integrand)(double), Interval domain)
{
    DefiniteIntegral definiteIntegral;
    definiteIntegral.Integrand = integrand;
    definiteIntegral.Domain = domain;
    return definiteIntegral;
}
 
double DefiniteIntegral_SampleIntegrand(DefiniteIntegral definiteIntegral, ApproximationMethod approximationMethod, Interval subdomain)
{
    switch (approximationMethod)
    {
        case RectangleLeft:
            return definiteIntegral.Integrand(subdomain.LeftEndpoint);
        case RectangleMidpoint:
            return definiteIntegral.Integrand(Interval_Center(subdomain));
        case RectangleRight:
            return definiteIntegral.Integrand(subdomain.RightEndpoint);
        case Trapezium:
            return (definiteIntegral.Integrand(subdomain.LeftEndpoint) + definiteIntegral.Integrand(subdomain.RightEndpoint)) / 2;
        case Simpson:
            return (definiteIntegral.Integrand(subdomain.LeftEndpoint) + 4 * definiteIntegral.Integrand(Interval_Center(subdomain)) + definiteIntegral.Integrand(subdomain.RightEndpoint)) / 6;
        default:
            return 0;
    }
}
 
double DefiniteIntegral_Approximate(DefiniteIntegral definiteIntegral, ApproximationMethod approximationMethod, int subdomainCount)
{
    Interval* subdomains = Interval_Subdivide(definiteIntegral.Domain, subdomainCount);
    double sum = 0;
    for (int index = 0; index < subdomainCount; index++)
    {
        sum += DefiniteIntegral_SampleIntegrand(definiteIntegral, approximationMethod, subdomains[index]);
    }
    free(subdomains);
    return Interval_Size(definiteIntegral.Domain) * sum / subdomainCount;
}
 
void TestApproximationMethods(DefiniteIntegral definiteIntegral, int subdomainCount)
{
    for (int approximationMethod = 0; approximationMethod < 5; approximationMethod++)
    {
        printf("%f\n", DefiniteIntegral_Approximate(definiteIntegral, approximationMethod, subdomainCount));
    }
}
 
