int main()
{
    TestApproximationMethods(DefiniteIntegral_new(Integrand1, Interval_new(0, 1)), 10000);
    TestApproximationMethods(DefiniteIntegral_new(Integrand2, Interval_new(1, 99)), 1000);
    TestApproximationMethods(DefiniteIntegral_new(Integrand3, Interval_new(0, 5000)), 500000);
    TestApproximationMethods(DefiniteIntegral_new(Integrand3, Interval_new(0, 6000)), 6000000);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <math.h>
#include <time.h>
 
#define TRUE 1
#define FALSE 0
 
int is_Prime(int n)
{
    int i, s, d;
 
    if (n == 0 || n == 1 || n == 4 || n == 6 || n == 8 || n == 9)
        return FALSE;
 
    if (n == 2 || n == 3 || n == 5 || n == 7)
        return TRUE;
 
    s = 0;
    d = n - 1;
    while (d % 2 == 0) {
        d /= 2;
        s++;
    }
    if ((1 << s) * d!= n - 1)
        return FALSE;
 
    int a;
    for (i = 0; i < 8; i++) {
        a = rand() % (n - 3) + 2;
        if (trial_composite(a, s, d, n))
            return FALSE;
    }
 
    return TRUE;
}
 
int trial_composite(int a, int s, int d, int n)
{
    if (pow(a, d) % n == 1)
        return FALSE;
 
    int i;
    for (i = 0; i < s; i++) {
        if (pow(a, (1 << i) * d) % n == n - 1)
            return FALSE;
    }
 
    return TRUE;
}
 
int *pierpont(int ulim, int vlim, int first)
{
    int u, v, p, p2, p3, pp_len, i;
    int *pp;
 
    p = 0;
    p2 = 1;
    p3 = 1;
    pp_len = 0;
    pp = (int *)malloc(sizeof(int) * 1000000);
 
    for (v = 0; v < vlim; v++) {
        for (u = 0; u < ulim; u++) {
            p = p2 * p3;
            if (first)
                p++;
            else
                p--;
            if (is_Prime(p)) {
                pp[pp_len] = p;
                pp_len++;
            }
            p2 *= 2;
        }
        p3 *= 3;
        p2 = 1;
    }
 
    pp = (int *)realloc(pp, sizeof(int) * pp_len);
 
    return pp;
}
 
int main()
{
    int i, *pp, *pp2;
 
    srand(time(NULL));
 
    printf("First 50 Pierpont primes of the first kind:\n");
    pp = pierpont(120, 80, TRUE);
    for (i = 0; i < 50; i++) {
        printf("%8d ", pp[i]);
        if ((i - 9) % 10 == 0)
            printf("\n");
    }
    printf("\n");
 
    printf("First 50 Pierpont primes of the second kind:\n");
    pp2 = pierpont(120, 80, FALSE);
    for (i = 0; i < 50; i++) {
        printf("%8d ", pp2[i]);
        if ((i - 9) % 10 == 0)
            printf("\n");
    }
    printf("\n");
 
    printf("250th Pierpont prime of the first kind: %d\n", pp[249]);
    printf("250th Pierpont prime of the second kind: %d\n", pp2[249]);
 
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <math.h>
 
typedef struct {
    double minimum;
    double lower_quartile;
    double median;
    double upper_quartile;
    double maximum;
} FiveNum;
 
double median(double *samples, int n) {
    // input is already sorted
    int m = n / 2;
    if (n % 2 == 0) {
        return (samples[m] + samples[m - 1]) / 2.0;
    } else {
        return samples[m];
    }
}
 
FiveNum fivenum(double *samples, int n) {
    double *xs = malloc(n * sizeof(double));
    for (int i = 0; i < n; i++) {
        xs[i] = samples[i];
    }
 
    for (int i = 0; i < n - 1; i++) {
        for (int j = 0; j < n - i - 1; j++) {
            if (xs[j] > xs[j + 1]) {
                double tmp = xs[j];
                xs[j] = xs[j + 1];
                xs[j + 1] = tmp;
            }
        }
    }
 
    int m = n / 2;
 
    FiveNum result;
    result.minimum = xs[0];
    result.lower_quartile = median(xs, m + (n % 2));
    result.median = median(xs, n);
    result.upper_quartile = median(xs + m, n - m);
    result.maximum = xs[n - 1];
 
    free(xs);
    return result;
}
 
int main() {
    double inputs[][21] = {
        {15., 6., 42., 41., 7., 36., 49., 40., 39., 47., 43.},
        {36., 40., 7., 39., 41., 15.},
        {
            0.14082834,
            0.09748790,
            1.73131507,
            0.87636009,
            -1.95059594,
            0.73438555,
            -0.03035726,
            1.46675970,
            -0.74621349,
            -0.72588772,
            0.63905160,
            0.61501527,
            -0.98983780,
            -1.00447874,
            -0.62759469,
            0.66206163,
            1.04312009,
            -0.10305385,
            0.75775634,
            0.32566578,
        },
    };
 
    for (int i = 0; i < 3; i++) {
        FiveNum result = fivenum(inputs[i], sizeof(inputs[i]) / sizeof(double));
        printf("Fivenum\n");
        printf("  Minumum: %f\n", result.minimum);
        printf("  Lower quartile: %f\n", result.lower_quartile);
        printf("  Median: %f\n", result.median);
        printf("  Upper quartile: %f\n", result.upper_quartile);
        printf("  Maximum: %f\n", result.maximum);
    }
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
 
int cylinder[6];
 
void rshift() {
    int t = cylinder[5];
    for (int i = 4; i >= 0; i--) {
        cylinder[i+1] = cylinder[i];
    }
    cylinder[0] = t;
}
 
void unload() {
    for (int i = 0; i < 6; i++) {
        cylinder[i] = 0;
    }
}
 
void load() {
    for (cylinder[0]) {
        rshift();
    }
    cylinder[0] = 1;
    rshift();
}
 
void spin() {
    int lim = 1 + rand() % 6;
    for (int i = 1; i < lim; i++) {
        rshift();
    }
}
 
int fire() {
    int shot = cylinder[0];
    rshift();
    return shot;
}
 
int method(char *s) {
    unload();
    for (int i = 0; i < strlen(s); i++) {
        switch (s[i]) {
        case 'L':
            load();
            break;
        case 'S':
            spin();
            break;
        case 'F':
            if (fire()) {
                return 1;
            }
        }
    }
    return 0;
}
 
char *mstring(char *s) {
    char *l = malloc(100);
    char *p = l;
    for (int i = 0; i < strlen(s); i++) {
        switch (s[i]) {
        case 'L':
            p += sprintf(p, "load, ");
            break;
        case 'S':
            p += sprintf(p, "spin, ");
            break;
        case 'F':
            p += sprintf(p, "fire, ");
            break;
        }
    }
    p[-2] = '\0';
    return l;
}
 
int main() {
    srand(time(NULL));
    int tests = 100000;
    for (int i = 0; i < 4; i++) {
        char *m = "LSLSFSF";
        if (i == 1) {
            m = "LSLSFF";
        } else if (i == 2) {
            m = "LLSFSF";
        } else if (i == 3) {
            m = "LLSFF";
        }
        int sum = 0;
        for (int t = 1; t <= tests; t++) {
            sum += method(m);
        }
        double pc = (double)sum * 100 / (double)tests;
        printf("%-40s produces %6.3f%% deaths.\n", mstring(m), pc);
    }
}

