#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
 
bool IsOppPlausibleWord(char *word) {
    if (strstr(word, "cie")!= NULL) {
        return true;
    }
    if (strstr(word, "ei")!= NULL) {
        return true;
    }
    return false;
}
 
bool IsPlausibleWord(char *word) {
    if (strstr(word, "cei")!= NULL) {
        return true;
    }
    if (strstr(word, "ie")!= NULL) {
        return true;
    }
    return false;
}
 
bool IsPlausibleRule(char *filename) {
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        return false;
    }
 
    char *line = NULL;
    size_t len = 0;
    ssize_t read;
 
    int trueCount = 0;
    int falseCount = 0;
 
    while ((read = getline(&line, &len, file))!= -1) {
        if (IsPlausibleWord(line)) {
            trueCount++;
        }
        else if (IsOppPlausibleWord(line)) {
            falseCount++;
        }
    }
 
    fclose(file);
    if (line) {
        free(line);
    }
 
    printf("Plausible count: %d\n", trueCount);
    printf("Implausible count: %d\n", falseCount);
    return trueCount > 2 * falseCount;
}
 
int main(int argc, char **argv) {
    if (argc < 2) {
        printf("Usage: %s <filename>\n", argv[0]);
        return 1;
    }
 
    if (IsPlausibleRule(argv[1])) {
        printf("Rule is plausible.\n");
    }
    else {
        printf("Rule is not plausible.\n");
    }
 
    return 0;
}

