#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <gmp.h>
 
int mod_exp(mpz_t b, mpz_t e, mpz_t n, mpz_t result)
{
    if (mpz_sgn(n) == 0) {
        return -1;
    }
    if (mpz_cmp(b, n) >= 0) {
        return -1;
    }
    if (mpz_cmp_ui(b, 1) == 0) {
        return -1;
    }
 
    mpz_t bb, ee;
    mpz_init_set(bb, b);
    mpz_init_set(ee, e);
    mpz_init_set_ui(result, 1);
    while (mpz_sgn(ee)!= 0) {
        if (mpz_odd_p(ee)) {
            mpz_mul(result, result, bb);
            mpz_mod(result, result, n);
        }
        mpz_fdiv_q_2exp(ee, ee, 1);
        mpz_mul(bb, bb, bb);
        mpz_mod(bb, bb, n);
    }
    mpz_clear(bb);
    mpz_clear(ee);
    return 0;
}
 
int main(void)
{
    char *msg = "Rosetta Code";
    size_t msg_len = strlen(msg);
 
    mpz_t n, e, d, msg_int, enc, dec;
    mpz_init_set_str(n, "9516311845790656153499716760847001433441357", 10);
    mpz_init_set_str(e, "65537", 10);
    mpz_init_set_str(d, "5617843187844953170308463622230283376298685", 10);
    mpz_init(msg_int);
    mpz_init(enc);
    mpz_init(dec);
 
    mpz_import(msg_int, msg_len, 1, 1, 0, 0, msg);
    if (mod_exp(msg_int, e, n, enc) == 0) {
        printf("msg as txt: %s\n", msg);
        printf("msg as num: ");
        mpz_out_str(stdout, 10, msg_int);
        printf("\n");
        printf("enc as num: ");
        mpz_out_str(stdout, 10, enc);
        printf("\n");
        if (mod_exp(enc, d, n, dec) == 0) {
            size_t dec_len = mpz_sizeinbase(dec, 256);
            char *dec_str = malloc(dec_len + 1);
            mpz_export(dec_str, NULL, 1, 1, 0, 0, dec);
            dec_str[dec_len] = '\0';
            printf("dec as num: ");
            mpz_out_str(stdout, 10, dec);
            printf("\n");
            printf("dec as txt: %s\n", dec_str);
            free(dec_str);
        }
    }
    mpz_clear(n);
    mpz_clear(e);
    mpz_clear(d);
    mpz_clear(msg_int);
    mpz_clear(enc);
    mpz_clear(dec);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <netdb.h>
#include <string.h>
#include <signal.h>

#define PORT 8080

int main(int argc, char *argv[])
{
    int sockfd, newsockfd, portno, clilen;
    char buffer[256];
    struct sockaddr_in serv_addr, cli_addr;
    int n;

    sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        perror("ERROR opening socket");
        exit(1);
    }
    bzero((char *) &serv_addr, sizeof(serv_addr));
    portno = PORT;
    serv_addr.sin_family = AF_INET;
    serv_addr.sin_addr.s_addr = INADDR_ANY;
    serv_addr.sin_port = htons(portno);
    if (bind(sockfd, (struct sockaddr *) &serv_addr, sizeof(serv_addr)) < 0) {
        perror("ERROR on binding");
        exit(1);
    }
    listen(sockfd,5);
    clilen = sizeof(cli_addr);
    newsockfd = accept(sockfd, (struct sockaddr *) &cli_addr, &clilen);
    if (newsockfd < 0) {
        perror("ERROR on accept");
        exit(1);
    }
    bzero(buffer,256);
    n = read(newsockfd,buffer,255);
    if (n < 0) {
        perror("ERROR reading from socket");
        exit(1);
    }
    n = write(newsockfd,"Goodbye, World!",16);
    if (n < 0) {
        perror("ERROR writing to socket");
        exit(1);
    }
    close(newsockfd);
    close(sockfd);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
 
int main(void)
{
    int mn, mx, guess, i;
    char txt[10];
    mn = 1;
    mx = 10;
    printf("Think of a number between %i and %i and wait for me to guess it.\n", mn, mx);
    printf("On every guess of mine you should state whether the guess was\n");
    printf("too high, too low, or equal to your number by typing h, l, or =\n");
    i = 0;
    while (1) {
        i += 1;
        guess = (mn+mx)/2;
        printf("Guess %2i is: %2i. The score for which is (h,l,=): ", i, guess);
        fgets(txt, 10, stdin);
        if (strlen(txt) < 2) {
            printf("  I don't understand your input of '%s' ?\n", txt);
            continue;
        }
        if (txt[0] == 'h') {
            mx = guess-1;
        }
        if (txt[0] == 'l') {
            mn = guess+1;
        }
        if (txt[0] == '=') {
            printf("  Ye-Haw!!\n");
            break;
        }
        if ((mn > mx) || (mn < 1) || (mx > 10)) {
            printf("Please check your scoring as I cannot find the value\n");
            break;
        }
    }
    printf("\nThanks for keeping score.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <time.h>
 
#define LONGMONTHS_LEN 7
const int LONGMONTHS[LONGMONTHS_LEN] = {1, 3, 5, 7, 8, 10, 12};
 
/**
 * Get all the tuples (year, month) in wich there is five Fridays, five Saturdays and five Sundays
 * between the years start and end (inclusive).
 */
int five_weekends(int start, int end, int **out) {
    int len = 0;
    int i, j;
 
    for (i = start; i <= end; i++) {
        for (j = 0; j < LONGMONTHS_LEN; j++) {
            struct tm tm = {0};
            tm.tm_year = i - 1900;
            tm.tm_mon = LONGMONTHS[j] - 1;
            tm.tm_mday = 1;
            mktime(&tm);
            if (tm.tm_wday == 5) {
                out[len][0] = i;
                out[len][1] = LONGMONTHS[j];
                len++;
            }
        }
    }
 
    return len;
}
 
int main() {
    int **out;
    int len = five_weekends(1900, 2100, out);
 
    printf("There are %d months of which the first and last five are:\n", len);
    for (int i = 0; i < 5; i++) {
        printf("\t%d / %d\n", out[i][0], out[i][1]);
    }
    printf("...\n");
    for (int i = len - 5; i < len; i++) {
        printf("\t%d / %d\n", out[i][0], out[i][1]);
    }
 
    return 0;
}
 
void test() {
    int **out;
    int len = five_weekends(1900, 2100, out);
    assert(len == 201);
}

#include <Python.h>

static PyObject *
pygen_evens(PyObject *self, PyObject *args)
{
    PyObject *values;
    PyObject *result;
    PyObject *iter;
    PyObject *item;
    PyObject *temp;

    if (!PyArg_ParseTuple(args, "O:evens", &values))
        return NULL;
    if ((iter = PyObject_GetIter(values)) == NULL)
        return NULL;
    result = PyList_New(0);
    if (result == NULL) {
        Py_DECREF(iter);
        return NULL;
    }
    while ((item = PyIter_Next(iter))!= NULL) {
        temp = PyNumber_And(item, Py_BuildValue("i", 1));
        Py_DECREF(item);
        if (temp == NULL) {
            Py_DECREF(iter);
            Py_DECREF(result);
            return NULL;
        }
        if (temp == Py_False) {
            if (PyList_Append(result, temp)!= 0) {
                Py_DECREF(temp);
                Py_DECREF(iter);
                Py_DECREF(result);
                return NULL;
            }
        }
        Py_DECREF(temp);
    }
    Py_DECREF(iter);
    return result;
}

static PyMethodDef pygen_methods[] = {
    {"evens", pygen_evens, METH_VARARGS,
     "Return a list of even numbers in the input list."},
    {NULL, NULL, 0, NULL}
};

static struct PyModuleDef pygenmodule = {
    PyModuleDef_HEAD_INIT,
    "pygen",
    NULL,
    -1,
    pygen_methods
};

PyMODINIT_FUNC
PyInit_pygen(void)
{
    return PyModule_Create(&pygenmodule);
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <X11/Xlib.h>
#include <X11/Xutil.h>
#include <X11/keysym.h>
#include <X11/extensions/XTest.h>

#define WPM 60
#define KEY_DELAY 1000000 / WPM

int main(int argc, char *argv[]) {
    Display *display = XOpenDisplay(NULL);
    if (display == NULL) {
        fprintf(stderr, "Cannot open display\n");
        exit(1);
    }

    int screen = DefaultScreen(display);
    Window window = RootWindow(display, screen);

    XSelectInput(display, window, KeyPressMask);
    XFlush(display);

    XTestGrabControl(display, True);

    char *string = "Hello, world!";
    int len = strlen(string);
    for (int i = 0; i < len; i++) {
        char c = string[i];
        KeySym keysym = XStringToKeysym(&c);
        KeyCode keycode = XKeysymToKeycode(display, keysym);
        XTestFakeKeyEvent(display, keycode, True, 0);
        XTestFakeKeyEvent(display, keycode, False, 0);
        usleep(KEY_DELAY);
    }

    XTestFakeKeyEvent(display, XKeysymToKeycode(display, XK_Return), True, 0);
    XTestFakeKeyEvent(display, XKeysymToKeycode(display, XK_Return), False, 0);

    XCloseDisplay(display);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include <ctype.h>
#include <math.h>
#include <assert.h>
 
#define MAX_PATH_LEN 100
 
typedef struct {
	char *path;
	int path_len;
} path_t;
 
typedef struct {
	path_t *paths;
	int path_count;
} path_set_t;
 
path_set_t *path_set_new(void)
{
	path_set_t *path_set = malloc(sizeof(path_set_t));
	path_set->paths = NULL;
	path_set->path_count = 0;
	return path_set;
}
 
void path_set_free(path_set_t *path_set)
{
	int i;
	for (i = 0; i < path_set->path_count; i++) {
		free(path_set->paths[i].path);
	}
	free(path_set->paths);
	free(path_set);
}
 
void path_set_add(path_set_t *path_set, char *path)
{
	path_set->paths = realloc(path_set->paths, (path_set->path_count + 1) * sizeof(path_t));
	path_set->paths[path_set->path_count].path = strdup(path);
	path_set->paths[path_set->path_count].path_len = strlen(path);
	path_set->path_count++;
}
 
int path_set_max_path_len(path_set_t *path_set)
{
	int i, max_path_len = 0;
	for (i = 0; i < path_set->path_count; i++) {
		if (path_set->paths[i].path_len > max_path_len) {
			max_path_len = path_set->paths[i].path_len;
		}
	}
	return max_path_len;
}
 
char *path_set_find_common_path(path_set_t *path_set, char *separator)
{
	int i, j, k, max_path_len, separator_len, common_path_len;
	char *common_path, *path;
	bool found;
	max_path_len = path_set_max_path_len(path_set);
	separator_len = strlen(separator);
	common_path = malloc(max_path_len + 1);
	common_path[0] = '\0';
	common_path_len = 0;
	for (i = 0; i < max_path_len; i++) {
		found = true;
		for (j = 0; j < path_set->path_count; j++) {
			path = path_set->paths[j].path;
			if (i + separator_len > path_set->paths[j].path_len) {
				found = false;
				break;
			}
			for (k = 0; k < separator_len; k++) {
				if (path[i + k]!= separator[k]) {
					found = false;
					break;
				}
			}
			if (!found) {
				break;
			}
		}
		if (found) {
			common_path_len = i + separator_len;
			memcpy(common_path, path, common_path_len);
			common_path[common_path_len] = '\0';
		} else {
			break;
		}
	}
	return common_path;
}
 
void test(void)
{
	path_set_t *path_set;
	char *common_path;
	path_set = path_set_new();
	path_set_add(path_set, "/home/user1/tmp/coverage/test");
	path_set_add(path_set, "/home/user1/tmp/covert/operator");
	path_set_add(path_set, "/home/user1/tmp/coven/members");
	printf("Path Set 1 (All Absolute Paths):\n");
	int i;
	for (i = 0; i < path_set->path_count; i++) {
		printf("%s\n", path_set->paths[i].path);
	}
	common_path = path_set_find_common_path(path_set, "/");
	printf("Path Set 1 Common Path: %s\n", common_path);
	free(common_path);
	path_set_free(path_set);
}
 
int main(void)
{
	test();
	return 0;
}

#include <stdio.h>
#include <math.h>

double stepDown(double d) {
    return nextafter(d, -INFINITY);
}

double stepUp(double d) {
    return nextafter(d, INFINITY);
}

double* safeAdd(double a, double b) {
    double result[2];
    result[0] = stepDown(a + b);
    result[1] = stepUp(a + b);
    return result;
}

int main() {
    double a = 1.2;
    double b = 0.03;
    double* result = safeAdd(a, b);
    printf("(%.2f + %.2f) is in the range %.16f..%.16f", a, b, result[0], result[1]);
    return 0;
}

