#include <stdio.h>
#include <stdlib.h>
#include <string.h>
 
typedef struct {
    int kind;
    char *message;
} Error;
 
Error *new_error(int kind, char *message) {
    Error *error = malloc(sizeof(Error));
    error->kind = kind;
    error->message = message;
    return error;
}
 
void free_error(Error *error) {
    free(error->message);
    free(error);
}
 
typedef struct {
    int kind;
    int number;
} Result;
 
Result *new_result(int kind, int number) {
    Result *result = malloc(sizeof(Result));
    result->kind = kind;
    result->number = number;
    return result;
}
 
void free_result(Result *result) {
    free(result);
}
 
Result *valid_function() {
    return new_result(0, 100);
}
 
Result *errored_function() {
    return new_result(1, 0);
}
 
void panicking_function() {
    printf("Unrecoverable state reached");
    exit(1);
}
 
int main() {
    Result *result = valid_function();
    if (result->kind == 0) {
        printf("Valid function: %d\n", result->number);
    } else {
        printf("Error: %s\n", result->message);
    }
    free_result(result);
 
    result = errored_function();
    if (result->kind == 0) {
        printf("Valid function: %d\n", result->number);
    } else {
        printf("Error: %s\n", result->message);
    }
    free_result(result);
 
    panicking_function();
}

