const char *check(const char *s) {
  const char *arr = s;
  int l = strlen(arr);
  int at = -1;
  for (int i = 1; i < l; i++) {
    if (arr[i]!= arr[i - 1]) {
      at = i;
      break;
    }
  }
  bool ok = at == -1;
  int p = ok? 0 : at + 1;
  char v = ok? 0 : arr[at];
  char vs[2] = {v, 0};
  int h = ok? 0 : (int)v;
  printf("\"%s\" => Length:%d\tSame:%d\tPos:%d\tChar:%s\tHex:%d\n", s, l, ok, p, vs, h);
  return s;
}

