#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
 
int **double_even_magic_square(int n) {
  if (n%4 > 0) {
    fprintf(stderr, "Need multiple of four\n");
    exit(1);
  }
  int block_size = n/4, max = n*n;
  bool pre_pat[] = {true, false, false, true,
                    false, true, true, false};
  bool pattern[n*n];
  for (int i=0; i<n*n; i++)
    pattern[i] = pre_pat[i%8];
  int *flat_ar = malloc(n*n * sizeof(int));
  for (int i=0; i<n*n; i++)
    flat_ar[i] = pattern[i]? i+1 : max-i;
  int **square = malloc(n * sizeof(int *));
  for (int i=0; i<n; i++)
    square[i] = flat_ar + i*n;
  return square;
}
 
void to_string(int **square, int n) {
  int max_digits = (n*n > 9)? 2 : 1;
  for (int i=0; i<n; i++) {
    for (int j=0; j<n; j++)
      printf("%*d ", max_digits, square[i][j]);
    printf("\n");
  }
}
 
int main() {
  int n = 8;
  int **square = double_even_magic_square(n);
  to_string(square, n);
  free(square[0]);
  free(square);
  return 0;
}

#include <stdio.h>
