#define IMPORT_COMMAND "/usr/bin/import"

int main(int argc, char *argv[]) {
  int x = atoi(argv[1]);
  int y = atoi(argv[2]);
  char command[100];
  sprintf(command, "%s -silent -window root -crop 1x1+%d+%d -depth 8 txt:-", IMPORT_COMMAND, x, y);
  FILE *fp = popen(command, "r");
  char buffer[100];
  fgets(buffer, 100, fp);
  regex_t regex;
  regcomp(&regex, "\\((\\d+),(\\d+),(\\d+)\\)", 0);
  regmatch_t matches[4];
  if (regexec(&regex, buffer, 4, matches, 0) == 0) {
    for (int i = 1; i < 4; i++) {
      char match[10];
      strncpy(match, buffer + matches[i].rm_so, matches[i].rm_eo - matches[i].rm_so);
      match[matches[i].rm_eo - matches[i].rm_so] = '\0';
      printf("%s\n", match);
    }
  }
  pclose(fp);
  return 0;
}

#include <ruby.h>
#include <math.h>
 
static VALUE
matrix_element_wise(VALUE self, VALUE op, VALUE other)
{
    VALUE result;
    long i, j, rows, cols;
    double *ptr, *ptr1, *ptr2;
    double (*func)(double, double);
 
    rows = NUM2LONG(rb_funcall(self, rb_intern("row_size"), 0));
    cols = NUM2LONG(rb_funcall(self, rb_intern("column_size"), 0));
    result = rb_funcall(rb_cMatrix, rb_intern("build"), 2, INT2NUM(rows), INT2NUM(cols));
 
    switch (op) {
    case '+':
        func = (double (*)(double, double))rb_funcall;
        break;
    case '-':
        func = (double (*)(double, double))rb_funcall;
        break;
    case '*':
        func = (double (*)(double, double))rb_funcall;
        break;
    case '/':
        func = (double (*)(double, double))rb_funcall;
        break;
    case 'f':
        func = (double (*)(double, double))rb_funcall;
        break;
    case '**':
        func = (double (*)(double, double))rb_funcall;
        break;
    case '%':
        func = (double (*)(double, double))rb_funcall;
        break;
    default:
        rb_raise(rb_eArgError, "unknown operator");
    }
 
    ptr = (double *)RARRAY_PTR(rb_funcall(result, rb_intern("to_a"), 0));
    ptr1 = (double *)RARRAY_PTR(rb_funcall(self, rb_intern("to_a"), 0));
    ptr2 = (double *)RARRAY_PTR(rb_funcall(other, rb_intern("to_a"), 0));
 
    for (i = 0; i < rows; i++) {
        for (j = 0; j < cols; j++) {
            *ptr++ = func(rb_cNumeric, op, 2, rb_float_new(*ptr1++), rb_float_new(*ptr2++));
        }
    }
 
    return result;
}
 
void
Init_matrix_element_wise()
{
    rb_define_method(rb_cMatrix, "element_wise", matrix_element_wise, 2);
}

