char *commatize(unsigned long long n) {
    char *s = malloc(25);
    sprintf(s, "%llu", n);
    int le = strlen(s);
    for (int i = le - 3; i >= 1; i -= 3) {
        memmove(s + i + 1, s + i, le - i);
        s[i] = ',';
        le++;
    }
    return s;
}
 
int main() {
    unsigned long long cube1, cube2, cube100k, diff;
    char **cubans = malloc(200 * sizeof(char *));
    int count = 0;
    cube1 = 1;
    for (int i = 1; ; i++) {
        int j = i + 1;
        cube2 = j * j * j;
        diff = cube2 - cube1;
        mpz_t z;
        mpz_init_set_ui(z, diff);
        if (mpz_probab_prime_p(z, 0)) { // 100% accurate for z < 2 ^ 64
            if (count < 200) {
                cubans[count] = commatize(diff);
            }
            count++;
            if (count == 100000) {
                cube100k = diff;
                break;
            }
        }
        cube1 = cube2;
    }
    printf("The first 200 cuban primes are:-\n");
    for (int i = 0; i < 20; i++) {
        int j = i * 10;
        for (int k = 0; k < 10; k++) {
            printf("%9s", cubans[j + k]);
        }
        printf("\n");
    }
    printf("\nThe 100,000th cuban prime is %s\n", commatize(cube100k));
    return 0;
}

