#include <stdbool.h>
 
// Returns the sum of the digits of n given the
// sum of the digits of n - 1
unsigned long digit_sum(unsigned long n, unsigned long sum) {
    sum += 1;
    while (n > 0 && n % 10 == 0) {
        sum -= 9;
        n /= 10;
    }
    return sum;
}
 
bool divisible(unsigned long n, unsigned long d) {
    if ((d & 1) == 0 && (n & 1) == 1) {
        return false;
    }
    return n % d == 0;
}
 
int main() {
    unsigned long previous = 1;
    unsigned long gap = 0;
    unsigned long sum = 0;
    unsigned long niven_index = 0;
    unsigned long gap_index = 1;
    unsigned long niven = 1;
    printf("Gap index  Gap    Niven index    Niven number\n");
    while (gap_index <= 32) {
        sum = digit_sum(niven, sum);
        if (divisible(niven, sum)) {
            if (niven > previous + gap) {
                gap = niven - previous;
                printf("%9lu %4lu %14lu %15lu\n", gap_index, gap, niven_index, previous);
                gap_index += 1;
            }
            previous = niven;
            niven_index += 1;
        }
        niven += 1;
    }
}

#include <stdio.h>
#include <math.h>
#include <complex.h>
 
typedef double complex complex;
 
struct pair {
  complex first;
  complex second;
};
 
struct pair solve_quadratic_equation(double a, double b, double c)
{
  b /= a;
  c /= a;
  double discriminant = b*b-4*c;
  if (discriminant < 0)
    return (struct pair){(-b/2) + I*sqrt(-discriminant)/2,
                         (-b/2) - I*sqrt(-discriminant)/2};
 
  double root = sqrt(discriminant);
  double solution1 = (b > 0)? (-b - root)/2
                            : (-b + root)/2;
 
  return (struct pair){solution1, c/solution1};
}
 
int main()
{
  struct pair result = solve_quadratic_equation(1, -1e20, 1);
  printf("%f + %fi, %f + %fi\n", creal(result.first), cimag(result.first),
                                 creal(result.second), cimag(result.second));
}

