bool isHumble(int i) {
    if (i <= 1) return true;
    if (i % 2 == 0) return isHumble(i / 2);
    if (i % 3 == 0) return isHumble(i / 3);
    if (i % 5 == 0) return isHumble(i / 5);
    if (i % 7 == 0) return isHumble(i / 7);
    return false;
}
 
char* toString(int n) {
    char* str = malloc(sizeof(char) * 10);
    sprintf(str, "%d", n);
    return str;
}
 
int main() {
    int limit = SHRT_MAX;
    int* humble = malloc(sizeof(int) * limit);
    int count = 0;
    int num = 1;
 
    while (count < limit) {
        if (isHumble(num)) {
            char* str = toString(num);
            int len = strlen(str);
            int* it = humble + len;
 
            if (*it!= 0) {
                *it = *it + 1;
            } else {
                *it = 1;
            }
 
            if (count < 50) printf("%d ", num);
            count++;
        }
        num++;
    }
    printf("\n\n");
 
    printf("Of the first %d humble numbers:\n", count);
    num = 1;
    while (num < limit - 1) {
        int* it = humble + num;
        if (*it!= 0) {
            printf("%5d have %2d digits\n", *it, num);
            num++;
        } else {
            break;
        }
    }
 
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
 
typedef struct Expression Expression;
 
struct Expression {
    char *op;
    char *ex;
    int prec;
};
 
char *postfixToInfix(const char *postfix);
 
int main(void) {
    char *e[] = {
        "3 4 2 * 1 5 - 2 3 ^ ^ / +",
        "1 2 + 3 4 + ^ 5 6 + ^"
    };
    for (int i = 0; i < 2; i++) {
        printf("Postfix : %s\n", e[i]);
        printf("Infix : %s\n", postfixToInfix(e[i]));
        printf("\n");
    }
    return 0;
}
 
char *postfixToInfix(const char *postfix) {
    char *ops = "-+/*^";
    char *token;
    char *ex;
    char *l, *r;
    int idx, opPrec;
    Expression *expr;
    int n = 0;
    int i = 0;
    int j = 0;
    int k = 0;
    int len = strlen(postfix);
    char *stack = malloc(len * sizeof(char));
    expr = malloc(len * sizeof(Expression));
 
    for (i = 0; i < len; i++) {
        if (postfix[i] =='') {
            n++;
        }
    }
    n++;
    token = malloc(n * sizeof(char));
 
    for (i = 0; i < len; i++) {
        if (postfix[i] =='') {
            token[j] = '\0';
            j = 0;
            idx = -1;
            for (k = 0; k < strlen(ops); k++) {
                if (token[0] == ops[k]) {
                    idx = k;
                    break;
                }
            }
            if (idx!= -1 && strlen(token) == 1) {
                r = expr[n - 1].ex;
                l = expr[n - 2].ex;
                opPrec = idx / 2;
                if (expr[n - 2].prec < opPrec || (expr[n - 2].prec == opPrec && token[0] == '^')) {
                    ex = malloc(strlen(l) + 3);
                    ex[0] = '(';
                    strcpy(ex + 1, l);
                    ex[strlen(l) + 1] = ')';
                    ex[strlen(l) + 2] = '\0';
                    l = ex;
                }
                if (expr[n - 1].prec < opPrec || (expr[n - 1].prec == opPrec && token[0]!= '^')) {
                    ex = malloc(strlen(r) + 3);
                    ex[0] = '(';
                    strcpy(ex + 1, r);
                    ex[strlen(r) + 1] = ')';
                    ex[strlen(r) + 2] = '\0';
                    r = ex;
                }
                ex = malloc(strlen(l) + strlen(r) + strlen(token) + 3);
                strcpy(ex, l);
                ex[strlen(l)] ='';
                strcpy(ex + strlen(l) + 1, token);
                ex[strlen(l) + strlen(token) + 1] ='';
                strcpy(ex + strlen(l) + strlen(token) + 2, r);
                ex[strlen(l) + strlen(token) + strlen(r) + 2] = '\0';
                expr[n - 2].ex = ex;
                n--;
            } else {
                expr[n].ex = malloc(strlen(token) + 1);
                strcpy(expr[n].ex, token);
                expr[n].prec = 3;
                n++;
            }
        } else {
            token[j] = postfix[i];
            j++;
        }
    }
    return expr[0].ex;
}

