#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
 
#define N 2200
 
int main(void) {
  bool *l_add = calloc(N*N+1, sizeof(bool));
  bool *l = calloc(N+1, sizeof(bool));
  int x, y, x2, s, s1, s2;
  for (x = 1; x <= N; x++) {
    x2 = x*x;
    for (y = x; y <= N; y++) l_add[x2 + y*y] = true;
  }
  s = 3;
  for (x = 1; x <= N; x++) {
    s1 = s;
    s += 2;
    s2 = s;
    for (y = x+1; y <= N; y++) {
      if (l_add[s1]) l[y] = true;
      s1 += s2;
      s2 += 2;
    }
  }
  for (x = 1; x <= N; x++) if (!l[x]) printf("%d ", x);
  printf("\n");
  free(l_add);
  free(l);
  return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ldap.h>
 
int main(int argc, char **argv) {
    LDAP *ld;
    LDAPMessage *result, *e;
    BerElement *ber;
    char *dn;
    char *attrs[] = { "givenName", "sn", "mail", "uid", NULL };
    int i, rc;
    char *host = "ldap.example.com";
    int port = 389;
    char *binddn = "uid=readonlyuser,ou=People,dc=example,dc=com";
    char *bindpw = "readonlypassword";
    char *base = "dc=example,dc=com";
    char *filter = "(uid=%s)";
    char *who = "jtblin";
    char *attr;
    char **vals;
    char *p;
    int version = LDAP_VERSION3;
    int found = 0;
    struct timeval time = { 10, 0 };
    
    if (ldap_initialize(&ld, "ldap://ldap.example.com")!= LDAP_SUCCESS) {
        perror("ldap_initialize");
        exit(1);
    }
    
    if (ldap_set_option(ld, LDAP_OPT_PROTOCOL_VERSION, &version)!= LDAP_SUCCESS) {
        perror("ldap_set_option");
        exit(1);
    }
    
    if (ldap_set_option(ld, LDAP_OPT_TIMELIMIT, &time)!= LDAP_SUCCESS) {
        perror("ldap_set_option");
        exit(1);
    }
    
    if (ldap_simple_bind_s(ld, binddn, bindpw)!= LDAP_SUCCESS) {
        perror("ldap_simple_bind_s");
        exit(1);
    }
    
    if (ldap_search_ext_s(ld, base, LDAP_SCOPE_SUBTREE, filter, attrs, 0, NULL, NULL, &time, 0, &result)!= LDAP_SUCCESS) {
        perror("ldap_search_ext_s");
        exit(1);
    }
    
    for (e = ldap_first_entry(ld, result); e!= NULL; e = ldap_next_entry(ld, e)) {
        if ((dn = ldap_get_dn(ld, e))!= NULL) {
            if (strstr(dn, who)!= NULL) {
                found = 1;
                break;
            }
            ldap_memfree(dn);
        }
    }
    
    if (!found) {
        fprintf(stderr, "User %s not found\n", who);
        exit(1);
    }
    
    for (attr = ldap_first_attribute(ld, e, &ber); attr!= NULL; attr = ldap_next_attribute(ld, e, ber)) {
        if ((vals = ldap_get_values(ld, e, attr))!= NULL) {
            for (i = 0; vals[i]!= NULL; i++) {
                printf("%s: %s\n", attr, vals[i]);
                ldap_memfree(vals[i]);
            }
            ldap_value_free(vals);
        }
        ldap_memfree(attr);
    }
    
    if (ber!= NULL) {
        ber_free(ber, 0);
    }
    
    ldap_msgfree(result);
    ldap_unbind_ext_s(ld, NULL, NULL);
    
    return 0;
}

