#include <stdio.h>
#include <stdlib.h>
 
typedef int (*CurriableFunctor)(int, int);
 
typedef int (*CurriedFunctor)(int);
 
typedef struct {
    CurriableFunctor functor;
} Currier;
 
int curry(Currier *currier, int arg1) {
    return currier->functor(arg1, 0);
}
 
int add(int arg1, int arg2) {
    return arg1 + arg2;
}
 
int main(int argc, char *argv[]) {
    Currier currier;
    currier.functor = add;
    CurriedFunctor add5 = curry(&currier, 5);
    printf("%d\n", add5(2));
    return 0;
}

