#include <stdio.h>
#include <stdlib.h>
#include <math.h>
 
typedef int** IntTable;
 
IntTable getSpiralArray( int dimension )
{
	IntTable spiralArray = (IntTable)malloc(dimension * sizeof(int*));
	for (int i = 0; i < dimension; i++)
		spiralArray[i] = (int*)malloc(dimension * sizeof(int));
 
	int numConcentricSquares = (int)ceil(
		(double)dimension / 2.0 );
 
	int j;
	int sideLen = dimension;
	int currNum = 0;
 
	for ( int i = 0; i < numConcentricSquares; i++ )
	{
		// do top side
		for ( j = 0; j < sideLen; j++ )
			spiralArray[i][i + j] = currNum++;
 
		// do right side
		for ( j = 1; j < sideLen; j++ )
			spiralArray[i + j][dimension - 1 - i] = currNum++;
 
		// do bottom side
		for ( j = sideLen - 2; j > -1; j-- )
			spiralArray[dimension - 1 - i][i + j] = currNum++;
 
		// do left side
		for ( j = sideLen - 2; j > 0; j-- )
			spiralArray[i + j][i] = currNum++;
 
		sideLen -= 2;
	}
 
	return spiralArray;
}
 
void printSpiralArray( IntTable spiralArray, int dimension )
{
	int fieldWidth = (int)floor( log10(
		(double)(dimension * dimension - 1) ) ) + 2;
 
	int col;
	for ( int row = 0; row < dimension; row++ )
	{
		for ( col = 0; col < dimension; col++ )
			printf("%*d", fieldWidth, spiralArray[row][col]);
		printf("\n");
	}
}
 
int main()
{
	int dimension = 5;
	IntTable spiralArray = getSpiralArray(dimension);
	printSpiralArray(spiralArray, dimension);
}

#include <stdio.h>
 
double newtoncooling(double time, double temp)
{
	return -0.07 * (temp - 20);
}
 
void euler(double (*f)(double, double), double y0, double a, double b, double h)
{
	double t = a;
	double y = y0;
	while (t <= b) {
		printf("%6.3f %6.3f\n", t, y);
		t += h;
		y += h * f(t, y);
	}
}
 
int main()
{
	euler(newtoncooling, 100, 0, 100, 10);
	return 0;
}

