#include <signal.h>
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
 
void handle_sigint(int sig) {
    time_t start_time = time(NULL);
    time_t current_time = time(NULL);
    double elapsed_time = difftime(current_time, start_time);
    printf("\nThe program has run for %f seconds\n", elapsed_time);
    exit(0);
}
 
int main(int argc, char **argv) {
    time_t start_time = time(NULL);
    signal(SIGINT, handle_sigint);
 
    int i = 0;
    while(1) {
        printf("%d\n", i++);
        sleep(1);
    }
}

#include <stdio.h>
 
int main()
{
  int s[] = {1,2,2,3,4,4,5};
  int s_size = sizeof(s) / sizeof(s[0]);
 
  if(s_size > 0)
  {
    int previousValue = s[0];
 
    for(size_t i = 1; i < s_size; ++i)
    {
      // in C++, variables in block scope are reset at each iteration
      int currentValue = s[i];
 
      if(i > 0 && previousValue == currentValue)
      {
        printf("%d\n", i);
      }
 
      previousValue = currentValue;
    }
  }
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <assert.h>
 
typedef struct {
  int foo;
  int *bar;
} src_t;
 
src_t *deepcopy(src_t *src) {
  src_t *dst = malloc(sizeof(src_t));
  dst->foo = src->foo;
  dst->bar = malloc(sizeof(int) * 2);
  memcpy(dst->bar, src->bar, sizeof(int) * 2);
  return dst;
}
 
int main(int argc, char **argv) {
  src_t src = {0, {0, 1}};
  src_t *dst = deepcopy(&src);
  printf("%d\n", src.foo);
  printf("%d\n", dst->foo);
  return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include <assert.h>
#include <libxml/parser.h>
#include <libxml/tree.h>
#include <libxml/xmlwriter.h>
 
typedef struct {
    char *key;
    char *value;
} pair;
 
typedef struct {
    pair *pairs;
    size_t len;
    size_t cap;
} pairs;
 
void pairs_init(pairs *p) {
    p->len = 0;
    p->cap = 10;
    p->pairs = malloc(sizeof(pair) * p->cap);
}
 
void pairs_deinit(pairs *p) {
    for (size_t i = 0; i < p->len; i++) {
        free(p->pairs[i].key);
        free(p->pairs[i].value);
    }
    free(p->pairs);
}
 
void pairs_append(pairs *p, char *key, char *value) {
    if (p->len == p->cap) {
        p->cap *= 2;
        p->pairs = realloc(p->pairs, sizeof(pair) * p->cap);
    }
    p->pairs[p->len].key = key;
    p->pairs[p->len].value = value;
    p->len++;
}
 
void pairs_sort(pairs *p) {
    for (size_t i = 0; i < p->len; i++) {
        for (size_t j = i + 1; j < p->len; j++) {
            if (strcmp(p->pairs[i].key, p->pairs[j].key) > 0) {
                pair tmp = p->pairs[i];
                p->pairs[i] = p->pairs[j];
                p->pairs[j] = tmp;
            }
        }
    }
}
 
char *characters_to_xml(pairs *characters) {
    xmlTextWriterPtr writer = xmlNewTextWriterMemory(NULL, 0);
    xmlTextWriterStartDocument(writer, NULL, "UTF-8", NULL);
    xmlTextWriterStartElement(writer, BAD_CAST "CharacterRemarks");
 
    for (size_t i = 0; i < characters->len; i++) {
        xmlTextWriterStartElement(writer, BAD_CAST "Character");
        xmlTextWriterWriteAttribute(writer, BAD_CAST "name", BAD_CAST characters->pairs[i].key);
        xmlTextWriterWriteRaw(writer, BAD_CAST characters->pairs[i].value);
        xmlTextWriterEndElement(writer);
    }
 
    xmlTextWriterEndElement(writer);
    xmlTextWriterEndDocument(writer);
 
    xmlChar *output;
    int size;
    xmlTextWriterFlush(writer, &output, &size);
    xmlFreeTextWriter(writer);
 
    char *result = malloc(size + 1);
    memcpy(result, output, size);
    result[size] = '\0';
    xmlFree(output);
 
    return result;
}
 
int main() {
    pairs characters;
    pairs_init(&characters);
    pairs_append(&characters, "April", "Bubbly: I'm > Tam and <= Emily");
    pairs_append(&characters, "", "Burns: \"When chapman billies leave the street...\"");
    pairs_append(&characters, "Emily", "Short & shrift");
    pairs_sort(&characters);
 
    char *output = characters_to_xml(&characters);
    printf("%s\n", output);
 
    assert(strstr(output, "<Character name=\"\">Burns: \"When chapman billies leave the street...\"</Character>")!= NULL);
    assert(strstr(output, "<Character name=\"April\">Bubbly: I'm > Tam and &lt;= Emily</Character>")!= NULL);
    assert(strstr(output, "<Character name=\"Emily\">Short &amp; shrift</Character>")!= NULL);
 
    free(output);
    pairs_deinit(&characters);
}

#include <stdio.h>
#include <stdlib.h>

int factorial(int n) {
    int i;
    int result = 1;
    for (i = 1; i <= n; i++) {
        result = result * i;
    }
    return result;
}

int main(int argc, char *argv[]) {
    int n = atoi(argv[1]);
    int result = factorial(n);
    printf("%d\n", result);
    return 0;
}

#include <SDL2/SDL.h>
#include <stdio.h>
 
int main(int argc, char *argv[]) {
    SDL_Window *window;
    SDL_Renderer *renderer;
    SDL_Texture *texture;
    SDL_Event event;
    int quit = 0;
    int i;
    Uint32 pixels[8];
 
    if (SDL_Init(SDL_INIT_VIDEO) < 0) {
        printf("SDL could not initialize! SDL_Error: %s\n", SDL_GetError());
        return 1;
    }
 
    window = SDL_CreateWindow("Colour Bars", SDL_WINDOWPOS_UNDEFINED, SDL_WINDOWPOS_UNDEFINED, 8, 1, SDL_WINDOW_FULLSCREEN_DESKTOP);
    if (window == NULL) {
        printf("Window could not be created! SDL_Error: %s\n", SDL_GetError());
        return 1;
    }
 
    renderer = SDL_CreateRenderer(window, -1, SDL_RENDERER_ACCELERATED);
    if (renderer == NULL) {
        printf("Renderer could not be created! SDL_Error: %s\n", SDL_GetError());
        return 1;
    }
 
    texture = SDL_CreateTexture(renderer, SDL_PIXELFORMAT_ARGB8888, SDL_TEXTUREACCESS_STREAMING, 8, 1);
    if (texture == NULL) {
        printf("Texture could not be created! SDL_Error: %s\n", SDL_GetError());
        return 1;
    }
 
    pixels[0] = 0x000000FF; // black
    pixels[1] = 0xFF0000FF; // red
    pixels[2] = 0x00FF00FF; // green
    pixels[3] = 0x0000FFFF; // blue
    pixels[4] = 0xFF00FFFF; // magenta
    pixels[5] = 0x00FFFFFF; // cyan
    pixels[6] = 0xFFFF00FF; // yellow
    pixels[7] = 0xFFFFFFFF; // white
 
    SDL_UpdateTexture(texture, NULL, pixels, 8 * sizeof(Uint32));
 
    while (!quit) {
        while (SDL_PollEvent(&event)) {
            if (event.type == SDL_QUIT) {
                quit = 1;
            }
        }
 
        SDL_RenderClear(renderer);
        SDL_RenderCopy(renderer, texture, NULL, NULL);
        SDL_RenderPresent(renderer);
    }
 
    SDL_DestroyTexture(texture);
    SDL_DestroyRenderer(renderer);
    SDL_DestroyWindow(window);
    SDL_Quit();
 
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <limits.h>
 
void print(int** dist, int** next, int num_vertices) {
  printf("(pair, dist, path)\n");
  for (int i = 0; i < num_vertices; ++i) {
    for (int j = 0; j < num_vertices; ++j) {
      if (i!= j) {
        int u = i + 1;
        int v = j + 1;
        printf("(%d -> %d, %d, ", u, v, dist[i][j]);
        char path[100];
        sprintf(path, "%d", u);
        do {
          u = next[u - 1][v - 1];
          sprintf(path + strlen(path), " -> %d", u);
        } while (u!= v);
        printf("%s)\n", path);
      }
    }
  }
}
 
void solve(int** w_s, int num_vertices) {
  int** dist = (int**)malloc(num_vertices * sizeof(int*));
  for (int i = 0; i < num_vertices; ++i) {
    dist[i] = (int*)malloc(num_vertices * sizeof(int));
    for (int j = 0; j < num_vertices; ++j) {
      dist[i][j] = INT_MAX;
    }
  }
  for (int i = 0; i < num_vertices; ++i) {
    dist[w_s[i][0] - 1][w_s[i][1] - 1] = w_s[i][2];
  }
  int** next = (int**)malloc(num_vertices * sizeof(int*));
  for (int i = 0; i < num_vertices; ++i) {
    next[i] = (int*)malloc(num_vertices * sizeof(int));
    for (int j = 0; j < num_vertices; ++j) {
      next[i][j] = 0;
    }
    for (int j = 0; j < num_vertices; ++j) {
      if (i!= j) {
        next[i][j] = j + 1;
      }
    }
  }
  for (int k = 0; k < num_vertices; ++k) {
    for (int i = 0; i < num_vertices; ++i) {
      for (int j = 0; j < num_vertices; ++j) {
        if (dist[i][j] > dist[i][k] + dist[k][j]) {
          dist[i][j] = dist[i][k] + dist[k][j];
          next[i][j] = next[i][k];
        }
      }
    }
  }
  print(dist, next, num_vertices);
}
 
int main() {
  int** w = (int**)malloc(5 * sizeof(int*));
  for (int i = 0; i < 5; ++i) {
    w[i] = (int*)malloc(3 * sizeof(int));
  }
  w[0][0] = 1;
  w[0][1] = 3;
  w[0][2] = -2;
  w[1][0] = 2;
  w[1][1] = 1;
  w[1][2] = 4;
  w[2][0] = 2;
  w[2][1] = 3;
  w[2][2] = 3;
  w[3][0] = 3;
  w[3][1] = 4;
  w[3][2] = 2;
  w[4][0] = 4;
  w[4][1] = 2;
  w[4][2] = -1;
  int num_vertices = 4;
  solve(w, num_vertices);
  return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
 
void quick_sort(void *v, size_t len, size_t size, int (*f)(const void *, const void *));
void partition(void *v, size_t len, size_t size, int (*f)(const void *, const void *));
 
int main(void) {
    printf("Sort numbers in descending order\n");
    int numbers[] = {4, 65, 2, -31, 0, 99, 2, 83, 782, 1};
    size_t len = sizeof(numbers) / sizeof(int);
    printf("Before: ");
    for (size_t i = 0; i < len; i++) {
        printf("%d ", numbers[i]);
    }
    printf("\n");
 
    quick_sort(numbers, len, sizeof(int), &int_cmp);
    printf("After:  ");
    for (size_t i = 0; i < len; i++) {
        printf("%d ", numbers[i]);
    }
    printf("\n\n");
 
    printf("Sort strings alphabetically\n");
    char *strings[] = {"beach", "hotel", "airplane", "car", "house", "art"};
    len = sizeof(strings) / sizeof(char *);
    printf("Before: ");
    for (size_t i = 0; i < len; i++) {
        printf("%s ", strings[i]);
    }
    printf("\n");
 
    quick_sort(strings, len, sizeof(char *), &str_cmp);
    printf("After:  ");
    for (size_t i = 0; i < len; i++) {
        printf("%s ", strings[i]);
    }
    printf("\n\n");
 
    printf("Sort strings by length\n");
    printf("Before: ");
    for (size_t i = 0; i < len; i++) {
        printf("%s ", strings[i]);
    }
    printf("\n");
 
    quick_sort(strings, len, sizeof(char *), &str_len_cmp);
    printf("After:  ");
    for (size_t i = 0; i < len; i++) {
        printf("%s ", strings[i]);
    }
    printf("\n");
 
    return 0;
}
 
void quick_sort(void *v, size_t len, size_t size, int (*f)(const void *, const void *)) {
    if (len >= 2) {
        size_t pivot_index = partition(v, len, size, f);
        quick_sort(v, pivot_index, size, f);
        quick_sort((char *)v + (pivot_index + 1) * size, len - pivot_index - 1, size, f);
    }
}
 
void partition(void *v, size_t len, size_t size, int (*f)(const void *, const void *)) {
    size_t pivot_index = len / 2;
    size_t last_index = len - 1;
 
    void *pivot = (char *)v + pivot_index * size;
    void *last = (char *)v + last_index * size;
    void *temp = malloc(size);
    memcpy(temp, last, size);
    memcpy(last, pivot, size);
    memcpy(pivot, temp, size);
    free(temp);
 
    size_t store_index = 0;
    for (size_t i = 0; i < last_index; i++) {
        if (f((char *)v + i * size, last) < 0) {
            void *store = (char *)v + store_index * size;
            void *current = (char *)v + i * size;
            memcpy(temp, current, size);
            memcpy(current, store, size);
            memcpy(store, temp, size);
            store_index++;
        }
    }
 
    void *store = (char *)v + store_index * size;
    memcpy(temp, last, size);
    memcpy(last, store, size);
    memcpy(store, temp, size);
    free(temp);
}
 
int int_cmp(const void *x, const void *y) {
    int a = *(int *)x;
    int b = *(int *)y;
    if (a < b) {
        return 1;
    } else if (a > b) {
        return -1;
    } else {
        return 0;
    }
}
 
int str_cmp(const void *x, const void *y) {
    char *a = *(char **)x;
    char *b = *(char **)y;
    return strcmp(a, b);
}
 
int str_len_cmp(const void *x, const void *y) {
    char *a = *(char **)x;
    char *b = *(char **)y;
    size_t len_a = strlen(a);
    size_t len_b = strlen(b);
    if (len_a < len_b) {
        return -1;
    } else if (len_a > len_b) {
        return 1;
    } else {
        return 0;
    }
}

