"are$delineated$by$a$single$'dollar'$character,$write$a$program",
"that$aligns$each$column$of$fields$by$ensuring$that$words$in$each$",
"column$are$separated$by$at$least$one$space.",
"Further,$allow$for$each$word$in$a$column$to$be$either$left$",
"justified,$right$justified,$or$center$justified$within$its$column."},
*x,*y,cols,max,cols=0,diff,left,right;
 
char *repeat(char *s,int n) {
 char *r;
 int i;
 r=malloc(n+1);
 for(i=0;i<n;i++) r[i]=s[0];
 r[i]=0;
 return r;
}
 
int main() {
 int x,y;
 for(x=0;x<sizeof(input)/sizeof(char *);x++) {
  input[x]=strtok(input[x],"$");
  if(input[x]&&strlen(input[x])>cols) cols=strlen(input[x]);
 }
 for(x=0;x<cols;x++) {
  max=0;
  for(y=0;y<sizeof(input)/sizeof(char *);y++) if(input[y][x]&&max<strlen(input[y][x])) max=strlen(input[y][x]);
  for(y=0;y<sizeof(input)/sizeof(char *);y++) 
   if(input[y][x]) {
