#include <stdio.h>
#include <stdlib.h>
#include <string.h>
 
typedef struct Maybe {
    void *value;
} Maybe;
 
Maybe *maybe_new(void *value) {
    Maybe *maybe = malloc(sizeof(Maybe));
    maybe->value = value;
    return maybe;
}
 
void *maybe_bind(Maybe *maybe, void *(*func)(void *)) {
    if (maybe->value == NULL) {
        return NULL;
    }
    return func(maybe->value);
}
 
void *plus_one(void *value) {
    if (value == NULL) {
        return NULL;
    }
    int *int_value = (int *)value;
    int new_value = *int_value + 1;
    return maybe_new(&new_value);
}
 
void *currency(void *value) {
    if (value == NULL) {
        return NULL;
    }
    int *int_value = (int *)value;
    char *str_value = malloc(10);
    sprintf(str_value, "$%d.00", *int_value);
    return maybe_new(str_value);
}
 
int main() {
    int test_cases[] = {1, 99, 0, 4};
    int num_test_cases = sizeof(test_cases) / sizeof(int);
 
    for (int i = 0; i < num_test_cases; i++) {
        Maybe *m_int = maybe_new(&test_cases[i]);
        Maybe *result = maybe_bind(m_int, plus_one);
        result = maybe_bind(result, currency);
        printf("%d -> %s\n", test_cases[i], (char *)result->value);
        free(result->value);
        free(result);
        free(m_int);
    }
 
    return 0;
}

