#include <stdio.h>
#include <stdlib.h>
#include <string.h>
 
void print_menu(const char** terms, int size)
{
    for (int i = 0; i < size; i++) {
        printf("%d) %s\n", i + 1, terms[i]);
    }
}
 
int parse_entry(const char* entry, int max_number)
{
    int number = atoi(entry);
    if (number < 1 || number > max_number) {
        throw "Invalid entry";
    }
 
    return number;
}
 
char* data_entry(const char* prompt, const char** terms, int size)
{
    if (size == 0) {
        return "";
    }
 
    int choice;
    while (true) {
        print_menu(terms, size);
        printf("%s", prompt);
 
        char entry[100];
        scanf("%s", entry);
 
        try {
            choice = parse_entry(entry, size);
            return terms[choice - 1];
        } catch (const char* e) {
            // printf("Not a valid menu entry!\n");
        }
    }
}
 
int main()
{
    const char* terms[] = {"fee fie", "huff and puff", "mirror mirror", "tick tock"};
    printf("You chose: %s\n", data_entry("> ", terms, 4));
}

