#include <ruby.h>
#include <stdio.h>

static VALUE
tempfile_new(VALUE klass, VALUE basename)
{
    VALUE obj;
    char *path;
    FILE *fp;

    path = make_tempname(basename);
    fp = fopen(path, "w+");
    if (!fp) {
        rb_sys_fail(path);
    }
    obj = Data_Wrap_Struct(klass, 0, fclose, fp);
    rb_obj_call_init(obj, 0, 0);
    return obj;
}

static VALUE
tempfile_path(VALUE self)
{
    FILE *fp;
    char *path;

    Data_Get_Struct(self, FILE, fp);
    path = make_tempname(basename);
    return rb_str_new2(path);
}

static VALUE
tempfile_unlink(VALUE self)
{
    FILE *fp;
    char *path;

    Data_Get_Struct(self, FILE, fp);
    path = make_tempname(basename);
    fclose(fp);
    unlink(path);
    return self;
}

void
Init_tempfile()
{
    VALUE cTempfile;

    cTempfile = rb_define_class("Tempfile", rb_cObject);
    rb_define_singleton_method(cTempfile, "new", tempfile_new, 1);
    rb_define_method(cTempfile, "path", tempfile_path, 0);
    rb_define_method(cTempfile, "unlink", tempfile_unlink, 0);
}

