// version 1.2.31
 
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
 
#define MAX_LINE 100
 
int main(int argc, char *argv[]) {
    char line[MAX_LINE];
    char *date;
    char *fields[49];
    char *rx = "\\s+";
    char *fmt = "Line:  %s  Reject: %2d  Accept: %2d  Line_tot: %7.3f  Line_avg: %7.3f";
    double grandTotal = 0.0;
    int readings = 0;
    int maxRun = -1;
    int run = 0;
    char *finishLine = "";
    FILE *file = fopen("readings.txt", "r");
    if (file == NULL) {
        printf("File readings.txt not found\n");
        exit(1);
    }
    while (fgets(line, MAX_LINE, file)!= NULL) {
        date = strtok(line, rx);
        if (date!= NULL) {
            int i = 0;
            while ((fields[i] = strtok(NULL, rx))!= NULL) {
                i++;
            }
            if (i == 49) {
                int accept = 0;
                double total = 0.0;
                for (i = 1; i < 49; i += 2) {
                    if (atoi(fields[i + 1]) >= 1) {
                        accept++;
                        total += atof(fields[i]);
                        if (run > maxRun) {
                            maxRun = run;
                            finishLine = date;
                        }
                        run = 0;
                    }
                    else run++;
                }
                grandTotal += total;
                readings += accept;
                printf(fmt, date, 24 - accept, accept, total, total / accept);
            }
            else printf("Line:  %s does not have 49 fields and has been ignored\n", date);
        }
    }
    if (run > maxRun) {
        maxRun = run;
        finishLine = date;
    }
    double average = grandTotal / readings;
    printf("\nFile     = readings.txt\n");
    printf("Total    = %7.3f\n", grandTotal);
    printf("Readings = %d\n", readings);
    printf("Average  = %-7.3f\n", average);
    printf("\nMaximum run of %d consecutive false readings\n", maxRun);
    printf("ends at line starting with date: %s\n", finishLine);
    fclose(file);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <limits.h>
 
int matrixChainOrder(int* dims, int n);
char* getOptimalParenthesizations(int** s, int i, int j);
 
int main() {
    int dims1[] = {5, 6, 3, 1};
    int dims2[] = {1, 5, 25, 30, 100, 70, 2, 1, 100, 250, 1, 1000, 2};
    int dims3[] = {1000, 1, 500, 12, 1, 700, 2500, 3, 2, 5, 14, 10};
 
    runMatrixChainMultiplication(dims1, 4);
    runMatrixChainMultiplication(dims2, 13);
    runMatrixChainMultiplication(dims3, 12);
 
    return 0;
}
 
void runMatrixChainMultiplication(int* dims, int n) {
    printf("Array Dimension  = ");
    for (int i = 0; i < n; i++) {
        printf("%d ", dims[i]);
    }
    printf("\n");
 
    printf("Cost             = %d\n", matrixChainOrder(dims, n));
    printf("Optimal Multiply = %s\n\n", getOptimalParenthesizations(order, 0, n - 1));
}
 
int** cost;
int** order;
 
int matrixChainOrder(int* dims, int n) {
    cost = (int**)malloc(sizeof(int*) * n);
    order = (int**)malloc(sizeof(int*) * n);
    for (int i = 0; i < n; i++) {
        cost[i] = (int*)malloc(sizeof(int) * n);
        order[i] = (int*)malloc(sizeof(int) * n);
    }
 
    for (int lenMinusOne = 1 ; lenMinusOne < n ; lenMinusOne++) {
        for (int i = 0; i < n - lenMinusOne; i++) {
            int j = i + lenMinusOne;
            cost[i][j] = INT_MAX;
            for (int k = i; k < j; k++) {
                int currentCost = cost[i][k] + cost[k+1][j] + dims[i]*dims[k+1]*dims[j+1];
                if (currentCost < cost[i][j]) {
                    cost[i][j] = currentCost;
                    order[i][j] = k;
                }
            }
        }
    }
    return cost[0][n-1];
}
 
char* getOptimalParenthesizations(int** s, int i, int j) {
    if (i == j) {
        char* str = (char*)malloc(sizeof(char) * 2);
        str[0] = i + 65;
        str[1] = '\0';
        return str;
    }
    else {
        char* str = (char*)malloc(sizeof(char) * 100);
        str[0] = '(';
        strcat(str, getOptimalParenthesizations(s, i, s[i][j]));
        strcat(str, " * ");
        strcat(str, getOptimalParenthesizations(s, s[i][j] + 1, j));
        strcat(str, ")");
        return str;
    }
}

#include <stdio.h>
#include <math.h>
 
typedef struct {
  int x;
  int y;
} Pixel;
 
typedef struct {
  int r;
  int g;
  int b;
} RGBColour;
 
typedef struct {
  int width;
  int height;
  RGBColour *pixels;
} Pixmap;
 
void draw_line(Pixmap *bitmap, Pixel p1, Pixel p2, RGBColour colour) {
  int x0 = p1.x;
  int y0 = p1.y;
  int x1 = p2.x;
  int y1 = p2.y;
  int dx = abs(x1 - x0);
  int dy = abs(y1 - y0);
  int sx = x0 < x1? 1 : -1;
  int sy = y0 < y1? 1 : -1;
  int err = dx - dy;
  int e2;
  while (1) {
    bitmap->pixels[y0 * bitmap->width + x0] = colour;
    if (x0 == x1 && y0 == y1) break;
    e2 = 2 * err;
    if (e2 > -dy) {
      err -= dy;
      x0 += sx;
    }
    if (e2 < dx) {
      err += dx;
      y0 += sy;
    }
  }
}
 
void draw_circle(Pixmap *bitmap, Pixel centre, int radius, RGBColour colour) {
  int x = radius;
  int y = 0;
  int radiusError = 1 - x;
  while (x >= y) {
    bitmap->pixels[(centre.y + y) * bitmap->width + centre.x + x] = colour;
    bitmap->pixels[(centre.y + y) * bitmap->width + centre.x - x] = colour;
    bitmap->pixels[(centre.y - y) * bitmap->width + centre.x + x] = colour;
    bitmap->pixels[(centre.y - y) * bitmap->width + centre.x - x] = colour;
    bitmap->pixels[(centre.y + x) * bitmap->width + centre.x + y] = colour;
    bitmap->pixels[(centre.y + x) * bitmap->width + centre.x - y] = colour;
    bitmap->pixels[(centre.y - x) * bitmap->width + centre.x + y] = colour;
    bitmap->pixels[(centre.y - x) * bitmap->width + centre.x - y] = colour;
    y++;
    if (radiusError < 0) {
      radiusError += 2 * y + 1;
    } else {
      x--;
      radiusError += 2 * (y - x + 1);
    }
  }
}
 
void draw_bezier_curve(Pixmap *bitmap, Pixel *points, int n, RGBColour colour) {
  int xmin = points[0].x;
  int xmax = points[n-1].x;
  int increment = 2;
  Pixel prev = points[0];
  for (int x = xmin + increment; x <= xmax; x += increment) {
    double t = (double)(x - xmin) / (xmax - xmin);
    Pixel p = {x, bezier(t, points, n)};
    draw_line(bitmap, prev, p, colour);
    prev = p;
  }
}
 
double bezier(double t, Pixel *points, int n) {
  double sum = 0.0;
  for (int i = 0; i < n; i++) {
    sum += nchoosek(n - 1, i) * pow(1 - t, n - 1 - i) * pow(t, i) * points[i].y;
  }
  return sum;
}
 
double nchoosek(int n, int k) {
  return factorial(n) / (factorial(k) * factorial(n - k));
}
 
double factorial(int n) {
  double product = 1.0;
  for (int i = 2; i <= n; i++) {
    product *= i;
  }
  return product;
}
 
int main() {
  Pixmap bitmap = {400, 400, malloc(400 * 400 * sizeof(RGBColour))};
  RGBColour red = {255, 0, 0};
  RGBColour blue = {0, 0, 255};
  Pixel points[] = {{40,100}, {100,350}, {150,50}, {150,150}, {350,250}, {250,250}};
  for (int i = 0; i < 6; i++) {
    draw_circle(&bitmap, points[i], 3, red);
  }
  draw_bezier_curve(&bitmap, points, 6, blue);
  FILE *f = fopen("bezier.ppm", "w");
  fprintf(f, "P3\n%d %d\n255\n", bitmap.width, bitmap.height);
  for (int i = 0; i < bitmap.width * bitmap.height; i++) {
    fprintf(f, "%d %d %d\n", bitmap.pixels[i].r, bitmap.pixels[i].g, bitmap.pixels[i].b);
  }
  fclose(f);
  free(bitmap.pixels);
  return 0;
}

