#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdbool.h>
 
#define MEM_SIZE 5000
 
int main(int argc, char **argv) {
    if (argc < 2) {
        printf("Usage: %s [path] (--debug)\n", argv[0]);
        return 1;
    }
 
    // Read the source file
    FILE *f = fopen(argv[1], "r");
    if (f == NULL) {
        printf("Error opening '%s'\n", argv[1]);
        return 1;
    }
 
    fseek(f, 0, SEEK_END);
    long fsize = ftell(f);
    fseek(f, 0, SEEK_SET);
 
    char *src = malloc(fsize + 1);
    fread(src, fsize, 1, f);
    fclose(f);
    src[fsize] = 0;
 
    // Launch options
    bool debug = false;
    for (int i = 2; i < argc; i++) {
        if (strcmp(argv[i], "--debug") == 0) {
            debug = true;
        }
    }
 
    // One pass to find bracket pairs.
    int brackets[MEM_SIZE];
    memset(brackets, 0, sizeof(brackets));
    int scope_stack[MEM_SIZE];
    int scope_stack_len = 0;
    for (int i = 0; i < fsize; i++) {
        switch (src[i]) {
            case '[':
                scope_stack[scope_stack_len++] = i;
                break;
            case ']':
                brackets[scope_stack[--scope_stack_len]] = i;
                break;
        }
    }
 
    int pc = 0;
    uint8_t mem[MEM_SIZE] = {0};
    int ptr = 0;
    int stack[MEM_SIZE];
    int stack_len = 0;
 
    while (pc < fsize) {
        uint8_t val = mem[ptr];
 
        if (debug) {
            printf("(BFDB) PC: %04d \tPTR: %04d \t$PTR: %03d \tSTACK_DEPTH: %d \tSYMBOL: %c\n", pc, ptr, val, stack_len, src[pc]);
        }
 
        switch (src[pc]) {
            case '>':
                ptr++;
                break;
            case '<':
                ptr--;
                break;
 
            case '+':
                mem[ptr]++;
                break;
            case '-':
                mem[ptr]--;
                break;
 
            case '[':
                if (val == 0) {
                    pc = brackets[pc];
                } else {
                    stack[stack_len++] = pc;
                }
                break;
            case ']':
                int matching_bracket = stack[--stack_len];
                if (val!= 0) {
                    pc = matching_bracket - 1;
                }
                break;
 
            case '.':
                if (debug) {
                    printf("(BFDB) STDOUT: '%c'\n", val);  // Intercept output
                } else {
                    putchar(val);
                }
                break;
            case ',':
                mem[ptr] = getchar();
                break;
        }
 
        pc++;
    }
 
    return 0;
}

