#include <stdio.h>
#include <stdlib.h>
#include <math.h>
#include <string.h>
#include <assert.h>
 
#define MAX_N 25
 
typedef int (*matrix)[MAX_N];
 
int prod(matrix a, int n, int *sigma)
{
    int i, p = 1;
    for (i = 0; i < n; i++)
        p *= a[i][sigma[i]];
    return p;
}
 
int perm(matrix a, int n)
{
    int i, j, p = 0;
    int *sigma = malloc(n * sizeof(int));
    for (i = 0; i < n; i++)
        sigma[i] = i;
    do {
        p += prod(a, n, sigma);
    } while (next_permutation(sigma, n));
    free(sigma);
    return p;
}
 
int sign(int *sigma, int n)
{
    int i, j, s = 1;
    for (i = 0; i < n; i++) {
        for (j = i + 1; j < n; j++) {
            if (sigma[j] < sigma[i])
                s = -s;
        }
    }
    return s;
}
 
int det(matrix a, int n)
{
    int i, j, p = 0;
    int *sigma = malloc(n * sizeof(int));
    for (i = 0; i < n; i++)
        sigma[i] = i;
    do {
        p += sign(sigma, n) * prod(a, n, sigma);
    } while (next_permutation(sigma, n));
    free(sigma);
    return p;
}
 
int next_permutation(int *sigma, int n)
{
    int i, j, t;
    for (i = n - 2; i >= 0; i--) {
        if (sigma[i] < sigma[i + 1]) {
            for (j = n - 1; j > i; j--) {
                if (sigma[j] > sigma[i])
                    break;
            }
            t = sigma[i];
            sigma[i] = sigma[j];
            sigma[j] = t;
            for (j = 0; j < (n - i) / 2; j++) {
                t = sigma[i + 1 + j];
                sigma[i + 1 + j] = sigma[n - 1 - j];
                sigma[n - 1 - j] = t;
            }
            return 1;
        }
    }
    return 0;
}
 
void print_matrix(matrix a, int n)
{
    int i, j;
    for (i = 0; i < n; i++) {
        for (j = 0; j < n; j++)
            printf("%3d ", a[i][j]);
        printf("\n");
    }
}
 
int main(void)
{
    int a[MAX_N][MAX_N];
    int n, i, j;
 
    for (n = 2; n <= MAX_N; n++) {
        for (i = 0; i < n; i++) {
            for (j = 0; j < n; j++)
                a[i][j] = i * n + j + 1;
        }
        printf("n = %d\n", n);
        print_matrix(a, n);
        printf("Perm: %d Det: %d\n", perm(a, n), det(a, n));
    }
    return 0;
}

