#include <stdio.h>
#include <stdlib.h>
#include <string.h>
 
typedef struct list_t {
    char *value;
    struct list_t *next;
} list_t;
 
list_t *list_new(char *value) {
    list_t *list = malloc(sizeof(list_t));
    list->value = value;
    list->next = NULL;
    return list;
}
 
list_t *list_append(list_t *list, char *value) {
    list_t *new_list = list_new(value);
    list_t *current = list;
    while (current->next!= NULL) {
        current = current->next;
    }
    current->next = new_list;
    return list;
}
 
list_t *list_concat(list_t *list1, list_t *list2) {
    list_t *current = list1;
    while (current->next!= NULL) {
        current = current->next;
    }
    current->next = list2;
    return list1;
}
 
list_t *list_except(list_t *list1, list_t *list2) {
    list_t *result = NULL;
    list_t *current = list1;
    while (current!= NULL) {
        list_t *current2 = list2;
        int found = 0;
        while (current2!= NULL) {
            if (strcmp(current->value, current2->value) == 0) {
                found = 1;
                break;
            }
            current2 = current2->next;
        }
        if (!found) {
            result = list_append(result, current->value);
        }
        current = current->next;
    }
    return result;
}
 
list_t *list_symmetric_difference(list_t *list1, list_t *list2) {
    list_t *result = list_except(list1, list2);
    result = list_concat(result, list_except(list2, list1));
    return result;
}
 
void list_print(list_t *list) {
    list_t *current = list;
    while (current!= NULL) {
        printf("%s\n", current->value);
        current = current->next;
    }
}
 
int main() {
    list_t *a = list_new("John");
    a = list_append(a, "Bob");
    a = list_append(a, "Mary");
    a = list_append(a, "Serena");
 
    list_t *b = list_new("Jim");
    b = list_append(b, "Mary");
    b = list_append(b, "John");
    b = list_append(b, "Bob");
 
    list_t *result = list_symmetric_difference(a, b);
    list_print(result);
 
    return 0;
}

#include <stdio.h>
