int is_palindrome(char *s) {
    int len = strlen(s);
    for (int i = 0; i < len / 2; i++) {
        if (s[i]!= s[len - i - 1]) {
            return 0;
        }
    }
    return 1;
}
 
int main() {
    time_t now = time(NULL);
    struct tm *date = localtime(&now);
    int count = 0;
    while (count < 15) {
        char buf[11];
        strftime(buf, 11, "%Y%m%d", date);
        if (is_palindrome(buf)) {
            strftime(buf, 11, "%F", date);
            printf("%s\n", buf);
            count++;
        }
        date->tm_mday++;
        mktime(date);
    }
    return 0;
}

