#include <random>
#include <iostream>
#include <stack>
#include <set>
#include <string>
#include <functional>
using namespace std;
 
class RPNParse
{
public:
  stack<double> stk;
  multiset<int> digits;
 
  void op(function<double(double,double)> f)
  {
    if(stk.size() < 2)
      throw "Improperly written expression";
    int b = stk.top(); stk.pop();
    int a = stk.top(); stk.pop();
    stk.push(f(a, b));
  }
 
  void parse(char c)
  {
    if(c >= '0' && c <= '9')
    {
      stk.push(c - '0');
      digits.insert(c - '0');
    }
    else if(c == '+')
      op([](double a, double b) {return a+b;});
    else if(c == '-')
      op([](double a, double b) {return a-b;});
    else if(c == '*')
      op([](double a, double b) {return a*b;});
    else if(c == '/')
      op([](double a, double b) {return a/b;});
  }
 
  void parse(string s)
  {
    for(int i = 0; i < s.size(); ++i)
      parse(s[i]);
  }
 
  double getResult()
  {
    if(stk.size()!= 1)
      throw "Improperly written expression";
    return stk.top();
  }
};
 
int main()
{
  random_device seed;
  mt19937 engine(seed());
  uniform_int_distribution<> distribution(1, 9);
  auto rnd = bind(distribution, engine);
 
  multiset<int> digits;
  cout << "Make 24 with the digits: ";
  for(int i = 0; i < 4; ++i)
  {
    int n = rnd();
    cout << " " << n;
    digits.insert(n);
  }
  cout << endl;
 
  RPNParse parser;
 
  try
  {
    string input;
    getline(cin, input);
    parser.parse(input);
 
    if(digits!= parser.digits)
      cout << "Error: Not using the given digits" << endl;
    else
    {
      double r = parser.getResult();
      cout << "Result: " << r << endl;
 
      if(r > 23.999 && r < 24.001)
        cout << "Good job!" << endl;
      else
        cout << "Try again." << endl;
    }
  }
  catch(char* e)
  {
    cout << "Error: " << e << endl;
  }
  return 0;
}

// version 1.0.5-2
 
int ipow(int base, int exp) {
    if (exp < 0) {
        throw "negative exponents not allowed";
    }
    if (exp == 0) {
        return 1;
    }
    int ans = 1;
    while (exp!= 0) {
        if (exp & 1 == 1) {
            ans *= base;
        }
        exp = exp >> 1;
        base *= base;
    }
    return ans;
}
 
int main(int argc, char** argv) {
    printf("5**3**2   = %d\n", ipow(5, ipow(3, 2)));
    printf("(5**3)**2 = %d\n", ipow(ipow(5, 3), 2));
    printf("5**(3**2) = %d\n", ipow(5, ipow(3, 2)));
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <curl/curl.h>

struct string {
  char *ptr;
  size_t len;
};

void init_string(struct string *s) {
  s->len = 0;
  s->ptr = malloc(s->len+1);
  if (s->ptr == NULL) {
    fprintf(stderr, "malloc() failed\n");
    exit(EXIT_FAILURE);
  }
  s->ptr[0] = '\0';
}

size_t writefunc(void *ptr, size_t size, size_t nmemb, struct string *s)
{
  size_t new_len = s->len + size*nmemb;
  s->ptr = realloc(s->ptr, new_len+1);
  if (s->ptr == NULL) {
    fprintf(stderr, "realloc() failed\n");
    exit(EXIT_FAILURE);
  }
  memcpy(s->ptr+s->len, ptr, size*nmemb);
  s->ptr[new_len] = '\0';
  s->len = new_len;

  return size*nmemb;
}

int main(void)
{
  CURL *curl;
  CURLcode res;
  struct string s;

  init_string(&s);

  curl = curl_easy_init();
  if(curl) {
    curl_easy_setopt(curl, CURLOPT_URL, "http://rosettacode.org");
    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, writefunc);
    curl_easy_setopt(curl, CURLOPT_WRITEDATA, &s);
    res = curl_easy_perform(curl);
    if(res!= CURLE_OK)
      fprintf(stderr, "curl_easy_perform() failed: %s\n",
              curl_easy_strerror(res));

    curl_easy_cleanup(curl);
  }
  printf("%s\n", s.ptr);
  free(s.ptr);
  return 0;
}

#include <stdio.h>
#include <math.h>
 
#define N 32
#define STEP 0.05
 
double thiele(double *x, double *y, double xin) {
    double p[N][N];
    int i, j;
 
    for (i = 0; i < N; i++)
        p[i][0] = y[i];
 
    for (i = 0; i < N - 1; i++)
        p[i][1] = (x[i] - x[i + 1]) / (p[i][0] - p[i + 1][0]);
 
    for (i = 2; i < N; i++)
        for (j = 0; j < N - i; j++)
            p[j][i] = (x[j] - x[j + i]) / (p[j][i - 1] - p[j + 1][i - 1]) + p[j + 1][i - 2];
 
    double a = 0;
    for (i = N - 1; i > 1; i--)
        a = (xin - x[i - 1]) / (p[0][i] - p[0][i - 2] + a);
    return y[0] + (xin - x[0]) / (p[0][1] + a);
}
 
int main() {
    double x[N], sin[N], cos[N], tan[N];
    int i;
 
    for (i = 0; i < N; i++)
        x[i] = i * STEP;
 
    for (i = 0; i < N; i++) {
        sin[i] = sin(x[i]);
        cos[i] = cos(x[i]);
        tan[i] = tan(x[i]);
    }
 
    printf("%f\n%f\n%f\n", 6 * thiele(sin, x, 0.5), 3 * thiele(cos, x, 0.5), 4 * thiele(tan, x, 1));
}

