#include <stdio.h>
#include <stdlib.h>
#include <string.h>
 
typedef struct {
    char *fileBuffer, *keyBuffer, *outBuffer, *outName;
} cipher;
 
char *readFile( char *fl ) {
    char *buffer = NULL;
    FILE *f = fopen( fl, "r" );
    if( f ) {
        fseek( f, 0, SEEK_END );
        long l = ftell( f );
        fseek( f, 0, SEEK_SET );
        buffer = malloc( l + 1 );
        fread( buffer, 1, l, f );
        fclose( f );
        buffer[l] = 0;
    }
    return buffer;
}
 
int saveOutput( cipher *c ) {
    FILE *o = fopen( c->outName, "w" );
    if( o ) {
        fwrite( c->outBuffer, 1, strlen( c->outBuffer ), o );
        fclose( o );
        return 1;
    }
    return 0;
}
 
int encode( cipher *c ) {
    size_t idx, len = strlen( c->keyBuffer ) >> 1;
    for( char *i = c->fileBuffer; *i; i++ ) {
        idx = strchr( c->keyBuffer, *i ) - c->keyBuffer;
        if( idx < len ) strncat( c->outBuffer, c->keyBuffer + idx + len, 1 );
        else strncat( c->outBuffer, i, 1 );
    }
    return saveOutput( c );
}
 
int decode( cipher *c ) {
    size_t idx, l = strlen( c->keyBuffer ), len = l >> 1;
    for( char *i = c->fileBuffer; *i; i++ ) {
        idx = strrchr( c->keyBuffer, *i ) - c->keyBuffer;
        if( idx >= len && idx < l ) strncat( c->outBuffer, c->keyBuffer + idx - len, 1 );
        else strncat( c->outBuffer, i, 1 );
    }
    return saveOutput( c );
}
 
int work( char *e, char *f, char *k ) {
    if( strlen( e ) < 1 ) return 0;
    cipher c = { readFile( f ), readFile( k ), "", NULL };
    if(!c.fileBuffer ) return 0;
    if(!c.keyBuffer ) return 0;
 
    c.outName = malloc( strlen( f ) + 5 );
    strcpy( c.outName, f );
    strcat( c.outName, "_out" );
 
    switch( e[0] ) {
        case 'e': return encode( &c );
        case 'd': return decode( &c );
    }
    return 0;
}
 
int main( int argc, char* argv[] ) {
    if( argc < 4 ) {
        printf( "<d or e>\tDecrypt or Encrypt\n<filename>\tInput file, the output file will have"
        "'_out' added to it.\n<key>\t\tfile with the key to encode/decode\n\n" );
    } else {
        if( work( argv[1], argv[2], argv[3] ) ) printf( "\nFile successfully saved!\n\n" );
        else printf( "Something went wrong!\n\n" );
    }
    return 0;
}

#include <stdio.h>
