int is_prime(int n) {
  int i;
  for (i = 2; i <= sqrt(n); i++) {
    if (n % i == 0) {
      return 0;
    }
  }
  return 1;
}
 
int num_divisors(int n) {
  int i, num_divisors = 1;
  for (i = 2; i <= n; i++) {
    if (is_prime(i) && n % i == 0) {
      int count = 0;
      while (n % i == 0) {
        count++;
        n /= i;
      }
      num_divisors *= count + 1;
    }
  }
  return num_divisors;
}
 
int main() {
  int i, n = 1, count = 0;
  while (count < 100) {
    if (n % num_divisors(n) == 0) {
      printf("%d\n", n);
      count++;
    }
    n++;
  }
  return 0;
}

