#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <stdbool.h>
 
int main() {
    srand(time(NULL));
    int k[9];
    int i;
    for (i = 0; i < 9; i++) {
        k[i] = rand() % 10;
        if (k[i] == 0) {
            k[i] = 9;
        }
    }
    int j;
    for (i = 0; i < 9; i++) {
        for (j = i + 1; j < 9; j++) {
            if (k[i] > k[j]) {
                int tmp = k[i];
                k[i] = k[j];
                k[j] = tmp;
            }
        }
    }
    printf("Sort digits by reversing a number of digits on the left.\n");
    int n, score = 0;
    while (true) {
        printf("Digits: ");
        for (i = 0; i < 9; i++) {
            printf("%d ", k[i]);
        }
        printf(". How many to reverse? ");
        scanf("%d", &n);
        score++;
        if (n < 2 || n > 9) {
            printf("\n(Enter a number from 2 to 9)\n");
            continue;
        }
        for (i = 0; i < n / 2; i++) {
            int tmp = k[i];
            k[i] = k[n - i - 1];
            k[n - i - 1] = tmp;
        }
        bool sorted = true;
        for (i = 0; i < 9; i++) {
            for (j = i + 1; j < 9; j++) {
                if (k[i] > k[j]) {
                    sorted = false;
                    break;
                }
            }
        }
        if (sorted) {
            printf("Digits: ");
            for (i = 0; i < 9; i++) {
                printf("%d ", k[i]);
            }
            printf(". Your score: %d. Good job.\n", score);
            return 0;
        }
    }
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
 
typedef struct node {
    int val;
    struct node *back;
} node;
 
int *lis(int *n, int len) {
    node **pileTops = malloc(len * sizeof(node *));
    int i, j;
    node *node;
    int *result;
    int resultLen = 0;
 
    // sort into piles
    for (i = 0; i < len; i++) {
        j = 0;
        while (j < resultLen && pileTops[j]->val < n[i]) {
            j++;
        }
        node = malloc(sizeof(node));
        node->val = n[i];
        node->back = NULL;
        if (j!= 0) {
            node->back = pileTops[j-1];
        }
        if (j!= resultLen) {
            pileTops[j] = node;
        } else {
            pileTops = realloc(pileTops, (resultLen+1) * sizeof(node *));
            pileTops[resultLen] = node;
            resultLen++;
        }
    }
 
    if (resultLen == 0) {
        return NULL;
    }
    result = malloc(resultLen * sizeof(int));
    for (node = pileTops[resultLen-1]; node!= NULL; node = node->back) {
        result[--resultLen] = node->val;
    }
    free(pileTops);
    return result;
}
 
int main() {
    int *result;
    int i;
    int d1[] = {3, 2, 6, 4, 5, 1};
    int d2[] = {0, 8, 4, 12, 2, 10, 6, 14, 1, 9, 5, 13, 3, 11, 7, 15};
    int *data[] = {d1, d2};
    int dataLen[] = {6, 16};
 
    for (i = 0; i < 2; i++) {
        result = lis(data[i], dataLen[i]);
        printf("an L.I.S. of ");
        for (int j = 0; j < dataLen[i]; j++) {
            printf("%d ", data[i][j]);
        }
        printf("is ");
        for (int j = 0; j < dataLen[i]; j++) {
            printf("%d ", result[j]);
        }
        printf("\n");
        free(result);
    }
    return 0;
}

