double deg2rad(double d) { return d * M_PI / 180; }
double rad2deg(double r) { return r * 180 / M_PI; }
 
double mean_angle(double *deg, int n) {
	double complex sum = 0;
	for (int i = 0; i < n; i++)
		sum += cexp(I * deg2rad(deg[i]));
	return rad2deg(carg(sum));
}
 
