#include <stdio.h>
#include <stdlib.h>
#include <string.h>
 
struct DataFrame {
  int sum;
  int *coins;
  int *avail_coins;
};
 
int main() {
  struct DataFrame *s = malloc(sizeof(struct DataFrame));
  s->sum = 100;
  s->coins = NULL;
  s->avail_coins = malloc(4 * sizeof(int));
  s->avail_coins[0] = 25;
  s->avail_coins[1] = 10;
  s->avail_coins[2] = 5;
  s->avail_coins[3] = 1;
  int ways = 0;
  while (s!= NULL) {
    struct DataFrame *top = s;
    s = s->next;
    if (top->sum < 0) continue;
    if (top->sum == 0) {
      ++ways;
      continue;
    }
    if (top->avail_coins == NULL) continue;
    struct DataFrame *d = malloc(sizeof(struct DataFrame));
    d->sum = top->sum - top->avail_coins[0];
    d->coins = malloc((top->coins_len + 1) * sizeof(int));
    memcpy(d->coins, top->coins, top->coins_len * sizeof(int));
    d->coins[top->coins_len] = top->avail_coins[0];
    d->coins_len = top->coins_len + 1;
    d->avail_coins = malloc((top->avail_coins_len - 1) * sizeof(int));
    memcpy(d->avail_coins, top->avail_coins + 1, (top->avail_coins_len - 1) * sizeof(int));
    d->avail_coins_len = top->avail_coins_len - 1;
    d->next = s;
    s = d;
    d = malloc(sizeof(struct DataFrame));
    d->sum = top->sum;
    d->coins = malloc(top->coins_len * sizeof(int));
    memcpy(d->coins, top->coins, top->coins_len * sizeof(int));
    d->coins_len = top->coins_len;
    d->avail_coins = malloc((top->avail_coins_len - 1) * sizeof(int));
    memcpy(d->avail_coins, top->avail_coins + 1, (top->avail_coins_len - 1) * sizeof(int));
    d->avail_coins_len = top->avail_coins_len - 1;
    d->next = s;
    s = d;
    free(top->coins);
    free(top->avail_coins);
    free(top);
  }
  printf("%d\n", ways);
  return 0;
}

