#include <stdio.h>
#include <math.h>
#include <string.h>
#include <stdlib.h>

double meanAngle(double *angles, int len) {
    double sinSum = 0.0;
    int i;
    for (i = 0; i < len; i++) {
        sinSum += sin(angles[i] * M_PI / 180.0);
    }

    double cosSum = 0.0;
    for (i = 0; i < len; i++) {
        cosSum += cos(angles[i] * M_PI / 180.0);
    }

    return atan2(sinSum / len, cosSum / len) * 180.0 / M_PI;
}

/* time string assumed to be in format "hh:mm:ss" */
int timeToSecs(char *t) {
    int hours = atoi(strtok(t, ":"));
    int mins  = atoi(strtok(NULL, ":"));
    int secs  = atoi(strtok(NULL, ":"));
    return 3600 * hours + 60 * mins + secs;
}

/* 1 second of time = 360/(24 * 3600) = 1/240th degree */
double timeToDegrees(char *t) {
    return timeToSecs(t) / 240.0;
}

char *degreesToTime(double d) {
    if (d < 0.0) d += 360.0;
    int secs  = (int)(d * 240.0);
    int hours = secs / 3600;
    int mins  = secs % 3600;
    secs = mins % 60;
    mins /= 60;
    char *t = malloc(sizeof(char) * 10);
    sprintf(t, "%2d:%2d:%2d", hours, mins, secs);
    return t;
}

int main(int argc, char **argv) {
    char *tm[] = {"23:00:17", "23:40:20", "00:12:45", "00:17:19"};
    double angles[4];
    int i;
    for (i = 0; i < 4; i++) angles[i] = timeToDegrees(tm[i]);
    double mean = meanAngle(angles, 4);
    printf("Average time is : %s\n", degreesToTime(mean));
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
 
int gcd(int a, int b) {
    int aa = a;
    int bb = b;
    while (aa!= bb) {
        if (aa > bb)
            aa -= bb;
        else
            bb -= aa;
    }
    return aa;
}
 
#define LIMIT 100
 
int main(int argc, char *argv[]) {
    int starts[] = {2, 5, 7, 9, 10};
    int ekg[5][LIMIT];
 
    for (int s = 0; s < 5; s++) {
        ekg[s][0] = 1;
        ekg[s][1] = starts[s];
        for (int n = 2; n < LIMIT; n++) {
            int i = 2;
            while (1) {
                // a potential sequence member cannot already have been used
                // and must have a factor in common with previous member
                int found = 1;
                for (int j = 0; j < n; j++) {
                    if (ekg[s][j] == i) {
                        found = 0;
                        break;
                    }
                }
                if (found && gcd(ekg[s][n - 1], i) > 1) {
                    ekg[s][n] = i;
                    break;
                }
                i++;
            }
        }
        printf("EKG(%2d): ", starts[s]);
        for (int i = 0; i < 30; i++) {
            printf("%d ", ekg[s][i]);
        }
        printf("\n");
    }   
 
    // now compare EKG5 and EKG7 for convergence
    for (int i = 2; i < LIMIT; i++) {
        if (ekg[1][i] == ekg[2][i]) {
            int found = 1;
            for (int j = 0; j < i; j++) {
                if (ekg[1][j]!= ekg[2][j]) {
                    found = 0;
                    break;
                }
            }
            if (found) {
                printf("\nEKG(5) and EKG(7) converge at term %d\n", i + 1);
                return 0;
            }
        }
    }
    printf("\nEKG5(5) and EKG(7) do not converge within %d terms\n", LIMIT);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
 
typedef struct {
    int *data;
    int size;
    int capacity;
} queue;
 
queue *queue_new(int capacity) {
    queue *q = malloc(sizeof(queue));
    q->data = malloc(sizeof(int) * capacity);
    q->size = 0;
    q->capacity = capacity;
    return q;
}
 
void queue_free(queue *q) {
    free(q->data);
    free(q);
}
 
void queue_push(queue *q, int value) {
    if (q->size == q->capacity) {
        q->capacity *= 2;
        q->data = realloc(q->data, sizeof(int) * q->capacity);
    }
    q->data[q->size++] = value;
}
 
int queue_pop(queue *q) {
    return q->data[--q->size];
}
 
int queue_peek(queue *q) {
    return q->data[q->size - 1];
}
 
int queue_empty(queue *q) {
    return q->size == 0;
}
 
int int_cmp(const void *a, const void *b) {
    return *(int *)a - *(int *)b;
}
 
void merge2(int *a, int *b, int *result, int a_size, int b_size) {
    queue *q1 = queue_new(a_size);
    queue *q2 = queue_new(b_size);
    int i;
    for (i = 0; i < a_size; i++) queue_push(q1, a[i]);
    for (i = 0; i < b_size; i++) queue_push(q2, b[i]);
    int j = 0;
    while (!queue_empty(q1) &&!queue_empty(q2)) {
        if (queue_peek(q1) < queue_peek(q2)) {
            result[j++] = queue_pop(q1);
        } else {
            result[j++] = queue_pop(q2);
        }
    }
    while (!queue_empty(q1)) result[j++] = queue_pop(q1);
    while (!queue_empty(q2)) result[j++] = queue_pop(q2);
    queue_free(q1);
    queue_free(q2);
}
 
void mergeN(int **sources, int *sizes, int *result, int n) {
    queue **queues = malloc(sizeof(queue *) * n);
    int i;
    for (i = 0; i < n; i++) {
        queues[i] = queue_new(sizes[i]);
        int j;
        for (j = 0; j < sizes[i]; j++) queue_push(queues[i], sources[i][j]);
    }
    int j = 0;
    while (1) {
        int min = 0;
        int k;
        for (k = 1; k < n; k++) {
            if (queue_peek(queues[k]) < queue_peek(queues[min])) min = k;
        }
        if (queue_empty(queues[min])) break;
        result[j++] = queue_pop(queues[min]);
    }
    for (i = 0; i < n; i++) queue_free(queues[i]);
    free(queues);
}
 
int main() {
    int a[] = {1, 4, 7, 10};
    int b[] = {2, 5, 8, 11};
    int c[] = {3, 6, 9, 12};
    int result[12];
    merge2(a, b, result, 4, 4);
    int i;
    for (i = 0; i < 8; i++) printf("%d ", result[i]);
    printf("\n");
    int *sources[] = {a, b, c};
    int sizes[] = {4, 4, 4};
    mergeN(sources, sizes, result, 3);
    for (i = 0; i < 12; i++) printf("%d ", result[i]);
    printf("\n");
    return 0;
}

#include <ncurses.h>
#include <stdlib.h>
#include <time.h>
#include <unistd.h>
 
#define ROW_DELAY 10000
 
int get_rand_in_range(int min, int max)
{
    return rand() % (max - min + 1) + min;
}
 
int main(int argc, char *argv[])
{
    int max_x, max_y;
    int i;
    int total_chars;
    int char_index;
    int *columns_row;
    int *columns_active;
    char *chars;
    WINDOW *stdscr;
 
    /* Characters to randomly appear in the rain sequence. */
    chars = "0123456789";
    total_chars = 10;
 
    stdscr = initscr();
    noecho();
    curs_set(FALSE);
 
    start_color();
    init_pair(1, COLOR_GREEN, COLOR_BLACK);
    attron(COLOR_PAIR(1));
 
    getmaxyx(stdscr, max_y, max_x);
 
    /* Create arrays of columns based on screen width. */
    columns_row = malloc(sizeof(int) * (max_x + 1));
    columns_active = malloc(sizeof(int) * (max_x + 1));
 
    for (i = 0; i < max_x; i++) {
        columns_row[i] = -1;
        columns_active[i] = 0;
    }
 
    while (1) {
        for (i = 0; i < max_x; i++) {
            if (columns_row[i] == -1) {
                /* If a column is at the top row, pick a random starting row and active status. */
                columns_row[i] = get_rand_in_range(0, max_y);
                columns_active[i] = get_rand_in_range(0, 1);
            }
        }
 
        /* Loop through columns and draw characters on rows */
        for (i = 0; i < max_x; i++) {
            if (columns_active[i] == 1) {
                /* Draw a random character at this column's current row. */
                char_index = get_rand_in_range(0, total_chars - 1);
                mvprintw(columns_row[i], i, "%c", chars[char_index]);
            } else {
                /* Draw an empty character if the column is inactive. */
                mvprintw(columns_row[i], i, " ");
            }
 
            columns_row[i]++;
 
            /* When a column reaches the bottom row, reset to top. */
            if (columns_row[i] >= max_y) {
                columns_row[i] = -1;
            }
 
            /* Randomly alternate the column's active status. */
            if (get_rand_in_range(0, 1000) == 0) {
                if (columns_active[i] == 0) {
                    columns_active[i] = 1;
                } else {
                    columns_active[i] = 0;
                }
            }
 
            usleep(ROW_DELAY);
            refresh();
        }
    }
 
    endwin();
 
    return 0;
}

#include <stdio.h>
#include <stdbool.h>
 
int main(void) 
{
    printf("Find a solution to i = 2 * j - 7\n");
    int answer[2];
    for(int i = 0; true; i++)
    {
        for(int j = 0; j < i; j++)
        {
            if( i == 2 * j - 7)
            {
                // use brute force and run until a solution is found
                answer[0] = i;
                answer[1] = j;
                goto loopexit;
            }
        }
    }
 
loopexit:
    printf("%d = 2 * %d - 7\n\n", answer[0], answer[1]); 
 
    // jumping out of nested loops is the main usage of goto in
    // C++.  goto can be used in other places but there is usually
    // a better construct.  goto is not allowed to jump across
    // initialized variables which limits where it can be used.
    // this is case where C++ is more restrictive than C.
 
    goto spagetti;
 
    int k;
    k = 9;  // this is assignment, can be jumped over
 
    /* The line below won't compile because a goto is not allowed
     * to jump over an initialized value.
    int j = 9;
    */
 
spagetti:
 
    printf("k = %d\n", k);  // k was never initialized, accessing it is undefined behavior
 
}

#include <gtk/gtk.h>
