static void validate_input(GtkWindow *window, const char *str)
{
    char *endptr;
    long i = strtol(str, &endptr, 10);
    if (*endptr!= '\0') {
        GtkWidget *dialog = gtk_message_dialog_new(
            window,
            GTK_DIALOG_MODAL,
            GTK_MESSAGE_ERROR,
            GTK_BUTTONS_OK,
            "Invalid value"
        );
        gtk_dialog_run(GTK_DIALOG(dialog));
        gtk_widget_destroy(dialog);
    }
}
 
static void entry_activate(GtkEntry *entry, gpointer data)
{
    validate_input(data, gtk_entry_get_text(entry));
}
 
static void increment_clicked(GtkButton *button, gpointer data)
{
    GtkEntry *entry = data;
    const char *str = gtk_entry_get_text(entry);
    char *endptr;
    long i = strtol(str, &endptr, 10);
    if (*endptr == '\0') {
        char buf[100];
        snprintf(buf, sizeof(buf), "%ld", i + 1);
        gtk_entry_set_text(entry, buf);
    }
}
 
static void random_clicked(GtkButton *button, gpointer data)
{
    GtkWindow *window = data;
    GtkWidget *dialog = gtk_message_dialog_new(
        window,
        GTK_DIALOG_MODAL,
        GTK_MESSAGE_QUESTION,
        GTK_BUTTONS_YES_NO,
        "Set random value"
    );
    if (gtk_dialog_run(GTK_DIALOG(dialog)) == GTK_RESPONSE_YES) {
        char buf[100];
        snprintf(buf, sizeof(buf), "%d", rand() % 10000);
        gtk_entry_set_text(GTK_ENTRY(data), buf);
    }
    gtk_widget_destroy(dialog);
}
 
