// version 1.1.2
 
int waterCollected(int tower[], int n) {
    int highLeft[n];
    int highRight[n];
    int i;
    int j;
    int max;
    int sum;
    int water;
    highLeft[0] = 0;
    for (i = 1; i < n; i++) {
        max = 0;
        for (j = 0; j < i; j++) {
            if (tower[j] > max) {
                max = tower[j];
            }
        }
        highLeft[i] = max;
    }
    highRight[n - 1] = 0;
    for (i = n - 2; i >= 0; i--) {
        max = 0;
        for (j = n - 1; j > i; j--) {
            if (tower[j] > max) {
                max = tower[j];
            }
        }
        highRight[i] = max;
    }
    sum = 0;
    for (i = 0; i < n; i++) {
        water = highLeft[i] < highRight[i]? highLeft[i] : highRight[i];
        water -= tower[i];
        if (water < 0) {
            water = 0;
        }
        sum += water;
    }
    return sum;
}
 
int main(void) {
    int towers[7][15] = {
        {1, 5, 3, 7, 2},
        {5, 3, 7, 2, 6, 4, 5, 9, 1, 2},
        {2, 6, 3, 5, 2, 8, 1, 4, 2, 2, 5, 3, 5, 7, 4, 1},
        {5, 5, 5, 5},
        {5, 6, 7, 8},
        {8, 7, 7, 6},
        {6, 7, 10, 7, 6}
    };
    int i;
    int j;
    int n;
    int water;
    for (i = 0; i < 7; i++) {
        n = sizeof(towers[i]) / sizeof(int);
        water = waterCollected(towers[i], n);
        printf("%2d from ", water);
        for (j = 0; j < n; j++) {
            printf("%d ", towers[i][j]);
        }
        printf("\n");
    }
    return 0;
}

