#include <stdio.h>
#include <stdlib.h>
#include <time.h>
 
#define sSuits "CDHS"
#define sNums "A23456789TJQK"
#define rMax32 0x7fffffff
 
static int seed = 1;
 
static int rnd(void)
{
    seed = (seed * 214013 + 2531011) & rMax32;
    return seed >> 16;
}
 
static void deal(int s, int *t)
{
    seed = s;
    for (int i = 0; i < 52; i++) {
        t[i] = 51 - i;
    }
    for (int i = 0; i < 51; i++) {
        int j = 51 - rnd() % (52 - i);
        int tmp = t[i];
        t[i] = t[j];
        t[j] = tmp;
    }
}
 
static void show(int *cs, int n)
{
    for (int i = 0; i < n; i++) {
        printf(" %c%c", sNums[cs[i] / 4], sSuits[cs[i] % 4]);
        if ((i + 1) % 8 == 0 || i + 1 == n) {
            printf("\n");
        }
    }
}
 
int main(int argc, char *argv[])
{
    int game;
    switch (argc) {
    case 1:
        srand(time(NULL));
        game = 1 + rand() % 32000;
        break;
    case 2:
        game = atoi(argv[1]);
        if (game < 1 || game > 32000) {
            fprintf(stderr, "usage: deal [game]\n");
            fprintf(stderr, "       where game is a number in the range 1 to 32000\n");
            return 1;
        }
        break;
    default:
        fprintf(stderr, "usage: deal [game]\n");
        fprintf(stderr, "       where game is a number in the range 1 to 32000\n");
        return 1;
    }
    printf("\nGame #%d\n", game);
    int t[52];
    deal(game, t);
    show(t, 52);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
 
typedef struct {
  char *key;
  int value;
} myhash_entry;
 
typedef struct {
  myhash_entry *entries;
  int size;
} myhash;
 
myhash *myhash_new() {
  myhash *h = malloc(sizeof(myhash));
  h->entries = NULL;
  h->size = 0;
  return h;
}
 
void myhash_set(myhash *h, char *key, int value) {
  int i;
  for (i = 0; i < h->size; i++) {
    if (strcmp(h->entries[i].key, key) == 0) {
      h->entries[i].value = value;
      return;
    }
  }
  h->size++;
  h->entries = realloc(h->entries, sizeof(myhash_entry) * h->size);
  h->entries[h->size - 1].key = strdup(key);
  h->entries[h->size - 1].value = value;
}
 
int myhash_get(myhash *h, char *key) {
  int i;
  for (i = 0; i < h->size; i++) {
    if (strcmp(h->entries[i].key, key) == 0) {
      return h->entries[i].value;
    }
  }
  return 0;
}
 
void myhash_iterate(myhash *h, void (*callback)(char *key, int value)) {
  int i;
  for (i = 0; i < h->size; i++) {
    callback(h->entries[i].key, h->entries[i].value);
  }
}
 
void myhash_iterate_es5(myhash *h, void (*callback)(char *key, int value)) {
  int i;
  for (i = 0; i < h->size; i++) {
    callback(h->entries[i].key, h->entries[i].value);
  }
}
 
void print_entry(char *key, int value) {
  printf("Key is: %s. Value is: %d\n", key, value);
}
 
int main() {
  myhash *h = myhash_new();
  myhash_set(h, "hello", 3);
  myhash_set(h, "world", 6);
  myhash_set(h, "!", 9);
  myhash_iterate(h, print_entry);
  myhash_iterate_es5(h, print_entry);
  return 0;
}

#include <stdio.h>
 
// Arguments n, p as described in WP
// If Legendre symbol != 1, ok return is false.  Otherwise ok return is true,
// R1 is WP return value R and for convenience R2 is p-R1.
int ts(int n, int p, int *R1, int *R2) {
    // a^e mod p
    int powModP(int a, int e) {
        int s = 1;
        for (; e > 0; e--) {
            s = s * a % p;
        }
        return s;
    }
    // Legendre symbol, returns 1, 0, or -1 mod p -- that's 1, 0, or p-1.
    int ls(int a) {
        return powModP(a, (p-1)/2);
    }
    // argument validation
    if (ls(n)!= 1) {
        return 0;
    }
    // WP step 1, factor out powers two.
    // variables Q, S named as at WP.
    int Q = p - 1;
    int S = 0;
    for (; Q&1 == 0; ) {
        S++;
        Q >>= 1;
    }
    // WP step 1, direct solution
    if (S == 1) {
        *R1 = powModP(n, (p+1)/4);
        *R2 = p - *R1;
        return 1;
    }
    // WP step 2, select z, assign c
    int z = 2;
    for (; ls(z)!= p-1; z++) {
    }
    int c = powModP(z, Q);
    // WP step 3, assign R, t, M
    int R = powModP(n, (Q+1)/2);
    int t = powModP(n, Q);
    int M = S;
    // WP step 4, loop
    for (;;) {
        // WP step 4.1, termination condition
        if (t == 1) {
            *R1 = R;
            *R2 = p - R;
            return 1;
        }
        // WP step 4.2, find lowest i...
        int i = 0;
        for (int z = t; z!= 1 && i < M-1; ) {
            z = z * z % p;
            i++;
        }
        // WP step 4.3, using a variable b, assign new values of R, t, c, M
        int b = c;
        for (int e = M - i - 1; e > 0; e--) {
            b = b * b % p;
        }
        R = R * b % p;
        c = b * b % p; // more convenient to compute c before t
        t = t * c % p;
        M = i;
    }
}
 
int main() {
    int R1, R2;
    ts(10, 13, &R1, &R2);
    printf("%d %d\n", R1, R2);
    ts(56, 101, &R1, &R2);
    printf("%d %d\n", R1, R2);
    ts(1030, 10009, &R1, &R2);
    printf("%d %d\n", R1, R2);
    ts(1032, 10009, &R1, &R2);
    printf("%d %d\n", R1, R2);
    ts(44402, 100049, &R1, &R2);
    printf("%d %d\n", R1, R2);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
 
typedef struct Stack {
  int top;
  char *dataStore;
} Stack;
 
Stack *newStack() {
  Stack *s = malloc(sizeof(Stack));
  s->top = 0;
  s->dataStore = malloc(sizeof(char) * 100);
  return s;
}
 
void push(Stack *s, char element) {
  s->dataStore[s->top++] = element;
}
 
char pop(Stack *s) {
  return s->dataStore[--s->top];
}
 
char peek(Stack *s) {
  return s->dataStore[s->top-1];
}
 
int length(Stack *s) {
  return s->top;
}
 
int main() {
  char *infix = "3 + 4 * 2 / ( 1 - 5 ) ^ 2 ^ 3";
  infix = str_replace(infix, " ", ""); // remove spaces, so infix[i]!=" "
  Stack *s = newStack();
  char *ops = "-+/*^";
  int precedence[5] = {4, 3, 3, 2, 2};
  char *associativity[5] = {"Right", "Left", "Left", "Left", "Left"};
  char token;
  char *postfix = "";
  char o1, o2;
  int i;
  for (i = 0; i < strlen(infix); i++) {
    token = infix[i];
    if (token >= '0' && token <= '9') { // if token is operand (here limited to 0 <= x <= 9)
      postfix += token + " ";
    }
    else if (strchr(ops, token)!= NULL) { // if token is an operator
      o1 = token;
      o2 = peek(s);
      while (strchr(ops, o2)!= NULL && ( // while operator token, o2, on top of the stack
        // and o1 is left-associative and its precedence is less than or equal to that of o2
        (strcmp(associativity[strchr(ops, o1) - ops], "Left") == 0 && (precedence[strchr(ops, o1) - ops] <= precedence[strchr(ops, o2) - ops]) ) || 
        // the algorithm on wikipedia says: or o1 precedence < o2 precedence, but I think it should be
        // or o1 is right-associative and its precedence is less than that of o2
        (strcmp(associativity[strchr(ops, o1) - ops], "Right") == 0 && (precedence[strchr(ops, o1) - ops] < precedence[strchr(ops, o2) - ops])) 
        )){
          postfix += o2 + " "; // add o2 to output queue
          pop(s); // pop o2 of the stack
          o2 = peek(s); // next round
      }
      push(s, o1); // push o1 onto the stack
    }
    else if (token == "(") { // if token is left parenthesis
      push(s, token); // then push it onto the stack
    }
    else if (token == ")") { // if token is right parenthesis 
      while (peek(s)!= "("){ // until token at top is (
        postfix += pop(s) + " ";
      }
      pop(s); // pop (, but not onto the output queue
    }
  }
  postfix += s->dataStore.reverse().join(" ");
  printf("%s\n", postfix);
  return 0;
}

