#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <stdbool.h>
#include <assert.h>
 
#define MAX_WORD_LEN 100
#define MAX_WORDS 100000
 
typedef struct {
  char word[MAX_WORD_LEN];
  int count;
} word_t;
 
int compare_words(const void *a, const void *b) {
  const word_t *wa = (const word_t *)a;
  const word_t *wb = (const word_t *)b;
  return wb->count - wa->count;
}
 
int main(int argc, char **argv) {
  int head = (argc > 1)? atoi(argv[1]) : 10;
  FILE *file = stdin;
  if (argc > 2) {
    file = fopen(argv[2], "r");
    if (file == NULL) {
      fprintf(stderr, "file %s open failed\n", argv[2]);
      return 1;
    }
  }
  word_t words[MAX_WORDS];
  int num_words = 0;
  char word[MAX_WORD_LEN];
  int word_len = 0;
  int c;
  while ((c = fgetc(file))!= EOF) {
    if (isalpha(c)) {
      word[word_len++] = tolower(c);
    } else if (word_len > 0) {
      word[word_len] = '\0';
      int i;
      for (i = 0; i < num_words; i++) {
        if (strcmp(word, words[i].word) == 0) {
          words[i].count++;
          break;
        }
      }
      if (i == num_words) {
        strcpy(words[num_words].word, word);
        words[num_words].count = 1;
        num_words++;
      }
      word_len = 0;
    }
  }
  if (word_len > 0) {
    word[word_len] = '\0';
    int i;
    for (i = 0; i < num_words; i++) {
      if (strcmp(word, words[i].word) == 0) {
        words[i].count++;
        break;
      }
    }
    if (i == num_words) {
      strcpy(words[num_words].word, word);
      words[num_words].count = 1;
      num_words++;
    }
  }
  assert(num_words <= MAX_WORDS);
  qsort(words, num_words, sizeof(word_t), compare_words);
  int i;
  for (i = 0; i < head && i < num_words; i++) {
    printf("%s %d\n", words[i].word, words[i].count);
  }
  return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <math.h>
 
int num_divisors(int n) {
  int prod = 1;
  int p = 2;
  int n_p = 0;
  while (n > 1) {
    if (n % p == 0) {
      n_p++;
      n /= p;
    } else {
      prod *= (n_p + 1);
      n_p = 0;
      p++;
    }
  }
  return prod;
}
 
int first_with_num_divs(int n) {
  int i = 1;
  while (num_divisors(i)!= n) {
    i++;
  }
  return i;
}
 
int main(int argc, char *argv[]) {
  int i;
  for (i = 1; i <= 15; i++) {
    printf("%d\n", first_with_num_divs(i));
  }
  return 0;
}

