#include <gmp.h>
#include <pthread.h>
 
#define MAX_PRIMES 1000000
 
typedef struct {
    int start;
    int end;
    mpz_t result;
} thread_data;
 
int primes[MAX_PRIMES];
 
void *partial(void *arg) {
    thread_data *data = (thread_data *)arg;
    int i;
    mpz_t aux;
    mpz_init(aux);
    mpz_set_ui(aux, 1);
    for (i = data->start; i <= data->end; i++) {
        mpz_mul_ui(aux, aux, primes[i]);
    }
    mpz_set(data->result, aux);
    mpz_clear(aux);
    return NULL;
}
 
int main() {
    int i, j, k, n, count;
    mpz_t j1;
    mpz_init(j1);
    for (i = 0; i < 10; i++) {
        mpz_primorial_ui(j1, i + 2);
        gmp_printf("Primorial : %Zd\n", j1);
    }
    mpz_set_ui(j1, 1);
    for (i = 0; i < 10; i++) {
        mpz_mul_ui(j1, j1, primes[i]);
    }
    gmp_printf("Digits of primorial 10 : %Zd\n", j1);
    mpz_set_ui(j1, 1);
    for (i = 0; i < 100; i++) {
        mpz_mul_ui(j1, j1, primes[i]);
    }
    gmp_printf("Digits of primorial 100 : %Zd\n", j1);
    mpz_set_ui(j1, 1);
    for (i = 0; i < 1000; i++) {
        mpz_mul_ui(j1, j1, primes[i]);
    }
    gmp_printf("Digits of primorial 1000 : %Zd\n", j1);
    mpz_set_ui(j1, 1);
    for (i = 0; i < 10000; i++) {
        mpz_mul_ui(j1, j1, primes[i]);
    }
    gmp_printf("Digits of primorial 10000 : %Zd\n", j1);
    mpz_set_ui(j1, 1);
    for (i = 0; i < 100000; i++) {
        mpz_mul_ui(j1, j1, primes[i]);
    }
    gmp_printf("Digits of primorial 100000 : %Zd\n", j1);
 
    mpz_set_ui(j1, 1);
    pthread_t threads[4];
    thread_data data[4];
    for (i = 0; i < 4; i++) {
        data[i].start = i * 250000;
        data[i].end = (i + 1) * 250000 - 1;
        mpz_init(data[i].result);
        pthread_create(&threads[i], NULL, partial, &data[i]);
    }
    for (i = 0; i < 4; i++) {
        pthread_join(threads[i], NULL);
        mpz_mul(j1, j1, data[i].result);
        mpz_clear(data[i].result);
    }
    gmp_printf("Digits of primorial 1000000 : %Zd\n", j1);
    mpz_clear(j1);
    return 0;
}

task_description:
This task has been clarified. Its programming examples are in need of review to ensure that they still fit the requirements of the task.
This task is inverse to the task Call foreign language function. Consider the following C program:

#include <stdio.h>
 
extern int Query (char * Data, size_t * Length);
 
int main (int argc, char * argv [])
{
   char     Buffer [1024];
   size_t   Size = sizeof (Buffer);
 
   if (0 == Query (Buffer, &Size))
   {
      printf ("failed to call Query\n");
   }
   else
   {
      char * Ptr = Buffer;
      while (Size-- > 0) putchar (*Ptr++);
      putchar ('\n');
   }
}
Implement the missing Query function in your language, and let this C program call it. The function should place the string Here am I into the buffer which is passed to it as the parameter Data. The buffer size in bytes is passed as the parameter Length. When there is no room in the buffer, Query shall return 0. Otherwise it overwrites the beginning of Buffer, sets the number of overwritten bytes into Length and returns 1.

code:
#include <string.h>
 
// C functions can get called from C++.
int
Query (char *Data, size_t *Length)
{
   const char Message[] = "Here am I";
 
   // Check that Message fits in Data.
   if (*Length < sizeof Message)
      return 0;  // C++ converts bool to int.
 
   *Length = sizeof Message - 1;
   memcpy(Data, Message, *Length);
   return 1;
}

