{\displaystyle 6}

;




588225


{\displaystyle 588225}

 has additive persistence 



2


{\displaystyle 2}

 and digital root of 



3


{\displaystyle 3}

;




393900588225


{\displaystyle 393900588225}

 has additive persistence 



2


{\displaystyle 2}

 and digital root of 



9


{\displaystyle 9}

;
The digital root may be calculated in bases other than 10.



See

 Casting out nines for this wiki's use of this procedure.
 Digital root/Multiplicative digital root
 Sum digits of an integer
 Digital root sequence on OEIS
 Additive persistence sequence on OEIS
 Iterated digits squaring

code:
#include <stdio.h>
#include <stdlib.h>
#include <math.h>

typedef struct {
   int addpers;
   int digrt;
} digitalRootBase_t;

digitalRootBase_t digitalRootBase(int x, int b) {
   digitalRootBase_t rootobj;
   if (x < b) {
      rootobj.addpers = 0;
      rootobj.digrt = x;
      return rootobj;
   }
   int fauxroot = 0;
   while (b <= x) {
      x = (x / b) | 0;
      fauxroot += x % b;
   }
   rootobj = digitalRootBase(fauxroot,b);
   rootobj.addpers += 1;
   return rootobj;
}

int main(int argc, char *argv[]) {
   int x = atoi(argv[1]);
   int b = atoi(argv[2]);
   digitalRootBase_t rootobj = digitalRootBase(x,b);
   printf("addpers = %d\n", rootobj.addpers);
   printf("digrt = %d\n", rootobj.digrt);
   return 0;
}

#include <stdio.h>
#include <string.h>
#include <ctype.h>
 
int sedol_checksum(const char * sedol, char * errorMessage)
{
    if(strlen(sedol)!= 6)
    {
        strcpy(errorMessage, "length of sedol string!= 6");
        return 0;
    }
 
    const char * valid_chars = "BCDFGHJKLMNPQRSTVWXYZ0123456789";
    if(strspn(sedol, valid_chars)!= 6)
    {
        strcpy(errorMessage, "sedol string contains disallowed characters");
        return 0;
    }
 
    const int weights[] = {1,3,1,7,3,9};    
    int weighted_sum = 0;
    for(int i = 0; i < 6; ++i)
    {
        int weight = weights[i];
        int c = sedol[i];
        if(isalpha(c))
            c = c - 'A' + 10;
        else
            c = c - '0';
        weighted_sum += c * weight;
    }
    return (10 - (weighted_sum % 10)) % 10;
}
 
int main()
{
    const char * inputs[] = {
       "710889", "B0YBKJ", "406566", "B0YBLH", "228276", "B0YBKL", 
       "557910", "B0YBKR", "585284", "B0YBKT", "B00030"
   }; 
   for(int i = 0; i < sizeof(inputs)/sizeof(inputs[0]); ++i)
   {
        char errorMessage[100];
        int sum = sedol_checksum(inputs[i], errorMessage);
        if(errorMessage[0])
            printf("error for sedol: %s message: %s\n", inputs[i], errorMessage);
        else
            printf("%s%d\n", inputs[i], sum);
   }
   return 0;
}

