typedef enum {
    Encrypt,
    Decrypt
} Mode;
 
const char *lAlphabet = "HXUCZVAMDSLKPEFJRIGTWOBNYQ";
const char *rAlphabet = "PTLNBQDEOYSFAVZKGJRIHWXUMC";
 
char *Chao(char *text, Mode mode, int showSteps) {
    int len = strlen(text);
    char *left = malloc(27);
    char *right = malloc(27);
    char *eText = malloc(len + 1);
    char *temp = malloc(27);
    strcpy(left, lAlphabet);
    strcpy(right, rAlphabet);
    int i;
    for (i = 0; i < len; i++) {
        if (showSteps) {
            printf("%s %s\n", left, right);
        }
        int index;
        if (mode == Encrypt) {
            index = strchr(right, text[i]) - right;
            eText[i] = left[index];
        } else {
            index = strchr(left, text[i]) - left;
            eText[i] = right[index];
        }
        if (i == len - 1) {
            break;
        }
 
        // permute left
        int j;
        for (j = index; j < 26; j++) {
            temp[j - index] = left[j];
        }
        for (j = 0; j < index; j++) {
            temp[26 - index + j] = left[j];
        }
        char store = temp[1];
        for (j = 2; j < 14; j++) {
            temp[j - 1] = temp[j];
        }
        temp[13] = store;
        strcpy(left, temp);
 
        // permute right
 
        for (j = index; j < 26; j++) {
            temp[j - index] = right[j];
        }
        for (j = 0; j < index; j++) {
            temp[26 - index + j] = right[j];
        }
        store = temp[0];
        for (j = 1; j < 26; j++) {
            temp[j - 1] = temp[j];
        }
        temp[25] = store;
        store = temp[2];
        for (j = 3; j < 14; j++) {
            temp[j - 1] = temp[j];
        }
        temp[13] = store;
        strcpy(right, temp);
    }
    eText[len] = '\0';
    return eText;
}
 
int main() {
    char *plainText = "WELLDONEISBETTERTHANWELLSAID";
    printf("The original plaintext is : %s\n", plainText);
    printf("\nThe left and right alphabets after each permutation ");
    printf("during encryption are :\n\n");
    char *cipherText = Chao(plainText, Encrypt, 1);
    printf("\nThe ciphertext is : %s\n", cipherText);
    char *plainText2 = Chao(cipherText, Decrypt, 0);
    printf("\nThe recovered plaintext is : %s\n", plainText2);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <gmp.h>
 
typedef mpz_t big_int;
 
big_int partitions(int n) {
    big_int *p = malloc((n + 1) * sizeof(big_int));
    mpz_init(p[0]);
    mpz_set_ui(p[0], 1);
    for (int i = 1; i <= n; ++i) {
        mpz_init(p[i]);
        for (int k = 1;; ++k) {
            int j = (k * (3*k - 1))/2;
            if (j > i)
                break;
            if (k & 1)
                mpz_add(p[i], p[i], p[i - j]);
            else
                mpz_sub(p[i], p[i], p[i - j]);
            j = (k * (3*k + 1))/2;
            if (j > i)
                break;
            if (k & 1)
                mpz_add(p[i], p[i], p[i - j]);
            else
                mpz_sub(p[i], p[i], p[i - j]);
        }
    }
    return p[n];
}
 
int main() {
    clock_t start = clock();
    big_int result = partitions(6666);
    clock_t end = clock();
    double ms = (double)(end - start) / CLOCKS_PER_SEC * 1000;
    gmp_printf("%Zd\n", result);
    printf("elapsed time: %f milliseconds\n", ms);
    return 0;
}

