#include <stdio.h>
#include <stdlib.h>

int factors(int n) {
  int factors = 0;
  for (int i = 1; i <= n; i++) {
    if (n % i == 0) {
      factors++;
    }
  }
  return factors;
}

int* generateAntiprimes(int n) {
  int* antiprimes = malloc(n * sizeof(int));
  int maxFactors = 0;
  for (int i = 1; i < n; i++) {
    int ifactors = factors(i);
    if (ifactors > maxFactors) {
      antiprimes[i] = i;
      maxFactors = ifactors;
    }
  }
  return antiprimes;
}

int main() {
  int number;
  printf("Enter a number: ");
  scanf("%d", &number);
  int* antiprimes = generateAntiprimes(number);
  for (int i = 0; i < number; i++) {
    printf("%d\n", antiprimes[i]);
  }
  free(antiprimes);
  return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
 
typedef struct Range {
    double left;
    double right;
} Range;
 
typedef struct RangeSorter {
    int (*compare)(Range o1, Range o2);
} RangeSorter;
 
typedef struct RangeConsolidation {
    Range (*consolidate)(Range range);
} RangeConsolidation;
 
int compare(Range o1, Range o2) {
    return (int) (o1.left - o2.left);
}
 
Range consolidate(Range range) {
    //  no overlap
    if ( this.right < range.left ) {
        return NULL;
    }
    //  no overlap
    if ( range.right < this.left ) {
        return NULL;
    }
    //  contained
    if ( this.left <= range.left && this.right >= range.right ) {
        return this;
    }
    //  contained
    if ( range.left <= this.left && range.right >= this.right ) {
        return range;
    }
    //  overlap
    if ( this.left <= range.left && this.right <= range.right ) {
        return new Range(this.left, range.right);
    }
    //  overlap
    if ( this.left >= range.left && this.right >= range.right ) {
        return new Range(range.left, this.right);
    }
    throw new RuntimeException("ERROR:  Logic invalid.");
}
 
int main(int argc, char *argv[]) {
    Range ranges[] = {
        {1.1, 2.2},
        {6.1, 7.2},
        {7.2, 8.3},
        {4, 3},
        {2, 1},
        {4, 3},
        {2, 1},
        {-1, -2},
        {3.9, 10},
        {1, 3},
        {-6, -1},
        {-4, -5},
        {8, 2},
        {-6, -6},
        {1, 1},
        {1, 2},
        {1, 2},
        {3, 4},
        {1.5, 3.5},
        {1.2, 2.5}
    };
    int i;
    for (i = 0; i < sizeof(ranges) / sizeof(Range); i++) {
        printf("ranges = %-70s, colsolidated = %s%n", ranges, Range.consolidate(ranges));
    }
    return 0;
}

