#include <stdio.h>
#include <stdbool.h>
 
bool is_prime(unsigned int n) {
    if (n < 2) {
        return false;
    }
    if (n % 2 == 0) {
        return n == 2;
    }
    if (n % 3 == 0) {
        return n == 3;
    }
    unsigned int p = 5;
    while (p * p <= n) {
        if (n % p == 0) {
            return false;
        }
        p += 2;
        if (n % p == 0) {
            return false;
        }
        p += 4;
    }
    return true;
}
 
bool is_left_truncatable(unsigned int p) {
    unsigned int n = 10;
    unsigned int q = p;
    while (p > n) {
        if (!is_prime(p % n) || q == p % n) {
            return false;
        }
        q = p % n;
        n *= 10;
    }
    return true;
}
 
bool is_right_truncatable(unsigned int p) {
    unsigned int q = p / 10;
    while (q > 0) {
        if (!is_prime(q)) {
            return false;
        }
        q /= 10;
    }
    return true;
}
 
int main() {
    unsigned int limit = 1000000;
    unsigned int largest_left = 0;
    unsigned int largest_right = 0;
    unsigned int p = limit;
    while (p >= 2) {
        if (is_prime(p) && is_left_truncatable(p)) {
            largest_left = p;
            break;
        }
        p -= 1;
    }
    printf("Largest left truncatable prime is %u\n", largest_left);
    p = limit;
    while (p >= 2) {
        if (is_prime(p) && is_right_truncatable(p)) {
            largest_right = p;
            break;
        }
        p -= 1;
    }
    printf("Largest right truncatable prime is %u\n", largest_right);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <math.h>
#include <stdbool.h>
 
typedef struct {
  int prime;
  int freq;
} prime_t;
 
typedef struct {
  int size;
  prime_t *primes;
} primes_t;
 
primes_t *prime_division(int n) {
  primes_t *primes = malloc(sizeof(primes_t));
  primes->size = 0;
  primes->primes = malloc(sizeof(prime_t));
  int prime = 2;
  while (n > 1) {
    if (n % prime == 0) {
      primes->primes[primes->size].prime = prime;
      primes->primes[primes->size].freq = 0;
      while (n % prime == 0) {
        primes->primes[primes->size].freq++;
        n /= prime;
      }
      primes->size++;
      primes->primes = realloc(primes->primes, (primes->size + 1) * sizeof(prime_t));
    }
    prime++;
  }
  return primes;
}
 
int *proper_divisors(int n) {
  if (n == 1) {
    return NULL;
  }
  primes_t *primes = prime_division(n);
  int *divisors = malloc(sizeof(int));
  divisors[0] = 1;
  int size = 1;
  for (int i = 0; i < primes->size; i++) {
    int prime = primes->primes[i].prime;
    int freq = primes->primes[i].freq;
    int *new_divisors = malloc(sizeof(int));
    new_divisors[0] = 1;
    int new_size = 1;
    for (int j = 0; j < freq; j++) {
      for (int k = 0; k < size; k++) {
        new_divisors[new_size] = divisors[k] * prime;
        new_size++;
        new_divisors = realloc(new_divisors, (new_size + 1) * sizeof(int));
      }
      prime *= primes->primes[i].prime;
    }
    for (int j = 0; j < new_size; j++) {
      divisors[size] = new_divisors[j];
      size++;
      divisors = realloc(divisors, (size + 1) * sizeof(int));
    }
    free(new_divisors);
  }
  free(primes->primes);
  free(primes);
  divisors[size] = 0;
  return divisors;
}
 
typedef struct {
  int n;
  int sum;
} abundant_t;
 
abundant_t *generator_odd_abundants(int from) {
  if (from % 2 == 0) {
    from++;
  }
  abundant_t *abundants = malloc(sizeof(abundant_t));
  int size = 0;
  for (int n = from; n < INT_MAX; n += 2) {
    int *divisors = proper_divisors(n);
    int sum = 0;
    for (int i = 0; divisors[i]!= 0; i++) {
      sum += divisors[i];
    }
    free(divisors);
    if (sum > n) {
      abundants[size].n = n;
      abundants[size].sum = sum;
      size++;
      abundants = realloc(abundants, (size + 1) * sizeof(abundant_t));
    }
  }
  abundants[size].n = 0;
  return abundants;
}
 
int main(void) {
  abundant_t *abundants = generator_odd_abundants(1);
  for (int i = 0; abundants[i].n!= 0; i++) {
    printf("%d with sum %d\n", abundants[i].n, abundants[i].sum);
  }
  printf("\n%d with sum %d\n", abundants[999].n, abundants[999].sum);
  free(abundants);
  abundants = generator_odd_abundants(1000000000);
  printf("\n%d with sum %d\n", abundants[0].n, abundants[0].sum);
  free(abundants);
  return 0;
}

#include <stdio.h>
