int main(int argc, char *argv[]) {
    int a[] = {1, 2, 3, 4, 5};
    int a_size = sizeof(a) / sizeof(a[0]);
    printf("Array       : ");
    for (int i = 0; i < a_size; i++) {
        printf("%d", a[i]);
        if (i < a_size - 1) {
            printf(", ");
        }
    }
    printf("\n");
    int sum = 0;
    for (int i = 0; i < a_size; i++) {
        sum += a[i];
    }
    printf("Sum         : %d\n", sum);
    int difference = 0;
    for (int i = 0; i < a_size; i++) {
        difference -= a[i];
    }
    printf("Difference  : %d\n", difference);
    int product = 1;
    for (int i = 0; i < a_size; i++) {
        product *= a[i];
    }
    printf("Product     : %d\n", product);
    int minimum = a[0];
    for (int i = 1; i < a_size; i++) {
        if (a[i] < minimum) {
            minimum = a[i];
        }
    }
    printf("Minimum     : %d\n", minimum);
    int maximum = a[0];
    for (int i = 1; i < a_size; i++) {
        if (a[i] > maximum) {
            maximum = a[i];
        }
    }
    printf("Maximum     : %d\n", maximum);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <math.h>
#include <cairo.h>
 
#define WIDTH 380
#define HEIGHT 380
 
typedef struct {
    double x;
    double y;
} Point;
 
Point archimedeanPoint(int degrees)
{
    const double a = 1;
    const double b = 9;
    double t = degrees * M_PI / 180;
    double r = a + b * t;
    return (Point) {.x = WIDTH / 2 + r * cos(t),.y = HEIGHT / 2 + r * sin(t) };
}
 
int main(int argc, char *argv[])
{
    cairo_surface_t *surface = cairo_image_surface_create(CAIRO_FORMAT_ARGB32, WIDTH, HEIGHT);
    cairo_t *cr = cairo_create(surface);
    cairo_set_source_rgb(cr, 1, 1, 1);
    cairo_paint(cr);
    cairo_set_source_rgb(cr, 1, 0.2, 0);
    cairo_set_line_width(cr, 1.5);
 
    Point p0 = {.x = WIDTH / 2,.y = HEIGHT / 2 };
    for (int i = 0; i < 360 * 3; i++) {
        Point p1 = archimedeanPoint(i);
        cairo_move_to(cr, p0.x, p0.y);
        cairo_line_to(cr, p1.x, p1.y);
        cairo_stroke(cr);
        p0 = p1;
    }
 
    cairo_surface_write_to_png(surface, "archimedes-c.png");
    cairo_destroy(cr);
    cairo_surface_destroy(surface);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
 
typedef struct {
    size_t len;
    size_t cap;
    unsigned int *data;
} Vec;
 
Vec *vec_new(void) {
    Vec *v = malloc(sizeof(Vec));
    v->len = 0;
    v->cap = 1;
    v->data = malloc(sizeof(unsigned int) * v->cap);
    return v;
}
 
void vec_push(Vec *v, unsigned int val) {
    if (v->len == v->cap) {
        v->cap *= 2;
        v->data = realloc(v->data, sizeof(unsigned int) * v->cap);
    }
    v->data[v->len++] = val;
}
 
void vec_free(Vec *v) {
    free(v->data);
    free(v);
}
 
Vec *hailstone(unsigned int start) {
    Vec *res = vec_new();
    unsigned int next = start;
 
    vec_push(res, start);
 
    while (next!= 1) {
        next = next % 2 == 0? next/2 : 3*next+1;
        vec_push(res, next);
    }
    return res;
}
 
int main(void) {
    unsigned int test_num = 27;
    Vec *test_hailseq = hailstone(test_num);
 
    printf("For %u number of elements is %zu\n", test_num, test_hailseq->len);
 
    char fst_slice[100] = "";
    char last_slice[100] = "";
    for (size_t i = 0; i < 4; i++) {
        char tmp[10];
        sprintf(tmp, "%u, ", test_hailseq->data[i]);
        strcat(fst_slice, tmp);
    }
    for (size_t i = test_hailseq->len-4; i < test_hailseq->len; i++) {
        char tmp[10];
        sprintf(tmp, "%u, ", test_hailseq->data[i]);
        strcat(last_slice, tmp);
    }
    printf("  hailstone starting with %s ending with %s\n", fst_slice, last_slice);
 
    unsigned int max_range = 100000;
    unsigned int max_len = 0;
    unsigned int max_seed = 0;
    for (unsigned int i_seed = 1; i_seed < max_range; i_seed++) {
        Vec *i_hailseq = hailstone(i_seed);
        unsigned int i_len = i_hailseq->len;
 
        if (i_len > max_len) {
            max_len = i_len;
            max_seed = i_seed;
        }
        vec_free(i_hailseq);
    }
    printf("Longest sequence is %u element long for seed %u\n", max_len, max_seed);
 
    vec_free(test_hailseq);
    return 0;
}

#include <stdio.h>
#include <math.h>
#include <stdlib.h>
#include <time.h>
 
double approx_pi(int throws) {
  int times_inside = 0;
  int i;
  for (i = 0; i < throws; i++) {
    double x = (double)rand() / RAND_MAX;
    double y = (double)rand() / RAND_MAX;
    if (hypot(x, y) <= 1.0) {
      times_inside++;
    }
  }
  return 4.0 * times_inside / throws;
}
 
int main() {
  int n;
  int samples[] = {1000, 10000, 100000, 1000000, 10000000};
  srand(time(NULL));
  for (n = 0; n < 5; n++) {
    printf("%8d samples: PI = %f\n", samples[n], approx_pi(samples[n]));
  }
  return 0;
}

void draw_circle(int centerX, int centerY, int radius, int color)
{
    int d = (5 - radius * 4) / 4;
    int x = 0;
    int y = radius;

    do
    {
        // ensure index is in range before setting (depends on your image implementation)
        // in this case we check if the pixel location is within the bounds of the image before setting the pixel
        if (centerX + x >= 0 && centerX + x <= image.Width - 1 && centerY + y >= 0 && centerY + y <= image.Height - 1) image[centerX + x, centerY + y] = color;
        if (centerX + x >= 0 && centerX + x <= image.Width - 1 && centerY - y >= 0 && centerY - y <= image.Height - 1) image[centerX + x, centerY - y] = color;
        if (centerX - x >= 0 && centerX - x <= image.Width - 1 && centerY + y >= 0 && centerY + y <= image.Height - 1) image[centerX - x, centerY + y] = color;
        if (centerX - x >= 0 && centerX - x <= image.Width - 1 && centerY - y >= 0 && centerY - y <= image.Height - 1) image[centerX - x, centerY - y] = color;
        if (centerX + y >= 0 && centerX + y <= image.Width - 1 && centerY + x >= 0 && centerY + x <= image.Height - 1) image[centerX + y, centerY + x] = color;
        if (centerX + y >= 0 && centerX + y <= image.Width - 1 && centerY - x >= 0 && centerY - x <= image.Height - 1) image[centerX + y, centerY - x] = color;
        if (centerX - y >= 0 && centerX - y <= image.Width - 1 && centerY + x >= 0 && centerY + x <= image.Height - 1) image[centerX - y, centerY + x] = color;
        if (centerX - y >= 0 && centerX - y <= image.Width - 1 && centerY - x >= 0 && centerY - x <= image.Height - 1) image[centerX - y, centerY - x] = color;
        if (d < 0)
        {
            d += 2 * x + 1;
        }
        else
        {
            d += 2 * (x - y) + 1;
            y--;
        }
        x++;
    } while (x <= y);
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
 
typedef struct {
    int stem;
    int leaf;
} StemLeaf;
 
int compare(const void *a, const void *b)
{
    const StemLeaf *x = a;
    const StemLeaf *y = b;
    return x->stem - y->stem;
}
 
int main()
{
    const int dataset[] = {
        12,127, 28, 42, 39,113, 42, 18, 44,118, 44, 37,113,124, 37, 48,127, 36,
        29, 31,125,139,131,115,105,132,104,123, 35,113,122, 42,117,119, 58,109,
        23,105, 63, 27, 44,105, 99, 41,128,121,116,125, 32, 61, 37,127, 29,113,
        121, 58,114,126, 53,114, 96, 25,109,  7, 31,141, 46, 13, 27, 43,117,116,
        27,  7, 68, 40, 31,115,124, 42,128, 52, 71,118,117, 38, 27,106, 33,117,
        116,111, 40,119, 47,105, 57,122,109,124,115, 43,120, 43, 27, 27, 18, 28,
        48,125,107,114, 34,133, 45,120, 30,127, 31,116,146
    };
    const int datasize = sizeof(dataset) / sizeof(dataset[0]);
    StemLeaf stemplot[datasize];
    int i;
 
    for (i = 0; i < datasize; ++i)
    {
        stemplot[i].stem = dataset[i] / 10;
        stemplot[i].leaf = dataset[i] % 10;
    }
 
    qsort(stemplot, datasize, sizeof(StemLeaf), compare);
 
    int lo = stemplot[0].stem; // minimum stem value
    int hi = stemplot[datasize - 1].stem; // maximum stem value
 
    for (i = 0; lo <= hi; ++lo)
    {
        printf("%2d |", lo); // print stem
 
        // while (there are more stems) and (stem is equal to lo)
        for ( ; i < datasize && stemplot[i].stem == lo; ++i)
        {
            printf(" %d", stemplot[i].leaf); // print leaf
        }
 
        printf("\n");
    }
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <regex.h>
 
#define MAX_LINE_LEN 1024
#define MAX_RULES 100
#define MAX_TESTS 100
 
/* rulesets assumed to be separated by a blank line in file */
int read_rules(char *path, char rules[MAX_RULES][MAX_LINE_LEN]) {
    FILE *fp = fopen(path, "r");
    int i = 0;
    while (fgets(rules[i], MAX_LINE_LEN, fp)) {
        if (rules[i][0] == '\n') {
            rules[i][0] = '\0';
            break;
        }
        i++;
    }
    fclose(fp);
    return i;
}
 
/* tests assumed to be on consecutive lines */
int read_tests(char *path, char tests[MAX_TESTS][MAX_LINE_LEN]) {
    FILE *fp = fopen(path, "r");
    int i = 0;
    while (fgets(tests[i], MAX_LINE_LEN, fp)) {
        i++;
    }
    fclose(fp);
    return i;
}
 
int main(int argc, char *argv[]) {
    char rules[MAX_RULES][MAX_LINE_LEN];
    char tests[MAX_TESTS][MAX_LINE_LEN];
    int nrules = read_rules("markov_rules.txt", rules);
    int ntests = read_tests("markov_tests.txt", tests);
    regex_t re;
    regcomp(&re, "^([^#]*?)\\s+->\\s+(\\.?)(.*)", REG_EXTENDED);
    regmatch_t matches[4];
    int i, j;
    for (i = 0; i < ntests; i++) {
        char *test = tests[i];
        char *orig_test = strdup(test);
        int redo;
        do {
            redo = 0;
            for (j = 0; j < nrules; j++) {
                char *rule = rules[j];
                if (regexec(&re, rule, 4, matches, 0) == 0) {
                    char *match = strndup(rule + matches[1].rm_so, matches[1].rm_eo - matches[1].rm_so);
                    char *replace = strndup(rule + matches[3].rm_so, matches[3].rm_eo - matches[3].rm_so);
                    char *new_test = str_replace(test, match, replace);
                    if (new_test!= NULL) {
                        free(test);
                        test = new_test;
                        if (rule[matches[2].rm_so] == '.') {
                            redo = 0;
                            break;
                        }
                        redo = 1;
                    }
                    free(match);
                    free(replace);
                }
            }
        } while (redo);
        printf("%s\n%s\n\n", orig_test, test);
        free(orig_test);
        free(test);
    }
    regfree(&re);
    return 0;
}

#include <stdio.h>

void insertionSort(int a[], int n) {
    int i, j, k;
    for (i = 0; i < n; i++) {
        k = a[i];
        for (j = i; j > 0 && k < a[j - 1]; j--)
            a[j] = a[j - 1];
        a[j] = k;
    }
}

int main() {
    int a[] = {4, 65, 2, -31, 0, 99, 83, 782, 1};
    int n = sizeof(a) / sizeof(a[0]);
    insertionSort(a, n);
    for (int i = 0; i < n; i++)
        printf("%d ", a[i]);
    return 0;
}

