int main(void) {
  char *wheel = "ndeokgelw";
  int wheel_size = strlen(wheel);
  char middle = wheel[4];
  char *word;
  char *res = NULL;
  char *p;
  int i;
  int len;
  int count = 0;
  FILE *fp = fopen("unixdict.txt", "r");
  if (fp == NULL) {
    perror("unixdict.txt");
    exit(EXIT_FAILURE);
  }
  while (fgets(word, 100, fp)!= NULL) {
    len = strlen(word);
    if (len < 3 || len > wheel_size) continue;
    if (strchr(word, middle) == NULL) continue;
    for (i = 0; i < wheel_size; i++) {
      p = strchr(word, wheel[i]);
      if (p!= NULL) {
        *p = '\0';
      }
    }
    if (strlen(word) == 0) {
      count++;
      res = realloc(res, count * sizeof(char *));
      res[count - 1] = malloc(len + 1);
      strcpy(res[count - 1], word);
    }
  }
  for (i = 0; i < count; i++) {
    printf("%s\n", res[i]);
    free(res[i]);
  }
  free(res);
  fclose(fp);
  return 0;
}

