#include <math.h>

void main(int argc, char *argv[]) {
    int i;
    for (i = 1; i < argc; i++) {
        Triangle(atoi(argv[i]));
    }
}

void Triangle(int n) {
    printf("%d rows:\n", n);
    int printMe = 1;
    int printed = 0;
    int row = 1;
    while (row <= n) {
        int cols = ceil(log10(n * (n - 1) / 2 + printed + 2.0));
        printf("%*d ", cols, printMe);
        if (++printed == row) { printf("\n"); row++; printed = 0; }
        printMe++;
    }
}

#include <stdio.h>
#include <stdlib.h>
#include <math.h>
#include <string.h>
 
typedef unsigned int uint;
 
uint powr[10];
int digs[10];
 
int getDigs( uint st )
{
	memset( digs, 0, 10 * sizeof( int ) );
	int r = 0;
	while( st )
	{
		digs[st % 10]++;
		st /= 10;
		r++;
	}
	return r;
}
 
void fillPower( int z )
{
	for( int i = 1; i < 10; i++ )
		powr[i] = pow( (float)i, z );
}
 
int main( int argc, char* argv[] )
{
	uint st = 0, tl; int pwr = 0, len;
	while( 1 )
	{
		len = getDigs( st );
		if( pwr!= len )
		{
			pwr = len;
			fillPower( pwr );
		}
		tl = 0;
		for( int i = 1; i < 10; i++ )
			tl += powr[i] * digs[i];
 
		if( tl == st ) printf( "%d ", st );
		st++;
	}
	return system( "pause" );
}

#include <stdio.h>
#include <stdint.h>
 
uint64_t pows[32];
uint64_t doublings[32];
 
void init_pows() {
    for (int i = 0; i < 32; i++) {
        pows[i] = 1 << i;
    }
}
 
void init_doublings(uint64_t divisor) {
    for (int i = 0; i < 32; i++) {
        doublings[i] = divisor << i;
    }
}
 
void egyptian_divide(uint64_t dividend, uint64_t divisor, uint64_t *answer, uint64_t *sum) {
    init_pows();
    init_doublings(divisor);
 
    for (int i = 31; i >= 0; i--) {
        if (*sum + doublings[i] < dividend) {
            *answer += pows[i];
            *sum += doublings[i];
        }
    }
}
 
int main() {
    uint64_t div, rem;
    egyptian_divide(580, 34, &div, &rem);
    printf("580 divided by 34 is %lu remainder %lu\n", div, rem);
}

#include <stdio.h>
