int main(int argc, char *argv[])
{
	printf("%f\n", DotProduct((float[]){1, 3, -5}, (float[]){4, -2, -1}));
	return 0;
}
 
float DotProduct(float vec1[], float vec2[])
{
	if (vec1 == NULL)
		return 0;
 
	if (vec2 == NULL)
		return 0;
 
	if (sizeof(vec1)!= sizeof(vec2))
		return 0;
 
	float tVal = 0;
	for (int x = 0; x < sizeof(vec1); x++)
	{
		tVal += vec1[x] * vec2[x];
	}
 
	return tVal;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
