void placeRandomly(char* p, char c)
{
	int loc = rand() % 8;
	if (!p[loc])
		p[loc] = c;
	else
		placeRandomly(p, c);    // try again
}
int placeFirst(char* p, char c, int loc)
{
	while (p[loc]) ++loc;
	p[loc] = c;
	return loc;
}
 
char* startPos()
{
	char p[8]; memset(p, 0, 8);
 
	// bishops on opposite color
	p[2 * (rand() % 4)] = 'B';
	p[2 * (rand() % 4) + 1] = 'B';
 
	// queen knight knight, anywhere
	for (char c : "QNN")
		placeRandomly(p, c);
 
	// rook king rook, in that order
	placeFirst(p, 'R', placeFirst(p, 'K', placeFirst(p, 'R', 0)));
 
	return p;
}
 
void generate(int c)
{
	for (int x = 0; x < c; x++)
		printf("%s\n", startPos());
}
 
int main(int argc, char* argv[])
{
	srand(time(NULL));
	generate(10);
	printf("\n\n");
	return system("pause");
}

#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
 
typedef struct {
    char *buf;
    int size;
    int head;
    int tail;
    int full;
    int empty;
    pthread_mutex_t *mutex;
    pthread_cond_t *notFull;
    pthread_cond_t *notEmpty;
} queue_t;
 
typedef struct {
    queue_t *lines;
    queue_t *count;
} args_t;
 
void queue_init(queue_t *q, int size) {
    q->buf = (char *) malloc(size);
    q->size = size;
    q->head = 0;
    q->tail = 0;
    q->full = 0;
    q->empty = 1;
    q->mutex = (pthread_mutex_t *) malloc(sizeof(pthread_mutex_t));
    pthread_mutex_init(q->mutex, NULL);
    q->notFull = (pthread_cond_t *) malloc(sizeof(pthread_cond_t));
    pthread_cond_init(q->notFull, NULL);
    q->notEmpty = (pthread_cond_t *) malloc(sizeof(pthread_cond_t));
    pthread_cond_init(q->notEmpty, NULL);
}
 
void queue_destroy(queue_t *q) {
    free(q->buf);
    pthread_mutex_destroy(q->mutex);
    free(q->mutex);
    pthread_cond_destroy(q->notFull);
    free(q->notFull);
    pthread_cond_destroy(q->notEmpty);
    free(q->notEmpty);
}
 
void queue_put(queue_t *q, char *data) {
    pthread_mutex_lock(q->mutex);
    while (q->full) {
        pthread_cond_wait(q->notFull, q->mutex);
    }
    q->buf[q->tail] = data;
    q->tail++;
    if (q->tail == q->size) {
        q->tail = 0;
    }
    if (q->tail == q->head) {
        q->full = 1;
    }
    q->empty = 0;
    pthread_cond_signal(q->notEmpty);
    pthread_mutex_unlock(q->mutex);
}
 
char queue_get(queue_t *q) {
    char data;
    pthread_mutex_lock(q->mutex);
    while (q->empty) {
        pthread_cond_wait(q->notEmpty, q->mutex);
    }
    data = q->buf[q->head];
    q->head++;
    if (q->head == q->size) {
        q->head = 0;
    }
    if (q->head == q->tail) {
        q->empty = 1;
    }
    q->full = 0;
    pthread_cond_signal(q->notFull);
    pthread_mutex_unlock(q->mutex);
    return data;
}
 
void *read(void *args) {
    args_t *a = (args_t *) args;
    queue_t *lines = a->lines;
    queue_t *count = a->count;
    FILE *file = fopen("input.txt", "r");
    char line[1024];
    int n = 0;
    while (fgets(line, 1024, file)) {
        queue_put(lines, line);
        n++;
    }
    queue_put(count, n);
    fclose(file);
    return NULL;
}
 
void *write(void *args) {
    args_t *a = (args_t *) args;
    queue_t *lines = a->lines;
    queue_t *count = a->count;
    char line[1024];
    int n = 0;
    while (1) {
        char *line = queue_get(lines);
        if (line == NULL) {
            break;
        }
        printf("%s", line);
        n++;
    }
    queue_put(count, n);
    return NULL;
}
 
int main() {
    queue_t lines;
    queue_t count;
    queue_init(&lines, 1024);
    queue_init(&count, 1024);
    args_t args;
    args.lines = &lines;
    args.count = &count;
    pthread_t reader;
    pthread_t writer;
    pthread_create(&reader, NULL, read, (void *) &args);
    pthread_create(&writer, NULL, write, (void *) &args);
    pthread_join(reader, NULL);
    pthread_join(writer, NULL);
    queue_destroy(&lines);
    queue_destroy(&count);
    return 0;
}

#include <stdio.h>
#include <gmp.h>
 
#define MAX_LEN 81
 
mpz_t power[10];
mpz_t dsum[MAX_LEN + 1];
int cnt[10], len;
 
void check_perm(void)
{
	char s[MAX_LEN + 1];
	int i, c, out[10] = { 0 };
 
	mpz_get_str(s, 10, dsum[0]);
	for (i = 0; s[i]; i++) {
		c = s[i]-'0';
		if (++out[c] > cnt[c]) return;
	}
 
	if (i == len)
		gmp_printf(" %Zd", dsum[0]);
}
 
void narc_(int pos, int d)
{
	if (!pos) {
		check_perm();
		return;
	}
 
	do {
		mpz_add(dsum[pos-1], dsum[pos], power[d]);
		++cnt[d];
		narc_(pos - 1, d);
		--cnt[d];
	} while (d--);
}
 
void narc(int n)
{
	int i;
	len = n;
	for (i = 0; i < 10; i++)
		mpz_ui_pow_ui(power[i], i, n);
 
	mpz_init_set_ui(dsum[n], 0);
 
	printf("length %d:", n);
	narc_(n, 9);
	putchar('\n');
}
 
int main(void)
{
	int i;
 
	for (i = 0; i <= 10; i++)
		mpz_init(power[i]);
	for (i = 1; i <= MAX_LEN; i++) narc(i);
 
	return 0;
}

#include <setjmp.h>
 
enum { MY_EXCEPTION = 1 }; /* any non-zero number */
 
jmp_buf env;
 
void foo()
{
  longjmp(env, MY_EXCEPTION); /* throw MY_EXCEPTION */
}
 
void call_foo()
{
  switch (setjmp(env)) {
  case 0:                     /* try */
    foo();
    break;
  case MY_EXCEPTION:          /* catch MY_EXCEPTION */
    /* handle exceptions of type MY_EXCEPTION */
    break;
  default:
    /* handle any type of exception not handled by above catches */
    /* note: if this "default" section is not included, that would be equivalent to a blank "default" section */
    /* i.e. any exception not caught above would be caught and ignored */
    /* there is no way to "let the exception through" */
  }
}

