#include <stdio.h>
#include <ctype.h>
 
int can_make_words(char **b, char *word)
{
	int i, ret = 0, c = toupper(*word);
 
#define SWAP(a, b) if (a != b) { char * tmp = a; a = b; b = tmp; }
 
	if (!c) return 1;
	if (!b[0]) return 0;
 
	for (i = 0; b[i] && !ret; i++) {
		if (b[i][0] != c && b[i][1] != c) continue;
		SWAP(b[i], b[0]);
		ret = can_make_words(b + 1, word + 1);
		SWAP(b[i], b[0]);
	}
 
	return ret;
}
 
int main(void)
{
	char* blocks[] = {
		"BO", "XK", "DQ", "CP", "NA", 
		"GT", "RE", "TG", "QD", "FS", 
		"JW", "HU", "VI", "AN", "OB", 
		"ER", "FS", "LY", "PC", "ZM",
		0 };
 
	char *words[] = {
		"", "A", "BARK", "BOOK", "TREAT", "COMMON", "SQUAD", "Confuse", 0
	};
 
	char **w;
	for (w = words; *w; w++)
		printf("%s\t%d\n", *w, can_make_words(blocks, *w));
 
	return 0;
}

#include <stdbool.h>
#include <stdio.h>
 
#define MAX_WORD 80
#define LETTERS 26
 
bool is_letter(char c) { return c >= 'a' && c <= 'z'; }
 
int index(char c) { return c - 'a'; }
 
void word_wheel(const char* letters, char central, int min_length, FILE* dict) {
    int max_count[LETTERS] = { 0 };
    for (const char* p = letters; *p; ++p) {
        char c = *p;
        if (is_letter(c))
            ++max_count[index(c)];
    }
    char word[MAX_WORD + 1] = { 0 };
    while (fgets(word, MAX_WORD, dict)) {
        int count[LETTERS] = { 0 };
        for (const char* p = word; *p; ++p) {
            char c = *p;
            if (c == '\n') {
                if (p >= word + min_length && count[index(central)] > 0)
                    printf("%s", word);
            } else if (is_letter(c)) {
                int i = index(c);
                if (++count[i] > max_count[i]) {
                    break;
                }
            } else {
                break;
            }
        }
    }
}
 
int main(int argc, char** argv) {
    const char* dict = argc == 2 ? argv[1] : "unixdict.txt";
    FILE* in = fopen(dict, "r");
    if (in == NULL) {
        perror(dict);
        return 1;
    }
    word_wheel("ndeokgelw", 'k', 3, in);
    fclose(in);
    return 0;
}

