#include <semaphore.h>
#include <pthread.h>
#include <stdlib.h>
#include <stdio.h>
#include <unistd.h>
 
sem_t sem;
int count = 3;
 
/* the whole point of a semaphore is that you don't count it:
 * p/v are atomic.  Unless it's locked while you are doing
 * something with the count, the value is only informative */
#define getcount() count
void acquire()
{
	sem_wait(&sem);
	count--;
}
 
void release()
{
	count++;
	sem_post(&sem);
}
 
void* work(void * id)
{
	int i = 10;
	while (i--) {
		acquire();
		printf("#%d acquired sema at %d\n", *(int*)id, getcount());
		usleep(rand() % 4000000); /* sleep 2 sec on average */
		release();
		usleep(0);  /* effectively yield */
	}
	return 0;
}
 
int main()
{
	pthread_t th[4];
	int i, ids[] = {1, 2, 3, 4};
 
	sem_init(&sem, 0, count);
 
	for (i = 4; i--;) pthread_create(th + i, 0, work, ids + i);
	for (i = 4; i--;) pthread_join(th[i], 0);
	printf("all workers done\n");
 
	return sem_destroy(&sem);
}

#include <stdio.h>
 
// m-th on the reversed kill list; m = 0 is final survivor
int jos(int n, int k, int m) {
	int a;
	for (a = m + 1; a <= n; a++)
		m = (m + k) % a;
	return m;
}
 
typedef unsigned long long xint;
 
// same as jos(), useful if n is large and k is not
xint jos_large(xint n, xint k, xint m) {
	if (k <= 1) return n - m - 1;
 
	xint a = m;
	while (a < n) {
		xint q = (a - m + k - 2) / (k - 1);
 
		if (a + q > n)	q = n - a;
		else if (!q)	q = 1;
 
		m = (m + q * k) % (a += q);
	}
 
	return m;
}
 
int main(void) {
	xint n, k, i;
 
	n = 41;
	k = 3;
	printf("n = %llu, k = %llu, final survivor: %d\n", n, k, jos(n, k, 0));
 
	n = 9876543210987654321ULL;
	k = 12031;
	printf("n = %llu, k = %llu, three survivors:", n, k);
 
	for (i = 3; i--; )
		printf(" %llu", jos_large(n, k, i));
	putchar('\n');
 
	return 0;
}

