#include <stdio.h>
#include <stdlib.h>
#include <string.h>
 
const char *menu_select(const char *const *items, const char *prompt);
 
int
main(void)
{
	const char *items[] = {"fee fie", "huff and puff", "mirror mirror", "tick tock", NULL};
	const char *prompt = "Which is from the three pigs?";
 
	printf("You chose %s.\n", menu_select(items, prompt));
 
	return EXIT_SUCCESS;
}
 
const char *
menu_select(const char *const *items, const char *prompt)
{
	char buf[BUFSIZ];
	int i;
	int choice;
	int choice_max;
 
	if (items == NULL)
		return NULL;
 
	do {
		for (i = 0; items[i] != NULL; i++) {
			printf("%d) %s\n", i + 1, items[i]);
		}
		choice_max = i;
		if (prompt != NULL)
			printf("%s ", prompt);
		else
			printf("Choice? ");
		if (fgets(buf, sizeof(buf), stdin) != NULL) {
			choice = atoi(buf);
		}
	} while (1 > choice || choice > choice_max);
 
	return items[choice - 1];
}

#include <stdio.h>
 
void pascaltriangle(unsigned int n)
{
  unsigned int c, i, j, k;
 
  for(i=0; i < n; i++) {
    c = 1;
    for(j=1; j <= 2*(n-1-i); j++) printf(" ");
    for(k=0; k <= i; k++) {
      printf("%3d ", c);
      c = c * (i-k)/(k+1);
    }
    printf("\n");
  }
}
 
int main()
{
  pascaltriangle(8);
  return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <locale.h>
 
long prod = 1L, sum = 0L;
 
void process(int j) {
    sum += abs(j);
    if (labs(prod) < (1 << 27) && j) prod *= j;
}
 
long ipow(int n, uint e) {
    long pr = n;
    int i;
    if (e == 0) return 1L;
    for (i = 2; i <= e; ++i) pr *= n;
    return pr;
}
 
int main() {
    int j;
    const int x = 5, y = -5, z = -2;
    const int one = 1, three = 3, seven = 7;
    long p = ipow(11, x);
    for (j = -three; j <= ipow(3, 3); j += three) process(j);
    for (j = -seven; j <= seven; j += x) process(j);
    for (j = 555; j <= 550 - y; ++j) process(j);
    for (j = 22; j >= -28; j -= three) process(j);
    for (j = 1927; j <= 1939; ++j) process(j);
    for (j = x; j >= y; j -= -z) process(j);
    for (j = p; j <= p + one; ++j) process(j);
    setlocale(LC_NUMERIC, "");
    printf("sum  = % 'ld\n", sum);
    printf("prod = % 'ld\n", prod);
    return 0;
}

#include <stdio.h>
 
#define SWAP(r,s)  do{ t=r; r=s; s=t; } while(0)
 
void StoogeSort(int a[], int i, int j) 
{
   int t;
 
   if (a[j] < a[i]) SWAP(a[i], a[j]);
   if (j - i > 1)
   {
       t = (j - i + 1) / 3;
       StoogeSort(a, i, j - t);
       StoogeSort(a, i + t, j);
       StoogeSort(a, i, j - t);
   }
}
 
int main(int argc, char *argv[])
{
   int nums[] = {1, 4, 5, 3, -6, 3, 7, 10, -2, -5, 7, 5, 9, -3, 7};
   int i, n;
 
   n = sizeof(nums)/sizeof(int);
   StoogeSort(nums, 0, n-1);
 
   for(i = 0; i <= n-1; i++)
      printf("%5d", nums[i]);
 
   return 0;
}

#include <stdio.h>
#include <stdlib.h>
 
long long c[100];
 
void coef(int n)
{
	int i, j;
 
	if (n < 0 || n > 63) abort(); // gracefully deal with range issue
 
	for (c[i=0] = 1; i < n; c[0] = -c[0], i++)
		for (c[1 + (j=i)] = 1; j > 0; j--)
			c[j] = c[j-1] - c[j];
}
 
int is_prime(int n)
{
	int i;
 
	coef(n);
	c[0] += 1, c[i=n] -= 1;
	while (i-- && !(c[i] % n));
 
	return i < 0;
}
 
void show(int n)
{
	do printf("%+lldx^%d", c[n], n); while (n--);
}
 
int main(void)
{
	int n;
 
	for (n = 0; n < 10; n++) {
		coef(n);
		printf("(x-1)^%d = ", n);
		show(n);
		putchar('\n');
	}
 
	printf("\nprimes (never mind the 1):");
	for (n = 1; n <= 63; n++)
		if (is_prime(n))
			printf(" %d", n);
 
	putchar('\n');
	return 0;
}

