#include<stdarg.h>
#include<stdio.h>
 
long int factorial(int n){
	if(n>1)
		return n*factorial(n-1);
	return 1;
}
 
long int sumOfFactorials(int num,...){
	va_list vaList;
	long int sum = 0;
 
	va_start(vaList,num);
 
	while(num--)
		sum += factorial(va_arg(vaList,int));
 
	va_end(vaList);
 
	return sum;
}
 
int main()
{
	printf("\nSum of factorials of [1,5] : %ld",sumOfFactorials(5,1,2,3,4,5));
	printf("\nSum of factorials of [3,5] : %ld",sumOfFactorials(3,3,4,5));
	printf("\nSum of factorials of [1,3] : %ld",sumOfFactorials(3,1,2,3));
 
	return 0;
}

#include <stdio.h>
 
int is_leap_year(int year)
{
    return (!(year % 4) && year % 100 || !(year % 400)) ? 1 : 0;
}
 
int main()
{
    int test_case[] = {1900, 1994, 1996, 1997, 2000}, key, end, year;
    for (key = 0, end = sizeof(test_case)/sizeof(test_case[0]); key < end; ++key) {
        year = test_case[key];
        printf("%d is %sa leap year.\n", year, (is_leap_year(year) == 1 ? "" : "not "));
    }
}

