typedef double (*deriv_f)(double, double);
#define FMT " %7.3f"
 
void ivp_euler(deriv_f f, double y, int step, int end_t)
{
	int t = 0;
 
	printf(" Step %2d: ", (int)step);
	do {
		if (t % 10 == 0) printf(FMT, y);
		y += step * f(t, y);
	} while ((t += step) <= end_t);
	printf("\n");
}
 
void analytic()
{
